export const ROZDZIALY = [
  {"nr":"1","tytul":"Makietka коротко","czesc":"Основи","ikona":"ksiazka","sekcje":[{"id":"1.1","tytul":"Що можна зробити в Makietka","html":"<p>Makietka — це редактор видань для друку: книжок, календарів, планерів, блокнотів, запрошень, етикеток — сторінка за сторінкою, як на макеті. Наприкінці ви отримуєте PDF-файл, готовий для друкарні. У ній є все, що потрібно багатосторінковому виданню:</p><ul class=\"punkty\"><li><b>розділи</b> різних форматів — напр. обкладинка з корінцем, розрахованим за кількістю сторінок і папером (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.6\">Обкладинка з корінцем</a>), і блок (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>),</li><li><b>розвороти</b> з дзеркальними полями, як у книжці (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.5\">Розвороти</a>),</li><li><b>шаблони сторінок</b> — фони, нижні колонтитули й номери сторінок, намальовані один раз для багатьох сторінок (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11\">Шаблони сторінок</a>),</li><li><b>стилі тексту</b> — однаковий вигляд для всіх заголовків чи підписів (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.4\">Стилі</a>),</li><li><b>файл для друкарні</b> з вильотом, мітками різу й вбудованими шрифтами, також PDF/X-4 у CMYK (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Експорт у PDF і PNG</a>).</li></ul><p>Сильна сторона Makietka — <b>дані</b>. Сторінку можна повторити для кожного рядка таблиці й вставити в неї значення з цього рядка: так з'являється календар на 365 днів, планер на цілий рік або сто іменних запрошень з одного зразка (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14\">Таблиці даних</a> – <a href=\"#\" data-cel=\"17\">Вигляд із даних</a>).</p><figure><img src=\"img/instrukcja/projekty.png\" alt=\"Ваші проєкти\" loading=\"lazy\"><figcaption>Ваші проєкти</figcaption></figure>"},{"id":"1.2","tytul":"Як побудовано проєкт","html":"<p>Один <b>проєкт</b> — це одне видання. Проєкт складається з:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Частина</th><th>Що це</th></tr></thead><tbody><tr><td><b>Розділи</b></td><td>Частини видання з власним форматом, полями й нумерацією, напр. «Обкладинка» і «Блок».</td></tr><tr><td><b>Сторінки</b></td><td>Сторінки кожного розділу в порядку друку. На сторінках розміщено елементи.</td></tr><tr><td><b>Елементи</b></td><td>Тексти, фігури, лінії, зображення, таблиці й групи.</td></tr><tr><td><b>Шаблони сторінок</b></td><td>Елементи, спільні для багатьох сторінок, — лежать під вмістом сторінки або над ним.</td></tr><tr><td><b>Стилі</b></td><td>Збережений вигляд тексту.</td></tr><tr><td><b>Таблиці даних</b></td><td>Аркуші з даними для полів у тексті та для повторення сторінок.</td></tr><tr><td><b>Зображення</b></td><td>Усі фото й графіка проєкту в одному вікні.</td></tr></tbody></table></div><p>Проєкт зберігається сам, у вашому обліковому записі (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.4\">Збереження</a>).</p>"}]},
  {"nr":"2","tytul":"Проєкти","czesc":"Основи","ikona":"ksiazka","wstep":"Проєкт — це одне видання: тут ви створюєте, відкриваєте, копіюєте й зберігаєте проєкти.","sekcje":[{"id":"2.1","tytul":"Список проєктів","html":"<p>Клацання по картці відкриває проєкт у редакторі — на сторінці, яку ви востаннє редагували на цьому пристрої. Коли у вас ще немає проєктів, список пропонує <span class=\"ui\">Створити проєкт</span>, <span class=\"ui\">З готового шаблону</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.10\">Готові розділи (шаблони документів)</a>) і <span class=\"ui\">Імпортувати з файлу</span>.</p><ul class=\"punkty\"><li><b>Хмаринка</b> біля назви показує, чи зміни вже в обліковому записі: з галочкою — збережено, з годинником — чекають на надсилання, перекреслена — немає інтернету (зміни на пристрої й надішлються самі).</li><li>Позначка <b>Спільний</b> — проєкт має посилання для перегляду (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"23\">Поширення за посиланням</a>). Клацання по позначці відкриває вікно посилання.</li><li>Проєкти, якими з вами поділилися інші, мають позначку з іменем власника й приміткою «Можна редагувати» або «Можна переглядати». Фільтри <span class=\"ui\">Усі</span>, <span class=\"ui\">Мої</span> і <span class=\"ui\">Надані мені</span> з'являються, коли у вас є такі проєкти.</li><li><span class=\"ui\">Запрошення</span> з числом — запрошення до чужих проєктів, які чекають на вашу відповідь (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24.3\">Прийняття запрошення</a>).</li></ul><figure><img src=\"img/instrukcja/projekty.png\" alt=\"Список проєктів\" loading=\"lazy\"><figcaption>Список проєктів</figcaption></figure>"},{"id":"2.2","tytul":"Новий проєкт","html":"<p><span class=\"ui\">Новий проєкт</span> запитує назву, формат сторінки (A4, A5, A6, B5, квадрат або <b>Власний</b> у мм), орієнтацію і:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Поле</th><th>Що задає</th></tr></thead><tbody><tr><td><b>Виліт</b></td><td>Смуга за краєм сторінки, яку друкарня обрізає, — зазвичай 3 мм (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.1\">Лінії на сторінці</a>).</td></tr><tr><td><b>Поля</b></td><td>Безпечна область для текстів, у мм.</td></tr><tr><td><b>Розташування сторінок</b></td><td><b>Окремі сторінки</b> або <b>Розвороти (ліва + права)</b>, як у книжці.</td></tr></tbody></table></div><p>Усе це можна змінити пізніше в налаштуваннях розділу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>).</p><p><b>Почати з</b>: <b>Порожньої сторінки</b> або <b>Готового шаблону</b>. <b>Готового шаблону</b> одразу показує в цьому вікні шаблони <b>цілих проєктів</b> — набори розділів із налаштуваннями, готові до друку й до 3D-макета:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Шаблон</th><th>Розділи</th></tr></thead><tbody><tr><td><b>Книжка у твердій палітурці</b></td><td>тверда обкладинка, передній форзац, блок, задній форзац</td></tr><tr><td><b>Книжка у твердій палітурці із суперобкладинкою</b></td><td>як вище, плюс суперобкладинка з клапанами</td></tr><tr><td><b>Книжка в м'якій обкладинці</b></td><td>м'яка клеєна обкладинка, блок</td></tr><tr><td><b>Брошура на скріпці</b></td><td>обкладинка на скріпці, блок (кратність 4)</td></tr><tr><td><b>Тижневий планер у твердій палітурці</b>, <b>Денний планер у м'якій обкладинці</b></td><td>обкладинка, (форзаци), календар у блоці</td></tr><tr><td><b>Фотоальбом у твердій палітурці</b></td><td>тверда обкладинка, форзаци, розвороти для фото</td></tr><tr><td><b>Настінний календар із підкладкою</b></td><td>12 місяців з обкладинкою, підкладка (картон)</td></tr></tbody></table></div><p>Клацніть шаблон: ви побачите перші сторінки кожного розділу й виберете <b>Формат</b>, <b>Сторінок блоку</b> і <b>Кратність сторінок (зошит)</b> — типово по 16 сторінок; кількість сторінок блоку завжди кратна їй. <b>Кольори</b> — бренд або палітра. <span class=\"ui\">Створити проєкт із цим шаблоном</span> створює весь проєкт. Поля формату й розташування тоді приховано — їх задає шаблон.</p><p>Шаблони <b>розділів</b> (календар, планер, запрошення, глава…) — це інше: їх вставляють в існуючий проєкт у редакторі (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.10\">Готові розділи (шаблони документів)</a>).</p><figure><img src=\"img/instrukcja/nowy-projekt.png\" alt=\"Новий проєкт\" loading=\"lazy\"><figcaption>Новий проєкт</figcaption></figure>"},{"id":"2.3","tytul":"Меню проєкту","html":"<p><span class=\"ui\">⋯</span> на картці проєкту: <span class=\"ui\">Перегляд</span> (одразу, без редактора, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"19\">Перегляд</a>), <span class=\"ui\">Перейменувати</span>, <span class=\"ui\">Дублювати</span> (напр. календар на наступний рік), <span class=\"ui\">Експортувати у файл (.makietka)</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.6\">Файл проєкту</a>), <span class=\"ui\">Спільна робота…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24\">Спільна робота</a>) і <span class=\"ui\">Видалити проєкт</span>. У проєкті іншої особи замість дублювання й видалення є <span class=\"ui\">Зробити власну копію</span> і <span class=\"ui\">Вийти з проєкту</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24.6\">Вихід із проєкту та копія</a>).</p><figure><img src=\"img/instrukcja/menu.png\" alt=\"Меню проєкту\" loading=\"lazy\"><figcaption>Меню проєкту</figcaption></figure>"},{"id":"2.4","tytul":"Збереження","html":"<p>Кнопки «Зберегти» немає — кожна зміна зберігається сама, спочатку на пристрої, а за мить в обліковому записі. Без інтернету зміни чекають на пристрої й надішлються самі, коли мережа повернеться. Стан збереження показує хмаринка біля назви проєкту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.1\">Список проєктів</a>). Зміна, зроблена просто перед закриттям вкладки, теж зберігається: вона записується на пристрої й потрапляє в обліковий запис під час наступного відкриття проєкту.</p>"},{"id":"2.5","tytul":"Кілька пристроїв і скасування","html":"<p>Той самий проєкт можна відкрити на кількох пристроях або в кількох вкладках. Зміна, зроблена на одному, за мить з'являється на іншому, без оновлення сторінки.</p><p>Нова версія Makietka вмикається сама й одразу, коли є інтернет (у відкритій вкладці щонайпізніше приблизно за 2 хвилини), – також у відкритому проєкті: зміни спочатку зберігаються, а потім проєкт відкривається в тому самому місці (з історією скасування). Під час введення тексту вона чекає, доки ви закінчите (щонайбільше 20 секунд). Без інтернету працює версія, збережена на пристрої. Номер версії видно в <b>Налаштуваннях</b>, під списком розділів.</p><p>Коли проєкт змінили у двох місцях одночасно, застосунок <b>об'єднує зміни елемент за елементом</b>: якщо на одному пристрої ви пересунете фото, а на іншому виправите заголовок, залишаться обидві зміни. Він запитує лише тоді, коли той самий елемент змінили в обох місцях: вікно «Те саме змінено на двох пристроях» показує кожен такий елемент із вибором <b>З цього пристрою</b> або <b>З облікового запису</b> (позначено версію з облікового запису). <span class=\"ui\">Усюди версія з облікового запису</span> вибирає її для всіх, <span class=\"ui\">Застосувати</span> підтверджує.</p><p><span class=\"ui\">Скасувати</span> (<kbd>Ctrl</kbd>+<kbd>Z</kbd>) і <span class=\"ui\">Повторити</span> (<kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Z</kbd>) охоплюють увесь проєкт: елементи, сторінки, розділи, шаблони сторінок, стилі, дані й серії. Історія сягає 80 кроків і зберігається після закриття проєкту — на тому самому пристрої. Скасування знімає лише зміни, зроблені на цьому пристрої; зміни інших людей і ШІ залишаються.</p>"},{"id":"2.6","tytul":"Файл проєкту","html":"<ul class=\"punkty\"><li><span class=\"ui\">Експортувати у файл (.makietka)</span> (меню <span class=\"ui\">⋯</span> на картці) зберігає весь проєкт, із зображеннями й шрифтами, у файл <code>.makietka</code> — це резервна копія або спосіб передати проєкт.</li><li><span class=\"ui\">Імпортувати з файлу</span> поруч із <span class=\"ui\">Новий проєкт</span> завантажує проєкт із файлу <code>.makietka</code> (на вузькому екрані це лише значок стрілки). Так само можна відкрити проєкт з <b>InDesign</b> (<code>.idml</code> – в InDesign: Файл → Зберегти як → InDesign Markup) і зі <b>Scribus</b> (<code>.sla</code>): з'являється новий проєкт зі сторінками (розділ для кожного формату сторінки, виліт і поля з файлу), текстовими рамками з форматуванням (зв'язані рамки й далі перетікають текст), фігурами в кольорі (CMYK перераховано в RGB) і зображеннями, збереженими у файлі. Зображення, які в InDesign чи Scribus лише прив'язані посиланням, можна завантажити разом із проєктом у ZIP-файлі (в InDesign: Файл → Пакет; у Scribus: Файл → Зібрати для виводу) – без них на їхньому місці стоять сірі поля з назвою файлу. Поля злиття даних InDesign та Affinity (<code>&lt;&lt;imie&gt;&gt;</code>), а також Word і Publisher (<code>«imie»</code>) стають полями Makietka (<code>{imie}</code>) – залишається лише завантажити дані (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14\">Таблиці даних</a>). Це працює й із файлами <b>Microsoft Publisher</b> (<code>.pub</code>, версії 2002–2019 – Microsoft припинив підтримку Publisher у жовтні 2026 року): сторінки у форматі з файлу, текстові рамки на своїх місцях зі шрифтом, розміром, жирним, курсивом, підкресленням і вирівнюванням, зв'язані рамки як перетічний текст, елементи шаблонних сторінок під вмістом, фото (JPEG, PNG, GIF), кольорові фони рамок і прості фігури. Зображення в старих форматах Windows (WMF, EMF) браузер не показує – на їхньому місці сірі поля. Старіші файли (Publisher 98/2000) спершу треба зберегти в новішій версії. Після завантаження вікно <b>«Що перейшло з програми…»</b> повідомляє, що спрощено: градієнт замінено одним кольором, тінь та інші ефекти пропущено, повернуте зображення вставлено без повороту, таблицю з IDML — як текст із табуляціями, текст на контурі й таблицю Scribus — як сіре поле, відсутні зображення, стилі абзаців — як звичайне форматування. <span class=\"ui\">Показати</span> відкриває сторінку з першим таким елементом. Спрощені елементи позначено, і вони з'являються в <b>Перевірити перед друком</b> як «З імпорту: …» – кнопка <span class=\"ui\">Перевірено</span> знімає позначку, коли елемент уже виправлено. Форматування фрагментів (напр. жирне поле <code>&lt;&lt;imie&gt;&gt;</code>) зберігається й у полях злиття.</li><li>Встановлений на комп'ютері застосунок відкриває файли <code>.makietka</code> подвійним клацанням (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"28.4\">Установлення застосунку</a>).</li></ul><p><b>Текст з інших програм і для них.</b> У редакторі, меню <b>⋯</b>:</p><ul class=\"punkty\"><li><span class=\"ui\">Вставити текст із файлу (Word, ODT, Markdown)…</span> — файл <code>.docx</code> (Word), <code>.odt</code> (LibreOffice, OpenOffice), <code>.md</code> (Markdown) або <code>.txt</code> потрапляє в одну рамку на поточній сторінці, у межах полів, з увімкненим <b>Додавати сторінки</b>: текст сам розподіляється на стільки сторінок, скільки потрібно. Заголовки залишаються заголовками (більші, жирні), глави (заголовок 1) починаються з нової сторінки, а жирні, курсивні й підкреслені фрагменти зберігаються. Таблиці потрапляють як рядки з табуляціями; зображення й виноски з файлу треба вставити окремо — застосунок скаже, скільки їх було.</li><li><span class=\"ui\">Зберегти текст як Word (.docx)</span> і <span class=\"ui\">Зберегти як е-книжку (EPUB)</span> — лише вміст сторінок у порядку читання (без обкладинки), із заголовками й форматуванням фрагментів; е-книжка має зміст і кожну главу в окремому файлі. Макет сторінок і зображення залишаються в Makietka.</li><li><span class=\"ui\">Зберегти для Scribus (.sla)</span> — весь проєкт із макетом сторінок для безкоштовної програми верстки Scribus (1.5 і 1.6): сторінки в порядку друку, з вильотом і полями, серії розгорнуто, дані підставлено. Тексти — це звичайні текстові рамки Scribus (шрифт, розмір, колір, жирний, курсив, підкреслення, вирівнювання, абзаци) — їх можна далі редагувати; прямокутники, еліпси, багатокутники, лінії й контури — це фігури з кольорами; фото, таблиці, календарі, групи й елементи з тінню або прозорістю потрапляють як зображення (300 dpi), збережені в самому файлі. Шрифти мають бути встановлені в системі — застосунок підкаже, які з них використовує файл. Лінії висічки не переносяться (вони у файлі для плотера).</li><li><span class=\"ui\">Зберегти для InDesign (.idml)</span> — те саме у форматі IDML, який відкриває Adobe InDesign (CS4 і новіші), а також Affinity Publisher і QuarkXPress: текстові рамки з форматуванням, фігури з кольорами, решта як зображення, вбудовані у файл. Кожна сторінка — окрема сторінка документа (без об'єднання в розвороти); поля й виліт зберігаються.</li><li><span class=\"ui\">Зберегти для Word з макетом сторінок (.docx)</span> — сторінки проєкту як сторінки документа Word: текстові рамки (текстові поля) зі шрифтом, кольором, вирівнюванням і міжрядковим інтервалом, фігури й зображення на своїх місцях, фон сторінки; таблиці, календарі й елементи з ефектами — як зображення. Такий файл відкриває й LibreOffice (Writer).</li><li><span class=\"ui\">Зберегти сторінки як SVG (Inkscape, Illustrator)</span> — кожна сторінка як SVG-файл у міліметрах (ZIP) – для Inkscape, Illustrator, Corel, Affinity або LibreOffice Draw.</li><li><b>Що перейде, а що ні.</b> Перед завантаженням файлу для Scribus, InDesign і Word вікно <b>«Що перейде до програми…»</b> перелічує, що перейде без змін, що <b>перетвориться на зображення</b> (виглядає так само, але його не можна редагувати: таблиці, календарі, діаграми, коди, групи, елементи з тінню, прозорістю, градієнтом, пунктирною лінією, текст по дузі), що буде <b>спрощено</b> (серії розгорнуто в готові сторінки, шаблони сторінок вбудовано в сторінки, стилі як звичайне форматування, зв'язані рамки роз'єднано, Pantone як RGB), чого <b>не вдасться перенести</b> (посилання, виноски, буквиці, лінії висічки) і що треба <b>зробити в програмі</b> (встановити шрифти, увімкнути перенесення слів). Біля кожного пункту є номери сторінок, а <span class=\"ui\">Показати</span> закриває вікно без завантаження й виділяє перший такий елемент – його можна виправити й зберегти ще раз. <span class=\"ui\">Завантажити</span> зберігає файл.</li><li><span class=\"ui\">Серія для іншої програми (шаблон + дані)…</span> — злиття даних поза Makietka. Сторінки проєкту йдуть по одному разу (без повторення), з полями на місці даних, а поруч — дані з таблиці серії. На вибір: - <b>InDesign / Affinity Publisher</b> – шаблон IDML з мітками <code>&lt;&lt;imie&gt;&gt;</code>, <code>dane.csv</code> і папка <code>obrazy/</code> (стовпець зображень має назву з <code>@</code>, напр. <code>@zdjecie</code>, і шляхи до файлів – так їх читає «Злиття даних»); - <b>Scribus</b> – шаблон SLA зі змінними <code>%VAR_imie%</code> для плагіна ScribusGenerator і <code>dane.csv</code>; - <b>Word / Publisher</b> – текст у DOCX зі справжніми полями злиття й <code>dane.xlsx</code> (Розсилки → Вибрати одержувачів → Використати наявний список). Поля документа (<code>{номер}</code>, <code>{розділ}</code>…) вже обчислено. Файл <code>CZYTAJ-MNIE.txt</code> у пакеті крок за кроком пояснює, що далі, а в кінці містить той самий опис «що й як перенеслося». У зворотний бік: текст із Word із полями злиття (Вставити текст із файлу) надходить із полями <code>{imie}</code>.</li></ul>"}]},
  {"nr":"3","tytul":"Екран редактора","czesc":"Редактор","ikona":"olowek","wstep":"Де що є в редакторі — панелі, бокові панелі та меню.","sekcje":[{"id":"3.1","tytul":"Будова екрана","html":"<p>Проєкт відкривається в редакторі. Екран має п'ять частин:</p><ul class=\"punkty\"><li><b>верхня панель</b> — навігація, скасування, вікна проєкту та меню <span class=\"ui\">⋯</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.2\">Верхня панель</a>, <a href=\"#\" data-cel=\"3.3\">Меню ⋯</a>),</li><li><b>панель сторінок</b> ліворуч — мініатюри сторінок, згруповані в розділи (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.1\">Панель сторінок</a>),</li><li><b>сторінка</b> посередині, а над нею панель вставлення (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.4\">Панель вставлення</a>),</li><li><b>права колонка</b> — вкладки «Властивості» і «Шари» (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.5\">Властивості й шари</a>, <a href=\"#\" data-cel=\"9\">Шари</a>),</li><li><b>правий нижній кут</b> — допоміжні лінії, попередження, меню вигляду та масштаб (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.6\">Правий нижній кут і меню вигляду</a>).</li></ul><p>Наведіть мишу на кнопку — побачите її назву та клавіатурне скорочення.</p><figure><img src=\"img/instrukcja/edytor.png\" alt=\"Редактор\" loading=\"lazy\"><figcaption>Редактор</figcaption></figure>"},{"id":"3.2","tytul":"Верхня панель","html":"<figure class=\"kadr\"><img src=\"img/instrukcja/k-pasek-gorny.png\" alt=\"Верхня панель\" loading=\"lazy\"><figcaption>Верхня панель</figcaption></figure><p>Зліва: <span class=\"ui\">Проєкти</span>, <b>назва проєкту</b> (клацніть, щоб її змінити) зі станом збереження (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.4\">Збереження</a>), <span class=\"ui\">Скасувати</span> і <span class=\"ui\">Повторити</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.5\">Кілька пристроїв і скасування</a>), <span class=\"ui\">Шаблони</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11\">Шаблони сторінок</a>), <span class=\"ui\">Дані</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14\">Таблиці даних</a>), <span class=\"ui\">Перегляд</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"19\">Перегляд</a>), <b>формат</b> розділу, напр. «A5» — відкриває налаштування розділу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>), <span class=\"ui\">Коментарі</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24.7\">Коментарі</a>), лупа <span class=\"ui\">Знайти й замінити</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.15\">Знайти й замінити</a>) і <span class=\"ui\">⋯</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.3\">Меню ⋯</a>).</p><p>Написи біля іконок з'являються, коли для них є місце — це можна змінити в меню вигляду: <b>Написи на верхній панелі</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.6\">Правий нижній кут і меню вигляду</a>). На вузькому телефоні <span class=\"ui\">Шаблони</span>, <span class=\"ui\">Дані</span>, <span class=\"ui\">Коментарі</span> і лупа є в меню <span class=\"ui\">⋯</span>.</p>"},{"id":"3.3","tytul":"Меню ⋯","html":"<figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-wiecej.png\" alt=\"Меню ⋯\" loading=\"lazy\"><figcaption>Меню ⋯</figcaption></figure><p>Пункти згруповано:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Група</th><th>Пункти</th></tr></thead><tbody><tr><td>Пошук і примітки</td><td><span class=\"ui\">Знайти й замінити…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.15\">Знайти й замінити</a>), <span class=\"ui\">Коментарі</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24.7\">Коментарі</a>).</td></tr><tr><td>Ресурси проєкту</td><td><span class=\"ui\">Зображення проєкту…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.5\">Вікно «Зображення проєкту»</a>), <span class=\"ui\">Шрифти проєкту…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.8\">Шрифти</a>), <span class=\"ui\">Кольори проєкту…</span> — кольори проєкту й розділів, додаткові кольори, оздоблення (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.1\">Додаткові кольори</a>, <a href=\"#\" data-cel=\"22.5\">Кольори проєкту й друк кольорів — для всього проєкту або для розділу</a>); на телефоні також <span class=\"ui\">Шаблони сторінок…</span> і <span class=\"ui\">Дані…</span>.</td></tr><tr><td>Формат і бренд</td><td><span class=\"ui\">Змінити формат проєкту…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.9\">Зміна формату з масштабуванням</a>), <span class=\"ui\">Застосувати бренд до проєкту…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.9\">Бренд-кит</a>).</td></tr><tr><td>Друк і експорт</td><td><span class=\"ui\">Перевірити перед друком</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>), <span class=\"ui\">Експортувати в PDF…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Експорт у PDF і PNG</a>), <span class=\"ui\">Друкувати вдома…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21.8\">Друк удома</a>), <span class=\"ui\">Завантажити поточну сторінку як PNG</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21.5\">Сторінка як PNG</a>).</td></tr><tr><td>Інше</td><td><span class=\"ui\">Спільна робота…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24\">Спільна робота</a>) і перемикач теми (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.4\">Тема</a>).</td></tr></tbody></table></div>"},{"id":"3.4","tytul":"Панель вставлення","html":"<p>Панель над сторінкою вставляє нові елементи (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.1\">Вставлення</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-wstaw.png\" alt=\"Панель вставлення\" loading=\"lazy\"><figcaption>Панель вставлення</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Кнопка</th><th>Клавіша</th><th>Що вставляє</th></tr></thead><tbody><tr><td><span class=\"ui\">Текст</span></td><td><kbd>T</kbd></td><td>Текстову рамку (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5\">Текст</a>).</td></tr><tr><td><span class=\"ui\">Фігури ▾</span></td><td><kbd>R</kbd> <kbd>E</kbd> <kbd>P</kbd> <kbd>L</kbd> <kbd>B</kbd> <kbd>N</kbd></td><td>Меню: <b>Прямокутник</b>, <b>Еліпс</b> (або коло), <b>Багатокутник або зірка</b> (спершу вибір фігури), <b>Лінія</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.1\">Прямокутник, еліпс і багатокутник</a>, <a href=\"#\" data-cel=\"6.2\">Лінія</a>), <b>Малювання від руки</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.3\">Малювання від руки</a>) і <b>Перо</b> – фігура з точок і дуг (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.4\">Перо й редагування точок</a>). Коли працює малювання або перо, кнопка має його іконку – клацання завершує інструмент.</td></tr><tr><td><span class=\"ui\">Зображення</span></td><td>—</td><td>Фото або графіку (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.1\">Вставлення зображення</a>).</td></tr><tr><td><span class=\"ui\">ШІ ▾</span></td><td>—</td><td>Меню ШІ: зображення з опису, виправлення зображення в рамці, покращення й переклад тексту, стовпець даних (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.17\">Текст ШІ: виправлення і переклад</a>, <a href=\"#\" data-cel=\"7.11\">Зображення ШІ</a>, <a href=\"#\" data-cel=\"14.6\">Заповнити стовпець за допомогою ШІ</a>); у коміксі також сценарій і кадри (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.13\">Комікс</a>).</td></tr><tr><td><span class=\"ui\">Таблиця</span></td><td>—</td><td>Таблицю з рядками й стовпцями (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8\">Таблиця</a>).</td></tr><tr><td><span class=\"ui\">Бібліотека</span></td><td>—</td><td>Готові елементи: фігури, рамки, прикраси, планери, календарі, діаграми та інше (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.8\">Бібліотека</a>).</td></tr><tr><td><span class=\"ui\">Коментар</span></td><td>—</td><td>Коментар, прикріплений до місця на сторінці або до виділеного елемента (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24.7\">Коментарі</a>).</td></tr></tbody></table></div><p>Підписи під іконками вмикаються в меню вигляду: <b>Підписи інструментів</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.6\">Правий нижній кут і меню вигляду</a>).</p><p>Клавіатурні скорочення фігур працюють без відкривання меню. Розмову зі ШІ відкриває окрема кнопка <span class=\"ui\">Асистент ШІ</span> на верхній панелі, поруч із <span class=\"ui\">Перегляд</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Асистент ШІ в Makietka (власний ключ)</a>).</p><p><b>На телефоні</b> <span class=\"ui\">Коментар</span> і <span class=\"ui\">Копіювати стиль</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.13\">Копіювати стиль (пензель формату)</a>) є під <span class=\"ui\">⋯</span> у кінці панелі, а <span class=\"ui\">Асистент ШІ</span> – у меню <span class=\"ui\">ШІ ▾</span>. Коли один з інструментів під <span class=\"ui\">⋯</span> працює, <span class=\"ui\">⋯</span> показує його іконку; дотик завершує інструмент.</p><figure class=\"kadr telefon\"><img src=\"img/instrukcja/k-wstaw-telefon.png\" alt=\"Меню ⋯ панелі вставлення на телефоні\" loading=\"lazy\"><figcaption>Меню ⋯ панелі вставлення на телефоні</figcaption></figure>"},{"id":"3.5","tytul":"Властивості й шари","html":"<p>Права колонка має вгорі дві вкладки: <span class=\"ui\">Властивості</span> і <span class=\"ui\">Шари</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"9\">Шари</a>), які перемикаються клацанням або <kbd>F7</kbd>. Заголовок властивостей показує, чого стосуються налаштування:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Заголовок</th><th>Коли</th><th>Що ви налаштовуєте</th></tr></thead><tbody><tr><td><b>Виділений елемент</b> · тип (напр. «Текст»)</td><td>Виділено елемент.</td><td>Вигляд і розташування цього елемента.</td></tr><tr><td><b>Налаштування інструмента</b> · назва (напр. «Малювання»)</td><td>Увімкнено інструмент, напр. малювання від руки. Заголовок тоді має тло акцентного кольору.</td><td>Як виглядатимуть наступні елементи — «Так виглядатимуть наступні лінії.»</td></tr><tr><td><b>Нічого не виділено</b> · «Сторінка»</td><td>Нічого не виділено.</td><td>Налаштування відкритої сторінки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.3\">Властивості сторінки</a>).</td></tr></tbody></table></div><p>Коли виділено елемент, у заголовку є <span class=\"ui\">Копіювати в буфер обміну</span>, <span class=\"ui\">Дублювати</span>, <span class=\"ui\">Копіювати стиль</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.13\">Копіювати стиль (пензель формату)</a>), <span class=\"ui\">Зберегти в бібліотеці</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.8\">Бібліотека</a>) і <span class=\"ui\">Видалити</span>. <b>Попередження</b> відкриває кнопка з трикутником біля масштабу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.2\">Попередження</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-rysowanie.png\" alt=\"Налаштування інструмента: малювання\" loading=\"lazy\"><figcaption>Налаштування інструмента: малювання</figcaption></figure><p>На телефоні ці панелі відкривають кнопки внизу екрана (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"28.2\">Редактор на телефоні</a>).</p><figure><img src=\"img/instrukcja/wlasciwosci.png\" alt=\"Властивості виділеного тексту\" loading=\"lazy\"><figcaption>Властивості виділеного тексту</figcaption></figure>"},{"id":"3.6","tytul":"Правий нижній кут і меню вигляду","html":"<figure class=\"kadr\"><img src=\"img/instrukcja/k-widok.png\" alt=\"Правий нижній кут\" loading=\"lazy\"><figcaption>Правий нижній кут</figcaption></figure><ul class=\"punkty\"><li><b>два аркуші</b> — лише в розділі з розворотами: увесь розворот або одна сторінка (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.5\">Розвороти</a>),</li><li>кнопка <b>допоміжних ліній</b> (<kbd>W</kbd>) — показує або ховає поля, виліт, корінець і напрямні (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.1\">Лінії на сторінці</a>),</li><li>кнопка <b>Попередження</b> (трикутник, <kbd>F8</kbd>) — кількість зауважень на сторінці; відкриває вікно попереджень (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.2\">Попередження</a>),</li><li><span class=\"ui\">Вигляд</span> (іконка сітки) — меню вигляду,</li><li><span class=\"ui\">−</span>, відсоток, <span class=\"ui\">+</span> — масштаб (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.6\">Масштаб</a>).</li></ul><p>Меню вигляду:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Пункт</th><th>Що робить</th></tr></thead><tbody><tr><td><b>Сітка</b>, <b>Прилипати до сітки</b>, <b>Крок сітки</b></td><td>Сітка із заданим кроком у мм (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.3\">Сітка</a>).</td></tr><tr><td><b>Сітка базових ліній</b></td><td>Базові лінії з налаштувань розділу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.13\">Сітка базових ліній</a>).</td></tr><tr><td><b>Прилипати до елементів і показувати відстані</b></td><td>Рожеві лінії та відстані в мм під час переміщення (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.5\">Прилипання й відстані</a>).</td></tr><tr><td><b>Лінійки</b></td><td>Лінійки в мм над сторінкою і ліворуч (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.4\">Лінійки й напрямні</a>).</td></tr><tr><td><b>Заблокувати напрямні</b>, <span class=\"ui\">Видалити напрямні з цієї сторінки</span></td><td>Захист і прибирання напрямних (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.4\">Лінійки й напрямні</a>).</td></tr><tr><td><b>У розворотах показувати одну сторінку</b></td><td>Те саме, що кнопка з двома аркушами (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.5\">Розвороти</a>).</td></tr><tr><td><b>Перевіряти правопис</b></td><td>Хвиляста червона лінія під словами, яких немає в словнику, і частина <b>Правопис</b> на панелі тексту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.16\">Перевірка правопису</a>).</td></tr><tr><td><b>Показувати оздоблення</b></td><td>Ефект лаку, фольги, тиснення і білої фарби на сторінці; вимкнено — звичайний вигляд (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.3\">Вигляд оздоблень</a>).</td></tr><tr><td><b>Підписи інструментів</b></td><td>Підписи під іконками панелі вставлення.</td></tr><tr><td><b>Написи на верхній панелі</b></td><td><span class=\"ui\">Авто</span> — коли вміщуються, <span class=\"ui\">Завжди</span>, <span class=\"ui\">Ніколи</span>.</td></tr></tbody></table></div><p>Налаштування вигляду стосуються лише цього пристрою.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-widoku.png\" alt=\"Меню вигляду\" loading=\"lazy\"><figcaption>Меню вигляду</figcaption></figure>"}]},
  {"nr":"4","tytul":"Елементи на сторінці","czesc":"Редактор","ikona":"olowek","wstep":"Усе, що стоїть на сторінці, — це елемент: тут описано те, що спільне для всіх, — виділення, переміщення, групи, готові елементи з Бібліотеки.","sekcje":[{"id":"4.1","tytul":"Вставлення","html":"<p>Клацніть інструмент на панелі вставлення (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.4\">Панель вставлення</a>) — елемент з'явиться посередині видимої області й буде виділений. Зображення можна також перетягнути з диска на сторінку або вставити з буфера обміну (<kbd>Ctrl</kbd>+<kbd>V</kbd>).</p><p>Елементи шаблонів (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11\">Шаблони сторінок</a>) видно на сторінці, але тут їх не можна виділити — їх змінюють у шаблоні.</p><figure><img src=\"img/instrukcja/wstawianie.png\" alt=\"Вставлений текст\" loading=\"lazy\"><figcaption>Вставлений текст</figcaption></figure>"},{"id":"4.2","tytul":"Виділення","html":"<ul class=\"punkty\"><li><b>Клацання</b> виділяє елемент.</li><li><kbd>Shift</kbd> + клацання додає елемент до виділення або вилучає його з нього.</li><li><b>Перетягування рамки</b> від порожнього місця сторінки виділяє елементи, яких вона торкнеться.</li><li><kbd>Ctrl</kbd>+<kbd>A</kbd> виділяє всі елементи сторінки.</li><li>Елемент, що лежить під іншим, виділіть у списку шарів (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"9\">Шари</a>).</li><li><b>Подвійне клацання</b>: у тексті — введення тексту, у групі — вхід у групу, у клітинці таблиці — введення в клітинку, у фігурі з пера — редагування точок, у зображенні — кадрування.</li><li><kbd>Esc</kbd> знімає виділення.</li></ul>"},{"id":"4.3","tytul":"Переміщення, розмір і обертання","html":"<ul class=\"punkty\"><li><b>Перетягніть</b> елемент, щоб його перемістити. Стрілки зсувають на 1 мм, із <kbd>Shift</kbd> — на 10 мм.</li><li><b>Кружечки в кутах і на боках</b> змінюють розмір, <b>кружечок над елементом</b> обертає.</li><li><kbd>Shift</kbd> під час перетягування — лише по горизонталі або вертикалі; під час обертання — кроком 15°.</li><li><kbd>Alt</kbd> під час перетягування — ви перетягуєте копію.</li></ul><p>Точні значення можна ввести у властивостях, у частині <b>Розташування і розмір (мм)</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Поле</th><th>Значення</th></tr></thead><tbody><tr><td><b>X</b>, <b>Y</b></td><td>Лівий верхній кут елемента, у мм від лівого верхнього кута сторінки (без вильоту).</td></tr><tr><td><b>Ширина</b>, <b>Висота</b></td><td>Розмір у мм. Замок між ними зберігає пропорції.</td></tr><tr><td><b>Обертання</b></td><td>Кут у градусах.</td></tr></tbody></table></div><p>Якщо виділено кілька елементів, числа стосуються їхньої спільної рамки.</p>"},{"id":"4.4","tytul":"Вирівнювання і рівні відстані","html":"<p>Частина <b>Вирівняти</b> у властивостях:</p><ul class=\"punkty\"><li><b>один елемент</b> — вирівнювання по полях сторінки: ліворуч, по центру, праворуч, угору, по центру по вертикалі, донизу,</li><li><b>кілька елементів</b> — вирівнювання між собою,</li><li><b>три й більше</b> — додатково <span class=\"ui\">Розподілити рівномірно по горизонталі</span> і <span class=\"ui\">Розподілити рівномірно по вертикалі</span>: рівні відстані між елементами.</li></ul><p>Під час переміщення елемент «прилипає» до країв і центрів інших елементів, а стрілки показують відстані в мм (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.5\">Прилипання й відстані</a>).</p><figure><img src=\"img/instrukcja/wyrownanie.png\" alt=\"Вирівнювання кількох елементів\" loading=\"lazy\"><figcaption>Вирівнювання кількох елементів</figcaption></figure>"},{"id":"4.5","tytul":"Групи","html":"<p>Виділіть кілька елементів і виберіть <span class=\"ui\">Згрупувати</span> (<kbd>Ctrl</kbd>+<kbd>G</kbd>). Група переміщується, масштабується й обертається як один елемент. <span class=\"ui\">Розгрупувати</span> (<kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>G</kbd>) знову розділяє її.</p><p><b>Елемент групи без розгрупування:</b> двічі клацніть групу — вона відкриється (помаранчева пунктирна рамка), а елемент під курсором буде виділено. Його можна перемістити, змінити у властивостях або вводити в ньому текст. Клацання іншого елемента групи виділяє той, <kbd>Shift</kbd> додає наступні. <kbd>Esc</kbd>, клацання поза групою або <span class=\"ui\">Повернутися до всієї групи</span> закриває її.</p><ul class=\"punkty\"><li>У відкритій групі <span class=\"ui\">Дублювати</span> залишає копію в групі, а <span class=\"ui\">Видалити</span> видаляє лише виділений елемент.</li><li>Група в групі відкривається наступним подвійним клацанням; <kbd>Esc</kbd> повертає на рівень вище.</li></ul>"},{"id":"4.6","tytul":"Порядок, блокування і буфер обміну","html":"<ul class=\"punkty\"><li>Частина <b>Порядок</b>: <span class=\"ui\">На передній план</span>, <span class=\"ui\">Вище</span>, <span class=\"ui\">Нижче</span>, <span class=\"ui\">На задній план</span>. Те саме можна зробити перетягуванням у списку шарів (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"9\">Шари</a>).</li><li>Частина <b>Інші</b>: - <b>Непрозорість</b> — прозорість елемента у %, - <b>Заблокувати розташування і розмір</b> — елемент не зсунеться випадково; колір і текст можна далі змінювати, - <b>Вимкнути попередження для цього об'єкта</b> — напр. для тла, яке навмисно заходить на виліт, - <b>Назва</b> — назва елемента в списку шарів.</li><li><span class=\"ui\">Копіювати в буфер обміну</span> і <kbd>Ctrl</kbd>+<kbd>V</kbd> на іншій сторінці вставляють елемент у те саме місце. У властивостях сторінки є також <span class=\"ui\">Вставити скопійовані елементи</span>.</li><li><b>Між проєктами</b>: скопійований елемент чекає в буфері обміну цього пристрою — відкрийте інший проєкт і вставте (<kbd>Ctrl</kbd>+<kbd>V</kbd> або <span class=\"ui\">Вставити скопійовані елементи</span>). Зображення елемента потрапляють до зображень нового проєкту. Буфер обміну зберігається після переходу до іншого проєкту, перезавантаження і в другій вкладці.</li><li><b>Сторінки й розділи</b> до іншого проєкту: меню сторінки (⋯ на мініатюрі) → <span class=\"ui\">Копіювати в буфер обміну (також до іншого проєкту)</span>, меню розділу → <span class=\"ui\">Копіювати розділ у буфер обміну (також до іншого проєкту)</span>. В іншому проєкті: меню сторінки → <span class=\"ui\">Вставити сторінки з буфера обміну</span> (після цієї сторінки, у її розділі) або меню розділу → <span class=\"ui\">Вставити розділ із буфера обміну</span> (після цього розділу). Разом зі сторінками переносяться їхні зображення, шаблони, серії з таблицями даних і стилі тексту. Пункт меню показує, що є в буфері і з якого проєкту. Обкладинку не можна вставити в проєкт, який уже має обкладинку, — вставте тоді лише сторінки.</li></ul>"},{"id":"4.7","tytul":"Тінь","html":"<p>Частина <b>Тінь</b> працює для кожного елемента:</p><p><b>Тінь під елементом</b> вмикає тінь. Можна налаштувати її колір, <b>Силу</b>, зсув <b>Праворуч</b> і <b>Униз</b> у мм (від'ємні — ліворуч або вгору) і <b>Розмиття</b> країв у мм.</p>"},{"id":"4.8","tytul":"Бібліотека","html":"<p>Бібліотека — це готові елементи для вставлення: фігури, рамки, прикраси, планери, календарі, діаграми і ваші власні елементи. Її відкриває <span class=\"ui\">Бібліотека</span> на панелі вставлення.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-biblioteka.png\" alt=\"Бібліотека поруч зі сторінкою\" loading=\"lazy\"><figcaption>Бібліотека поруч зі сторінкою</figcaption></figure><ol class=\"kroki\"><li>Виберіть категорію вгорі або введіть слово в поле <b>Пошук</b> – пошук переглядає всі категорії одразу.</li><li>Клацніть елемент – він стане посередині поточної сторінки. На комп'ютері можна також перетягнути плитку на сторінку: елемент стане там, де ви його відпустите.</li><li>Решту налаштуйте на панелі властивостей, як для будь-якого елемента.</li></ol><div class=\"tabela-instrukcji\"><table><thead><tr><th>Категорія</th><th>Що в ній є</th></tr></thead><tbody><tr><td><b>Мої елементи</b></td><td>Елементи, які ви зберегли, – в обліковому записі, у кожному проєкті (див. нижче).</td></tr><tr><td><b>Готові розділи</b></td><td>Цілі документи: календарі, планери, блокноти, запрошення, дипломи, візитівки, листівки, меню, розділи книги… Плитка відкриває вікно готових розділів із цим шаблоном (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.10\">Готові розділи (шаблони документів)</a>).</td></tr><tr><td><b>Іконки</b></td><td>260 лінійних іконок в одному стилі, у групах: <b>Контакт</b>, <b>Час і календар</b>, <b>Погода</b>, <b>Їжа</b>, <b>Подорожі</b>, <b>Школа й навчання</b>, <b>Віра</b> (хрест, голуб, риба, свічка, складені долоні, Біблія, чаша, вервиця…), <b>Здоров'я</b>, <b>Фінанси</b>, <b>Дім</b>, <b>Природа</b>, <b>Технології</b>, <b>Стрілки</b>. Колір і товщину лінії змінюйте в частині <b>Обведення</b>; під час збільшення лінія росте разом з іконкою.</td></tr><tr><td><b>Ілюстрації</b></td><td>Лінійні малюнки для перефарбовування: гори, ліс, вітрильник, маяк, будинок із деревом, церква на пагорбі, кава й книжка, свічка з книгою, монстера, гілочка, кактус, птахи, метелик, кіт, сніп збіжжя, виноградна лоза, голуб із гілочкою, долоні із серцем, хрест на пагорбі, місяць, місто, велосипед, подарунок.</td></tr><tr><td><b>Фігури</b></td><td>Понад 200 фігур у групах: <b>Основні</b> (коло, квадрат, овали, трикутники, дуги, кільце, куб, циліндр…), <b>Багатокутники</b> (також заокруглені, бджолині стільники), <b>Зірки й значки</b> (зірки, печатки, медаль, шестерня, рекламні значки), <b>Серця і природа</b> (серця, квіти, листя, хмари, гори, хвиля, полум'я, веселка, тварини…), <b>Символи й іконки</b> (дім, телефон, корона, кубок, замок, людина, ноутбук, ключ, пазл, мапа…), <b>Святкові</b> (подарунок, кулька, ялинка, ялинкова кулька, торт, писанка, сніговик…), <b>Символи</b> (плюс, мінус, відсоток, знак питання, галочка, поля вибору…).</td></tr><tr><td><b>Стрілки й бульбашки</b></td><td>Стрілки в усі боки, навскіс, закручені, з коліном, дугою, хвилясті, обміну, розгалужені; шеврони; мовні бульбашки з кожного боку, круглі, овальні, думки, хмаринка, крику, дві бульбашки.</td></tr><tr><td><b>Рамки</b></td><td>Понад 60 рамок у групах: <b>Прості</b>, <b>Заокруглені</b>, <b>Подвійні й пунктирні</b> (пунктирна, крапкова, штрих – крапка – лише обведення), <b>Декоративні</b>, <b>З місцем для заголовка</b>, <b>Фігурні</b> (серце, овал, коло, хмаринка, восьмикутник, арка, зірка…), <b>На фото</b> (поля у формі кола, серця, арки, хмаринки… – вставте в них зображення, а також відбиток, слайд, кадр плівки), <b>Аркуші й нотатки</b>, <b>Рамки сторінок</b> (одразу вставляються на всю сторінку).</td></tr><tr><td><b>Прикраси</b></td><td>Стрічки й банери, кутики (поодинокі та комплекти з чотирьох), розетки й орнаменти (мандала, роза вітрів, лілея, медальйон…).</td></tr><tr><td><b>Лінії й роздільники</b></td><td>Лінія суцільна, тонка, товста, пунктирна, крапкова, штрих – крапка, подвійна й вертикальна; декоративні роздільники (хвиля, зигзаг, із крапкою, кружечком, зірочкою, квіточкою, ромбами, завитки, петельки, листочки…). Тип і товщину потім змінюйте в частині <b>Лінія</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.2\">Лінія</a>).</td></tr><tr><td><b>Етикетки й значки</b></td><td>Етикетки заокруглені, зі зрізаними кутами, овальні, з облямівкою, хвилясті, зубчасті, на банку, геральдичні, цінник, бирка, значок, печатка, поштова марка, табличка — усередину вставте текст.</td></tr><tr><td><b>Святкові</b></td><td>Набори в одному стилі на <b>Різдво</b>, <b>Великдень</b>, <b>день народження</b>, <b>весілля</b>, <b>хрещення</b>, <b>Перше Причастя</b> і <b>школу</b>: заголовок із побажаннями, рамка, бордюр і готова листівка.</td></tr><tr><td><b>Тла й візерунки</b></td><td><b>Візерунки на всю сторінку</b> (смужки, крапки, горошок, клітинка, шотландка, ялинка, хвилі, зигзаг, ромби, зірочки, квіточки, стільники, луска, трикутники, хрестики, кола, коміксний растр, лінії руху), <b>Текстури паперу</b> (лляне полотно, картон, пакувальний папір, черпаний, у лінійку з полем, міліметровий), <b>Градієнти</b> і <b>Плями й акварель</b>. Візерунки, текстури й градієнти вставляються на всю сторінку з вильотом, під вміст; візерунок — це один векторний елемент на тлі – кольори змінюйте після відкриття групи (подвійне клацання). Якщо виділено фігуру, візерунок може її заповнити (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.5\">Заливка</a>).</td></tr><tr><td><b>Календарі</b></td><td>Календар місяця: звичайний, із місцем для нотаток, із номерами тижнів (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.9\">Календар місяця</a>).</td></tr><tr><td><b>Планер</b></td><td>Готові таблиці для планерів і блокнотів: список справ, трекер звичок, план тижня, план дня (години), нотатки в лінійку, сітка днів тижня, список покупок, цілі, бюджет, контакти, розклад уроків; <b>Плани</b>: річний календар (12 місяців на сторінці), план місяця, тиждень у колонках і з пріоритетами, план харчування; <b>Трекери</b>: настрій, вода, читання, молитовний щоденник; <b>Списки й бюджет</b>: список бажань, місячний бюджет; а також сітки для нотаток: клітинка, крапки, лінії (кожні 5 мм), міліметровий папір, ізометрична сітка. Поля вибору є у <b>Фігури → Символи</b>.</td></tr><tr><td><b>Форми для друку</b></td><td>Дата й підпис, клітинки для літер, поля для даних, відрізний талон із ножицями, поля вибору, шкала оцінок 1–5, поле для зауважень, купон, згода з підписом; таблиця замовлення і список присутності (звичайні таблиці).</td></tr><tr><td><b>Діаграми</b></td><td>Стовпчикова, горизонтальна, лінійна, кругова і кільцева з таблиці даних (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.10\">Діаграма</a>).</td></tr><tr><td><b>Інфографіка</b></td><td>Горизонтальна й вертикальна часова шкала, кроки й стрілки процесу, числа й статистика, порівняння, дерево, піраміда, цикл, смуги прогресу, оцінка зірочками, воронка, ментальна карта, матриця 2 × 2.</td></tr><tr><td><b>Колажі фото</b></td><td>Готові макети з 2–9 полями для фото (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.11\">Колаж фото</a>).</td></tr><tr><td><b>Тексти</b></td><td>Готові написи по дузі, по колу (печатка), хвилястий банер, прапор, опуклий заголовок (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.14\">Текст по дузі, колу й контуру; вигин</a>).</td></tr><tr><td><b>Заголовки й назви</b></td><td>Заголовок із підзаголовком, заголовок між лініями, номер розділу, буквиця з абзацом, цитата з автором, печатки, стрічка з написом, заголовок на смузі, рукописний, із двох шрифтів, з етикеткою, у кутиках, колонтитул сторінки, заголовок із датою.</td></tr><tr><td><b>Блоки вмісту</b></td><td>Рамки <b>Увага</b>, <b>Порада</b>, <b>Цікавинка</b>, <b>Важливо</b>, виділена цитата, вірш, список з іконками і нумерований, бічна колонка, вихідні дані, примітка про автора (з полем для фото), контакт, питання й відповідь, «Запам'ятати».</td></tr><tr><td><b>Макети сторінок</b></td><td>Цілі сторінки на область вмісту: титульна сторінка, початок розділу, галерея 2 × 2, сторінка з цитатою, сторінка для нотаток, диплом, оголошення, сторінка дня.</td></tr><tr><td><b>Стилі тексту</b></td><td>Стилі абзацу проєкту: клацання застосовує стиль до виділеного тексту, а без виділення вставляє новий текст у цьому стилі (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.4\">Стилі</a>).</td></tr><tr><td><b>Бренд</b></td><td>Логотип із бренд-кита, <span class=\"ui\">Застосувати бренд до проєкту…</span> і <span class=\"ui\">Редагувати бренд-кит…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.9\">Бренд-кит</a>).</td></tr><tr><td><b>Коди</b></td><td>QR-код і штрихкод EAN / ISBN (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.12\">QR-код і штрихкод</a>).</td></tr></tbody></table></div><p>Іконки, ілюстрації, заголовки, блоки, інфографіка, форми, макети й святкові набори — це звичайні тексти, фігури й лінії, складені в одну групу, – ви переміщуєте їх разом, а після подвійного клацання (відкрита група, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.5\">Групи</a>) змінюєте кожен текст, колір чи фігуру окремо. Кольори й шрифти вони беруть із бренд-кита (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.9\">Бренд-кит</a>), якщо він у вас є; уся вставка — це один крок скасування. На комп'ютері категорії займають щонайбільше три ряди – решту побачите, прокрутивши це місце.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-biblioteka-dzialy.png\" alt=\"Заголовок, блок «Порада», часова шкала і вірш із Бібліотеки\" loading=\"lazy\"><figcaption>Заголовок, блок «Порада», часова шкала і вірш із Бібліотеки</figcaption></figure><p>Фігура з бібліотеки — це звичайна фігура: можна змінити її колір, обведення й точки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.4\">Перо й редагування точок</a>), а замкнена фігура може бути рамкою для фото (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.7\">Зображення у фігурі</a>). Довгі категорії мають заголовки груп (напр. Основні, Багатокутники); під час пошуку заголовків немає, а результати — з усіх категорій. Шаблон із категорії <b>Планер</b> — це звичайна таблиця (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8\">Таблиця</a>): ви вводите текст у клітинки, додаєте рядки й стовпці, змінюєте лінії та кольори. Щоб планер повторювався на багатьох сторінках, вставте його в шаблон (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11\">Шаблони сторінок</a>) або на сторінку серії (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Серії</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-biblioteka-planer.png\" alt=\"Категорія «Планер» у Бібліотеці\" loading=\"lazy\"><figcaption>Категорія «Планер» у Бібліотеці</figcaption></figure><p><b>Мої елементи.</b> Логотип, нижній колонтитул фірми чи улюблену рамку можна зберегти один раз і вставляти в кожному проєкті:</p><ol class=\"kroki\"><li>Виділіть елемент або кілька елементів (напр. логотип із підписом).</li><li>Клацніть <span class=\"ui\">Зберегти в бібліотеці</span> у заголовку панелі (якщо виділено кілька — у частині <b>Виділення</b>) або в <span class=\"ui\">⋯</span> біля елемента в списку шарів.</li><li>Введіть назву. Елемент потрапить до категорії <b>Мої елементи</b>.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-moje-elementy.png\" alt=\"Мої елементи в Бібліотеці\" loading=\"lazy\"><figcaption>Мої елементи в Бібліотеці</figcaption></figure><ul class=\"punkty\"><li>Елементи зберігаються у вашому обліковому записі, тож їх видно в кожному проєкті й на кожному пристрої.</li><li>Вставлений елемент — це копія: видалення його з Бібліотеки не змінює сторінок, на яких він уже стоїть.</li><li>Олівець у куті плитки змінює назву, кошик видаляє елемент із Бібліотеки.</li><li>Елементи шаблону і текст, у якому ви саме вводите, зберегти не можна — спершу завершіть введення.</li></ul>"},{"id":"4.9","tytul":"Календар місяця","html":"<p>Сітка днів одного місяця з назвою місяця й днями тижня. Неділі та польські свята – також рухомі: Великдень, Великодній понеділок, Зелені свята, Свято Тіла і Крові Христових – виділено кольором.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kalendarz.png\" alt=\"Календар місяця та його налаштування\" loading=\"lazy\"><figcaption>Календар місяця та його налаштування</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Що змінює</th></tr></thead><tbody><tr><td><b>Місяць</b>, <b>Рік</b></td><td>Показаний місяць.</td></tr><tr><td><b>Місяць зі стовпця даних</b></td><td>На кожній сторінці серії інший місяць – зі стовпця зі значеннями на кшталт «2027-03», «marzec 2027» або «3» (рік тоді з <b>Рік зі стовпця</b>). Так з однієї сторінки-зразка виходить календар на 12 місяців (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Серії</a>).</td></tr><tr><td><b>Тиждень починається з</b></td><td>Понеділка або неділі.</td></tr><tr><td><b>Назви днів</b></td><td>Повні, скорочені або лише літери.</td></tr><tr><td><b>Дні інших місяців</b></td><td>Сірі, як звичайні дні або приховані.</td></tr><tr><td><b>Назва місяця над днями</b>, <b>Номери тижнів</b></td><td>Додатковий рядок і стовпець.</td></tr><tr><td><b>Місце для нотаток</b></td><td>Дата в куті, вищі клітинки для записів.</td></tr><tr><td><b>Польські свята</b>, <b>Назва свята під датою</b></td><td>Виділення свят і їхні назви в клітинках.</td></tr><tr><td><b>Свята з таблиці даних</b></td><td>Власні дні (дні народження, іменини, терміни) з таблиці: стовпець із датою («2027-05-26», «26.05.2027» або «26.05» – щороку) і стовпець із назвою.</td></tr><tr><td><b>Кольори календаря</b></td><td>Дні, назви, неділі, суботи, свята, дні інших місяців.</td></tr></tbody></table></div><p>Лінії, тло рядків, шрифт і вирівнювання змінюйте як у таблиці (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.5\">Лінії та фон</a>). Дати розставляє застосунок – у клітинках календаря текст не вводять.</p>"},{"id":"4.10","tytul":"Діаграма","html":"<p>Діаграма відображає числа з таблиці даних проєкту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14\">Таблиці даних</a>) і сама змінюється, коли ви змінюєте дані.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-wykres.png\" alt=\"Стовпчикова діаграма та її налаштування\" loading=\"lazy\"><figcaption>Стовпчикова діаграма та її налаштування</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Що змінює</th></tr></thead><tbody><tr><td><b>Тип</b></td><td>Стовпчикова, горизонтальна, лінійна, кругова, кільцева.</td></tr><tr><td><b>Таблиця даних</b>, <b>Підписи зі стовпця</b>, <b>Числа зі стовпців</b></td><td>Звідки діаграма бере дані; кожен позначений стовпець чисел — окрема серія (окремий колір).</td></tr><tr><td><b>Рядки</b></td><td>Усі, вибрані (від–до) або <b>рядок сторінки серії</b> – на кожній повтореній сторінці діаграма з її рядка.</td></tr><tr><td><b>Заголовок</b>, <b>Числа біля стовпчиків і секторів</b>, <b>Вісь</b>, <b>Лінії сітки</b>, <b>Легенда</b></td><td>Що видно на діаграмі.</td></tr><tr><td><b>Ширина</b>, <b>Висота</b>, <b>Шрифт</b>, <b>Розмір шрифту</b>, <b>Кольори</b></td><td>Вигляд. Маркери змінюють розмір діаграми, а не розмір шрифту.</td></tr></tbody></table></div><p>Числа в клітинках можуть мати кому, пробіли й знак %.</p>"},{"id":"4.11","tytul":"Колаж фото","html":"<p>Колаж — це готовий макет полів для фото. Перетягніть фото з комп'ютера на поле – воно потрапить у це поле. Можна також двічі клацнути колаж, вибрати поле й у частині <b>Зображення у фігурі</b> вставити зображення з проєкту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.7\">Зображення у фігурі</a>).</p><p>На панелі колажу можна змінити <b>Макет</b> (поля додаються або зникають, фото в перших полях залишаються), <b>Відстань між фото</b>, <b>Заокруглення кутів</b>, <b>Ширину</b> і <b>Висоту</b>.</p>"},{"id":"4.12","tytul":"QR-код і штрихкод","html":"<p>Код вставте з <span class=\"ui\">Бібліотека</span>, категорія <b>Коди</b>. У частині <b>Код</b> панелі налаштуйте решту:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Що означає</th></tr></thead><tbody><tr><td><b>Тип</b></td><td><b>QR-код</b> або <b>Штрихкод EAN-13 / ISBN</b> (напр. ISBN на обкладинці книги).</td></tr><tr><td><b>Що містить</b> (QR)</td><td><b>Адреса сайту</b>, <b>Текст</b>, <b>Ел. пошта</b>, <b>Телефон</b> або <b>Мережа Wi-Fi</b>.</td></tr><tr><td><b>Корекція помилок</b> (QR)</td><td>Яку частину коду можна закрити: від <b>Низька (7%)</b> — найменший код — до <b>Найвища (30%)</b>, напр. під логотип.</td></tr><tr><td><b>Номер EAN або ISBN</b></td><td>Контрольна цифра допишеться сама; ISBN можна вводити з дефісами.</td></tr><tr><td><b>Розмір</b></td><td><span class=\"ui\">Номінальний розмір (100%)</span> встановлює код EAN на 37,29 × 25,93 мм.</td></tr><tr><td><b>Колір коду</b>, <b>Тло</b>, <b>Тиха зона</b></td><td>Код має бути темним на світлому тлі, з порожньою смугою навколо.</td></tr></tbody></table></div><p>Поле з даних у вмісті — напр. <code>{adres}</code> або <code>{isbn}</code> — дає інший код на кожній сторінці серії (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Поля в тексті</a>).</p><p>Якщо код буде замалий, засвітлий або з помилковим вмістом, про це нагадає панель і <b>Перевірити перед друком</b>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kod.png\" alt=\"QR-код і його налаштування\" loading=\"lazy\"><figcaption>QR-код і його налаштування</figcaption></figure>"},{"id":"4.13","tytul":"Копіювати стиль (пензель формату)","html":"<p>Вигляд одного елемента можна перенести на інший одним клацанням — без переписування кольорів і товщин.</p><p><span class=\"ui\">Копіювати стиль</span> (пензель) є в заголовку панелі властивостей, у <span class=\"ui\">⋯</span> біля елемента в списку шарів, а на телефоні також під <span class=\"ui\">⋯</span> панелі вставлення (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.4\">Панель вставлення</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-malarz.png\" alt=\"Копіювати стиль у заголовку панелі\" loading=\"lazy\"><figcaption>Копіювати стиль у заголовку панелі</figcaption></figure><ol class=\"kroki\"><li>Виділіть елемент, який уже має потрібний вигляд.</li><li>Клацніть <span class=\"ui\">Копіювати стиль</span> (<kbd>Ctrl</kbd>+<kbd>Alt</kbd>+<kbd>C</kbd>).</li><li>Клацніть елемент, який має отримати цей вигляд.</li></ol><ul class=\"punkty\"><li><b>Подвійне клацання</b> на <span class=\"ui\">Копіювати стиль</span> — безперервний режим: клацаєте наступні елементи, доки не натиснете <kbd>Esc</kbd>.</li><li><b>Фрагмент тексту:</b> у тексті, який редагуєте, виділіть слова й клацніть <span class=\"ui\">Копіювати стиль</span> — вигляд отримає лише виділений фрагмент. Так само можна скопіювати вигляд із фрагмента.</li></ul><p>Переноситься все, що стосується вигляду, — кольори, градієнти, обведення, шрифт, інтервали, фільтри фото, непрозорість, тінь, оздоблення, — а вміст залишається. Таблиці, коди, діаграми й календарі мають власні налаштування і вигляду не переймають.</p>"},{"id":"4.14","tytul":"Бульбашка","html":"<p>Бульбашка – це один елемент: рамка тексту з бульбашкою навколо. Вставте її з <span class=\"ui\">Бібліотека</span>, категорія <b>Бульбашки</b>. Пишете в ній, як у звичайній рамці тексту, – бульбашка росте разом із текстом.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Тип</th><th>Вигляд</th></tr></thead><tbody><tr><td><b>мова</b></td><td>Овал із хвостиком.</td></tr><tr><td><b>думка</b></td><td>Хмаринка з кружечками замість хвостика.</td></tr><tr><td><b>крик</b></td><td>Вибух із шипами.</td></tr><tr><td><b>шепіт</b></td><td>Овал із пунктирним контуром.</td></tr><tr><td><b>оповідь</b></td><td>Прямокутна рамка без хвостика.</td></tr></tbody></table></div><ul class=\"punkty\"><li>Кінчик хвостика пересуваєте помаранчевим маркером на сторінці – поставте його біля рота персонажа. Хвостик рухається разом із бульбашкою.</li><li>У частині <b>Бульбашка</b> панелі змінюєте <b>Тип</b>, вмикаєте чи вимикаєте <b>Хвостик</b>, задаєте <b>Заливку</b>, <b>Контур</b> і <b>Товщину контуру</b>. Шрифт, розмір і колір тексту – як у звичайному тексті (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5\">Текст</a>).</li><li>У PDF бульбашка виходить векторною, так само як на сторінці.</li></ul>"}]},
  {"nr":"5","tytul":"Текст","czesc":"Редактор","ikona":"olowek","wstep":"Текстові рамки, їхній вигляд, стилі й верстка — від одного напису до тексту книги, що тече через багато сторінок.","sekcje":[{"id":"5.1","tytul":"Введення тексту","html":"<p>Вставте текст кнопкою <span class=\"ui\">Текст</span> (<kbd>T</kbd>) і одразу пишіть. На наявному тексті клацніть двічі, щоб писати в ньому; <kbd>Esc</kbd> завершує введення. <kbd>Enter</kbd> починає новий абзац.</p><p>Ширину рамки змінюйте боковими маркерами — текст перерозкладається, літери не розтягуються. Висота рамки росте разом із текстом, якщо ви не задасте фіксовану висоту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.6\">Текстова рамка</a>).</p><figure><img src=\"img/instrukcja/wstawianie.png\" alt=\"Текст на сторінці\" loading=\"lazy\"><figcaption>Текст на сторінці</figcaption></figure>"},{"id":"5.2","tytul":"Вигляд тексту","html":"<p>Властивості виділеного тексту:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><b>Стиль</b></td><td>Збережений вигляд тексту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.4\">Стилі</a>).</td></tr><tr><td><b>Шрифт</b></td><td>Гарнітура. У списку почніть вводити назву, щоб її знайти (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.8\">Шрифти</a>).</td></tr><tr><td><b>Розмір</b></td><td>У пунктах (pt). Кружечок праворуч — це <b>колір тексту</b>.</td></tr><tr><td><span class=\"ui\">B</span> <span class=\"ui\">I</span> <span class=\"ui\">U</span> <span class=\"ui\">S</span></td><td>Жирний, курсив, підкреслення, закреслення. Сірі, коли шрифт не має такого накреслення.</td></tr><tr><td><b>Вирівнювання</b></td><td>Ліворуч, по центру, праворуч, по ширині.</td></tr><tr><td><b>Міжрядковий інтервал</b></td><td>Відстань між рядками; 1 — одинарний.</td></tr><tr><td><b>Міжлітерний інтервал</b></td><td>Розрідження літер; від'ємне значення стискає текст.</td></tr><tr><td><b>Регістр літер</b></td><td><span class=\"ui\">AA</span> — усі великі, <span class=\"ui\">aa</span> — усі малі, <span class=\"ui\">Aᴀ</span> — капітель: це лише вигляд, вміст залишається таким, як його введено. <span class=\"ui\">Aa</span> — «як у реченні»: змінює сам вміст.</td></tr><tr><td><b>Список</b></td><td>Маркери, тире або номери перед кожним абзацом (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.5\">Списки</a>).</td></tr><tr><td><b>Обведення літер</b></td><td>Колір і <b>Товщина обведення літер</b> — контур навколо кожної літери.</td></tr></tbody></table></div><figure><img src=\"img/instrukcja/wlasciwosci.png\" alt=\"Властивості тексту\" loading=\"lazy\"><figcaption>Властивості тексту</figcaption></figure>"},{"id":"5.3","tytul":"Фрагмент тексту","html":"<p>Двічі клацніть текст, виділіть фрагмент і змініть його тими самими налаштуваннями — панель покаже «Ви змінюєте лише виділений фрагмент тексту.» Так можна виділити жирним одне слово або змінити колір одного рядка. Вигляд фрагмента з полем (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Поля в тексті</a>) переходить на вставлене значення.</p>"},{"id":"5.4","tytul":"Стилі","html":"<p><b>Стиль</b> — це збережений вигляд тексту, напр. «Заголовок», «Підпис», «Бульбашка». Застосуйте його до всіх текстів, які мають виглядати однаково.</p><ul class=\"punkty\"><li>Список <b>Стиль</b> у властивостях застосовує стиль до виділеного тексту.</li><li><span class=\"ui\">Новий стиль</span> зберігає вигляд виділеного тексту під новою назвою.</li><li>Коли ви зміните текст зі стилем, з'являться <span class=\"ui\">Оновити стиль</span> — змінює всі тексти з цим стилем у всьому проєкті — і <span class=\"ui\">Відновити</span> — повертає вигляд зі стилю.</li><li>Стиль зберігає також налаштування <b>Верстки абзацу</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.9\">Верстка абзацу</a>) — напр. перенесення слів для всього тексту книги.</li></ul><p><b>Символьний стиль</b> — це збережений вигляд фрагмента тексту, напр. «Виділення» або «Власна назва».</p><ol class=\"kroki\"><li>Виділіть фрагмент тексту (двічі клацніть текст і виділіть слова).</li><li>Налаштуйте його вигляд (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.3\">Фрагмент тексту</a>), потім у частині <b>Стиль тексту</b> виберіть <span class=\"ui\">Новий символьний стиль</span>.</li><li>Інші фрагменти виділіть і виберіть стиль зі списку <b>Символьний стиль</b>. Без виділення стиль отримує весь текст.</li></ol><p><span class=\"ui\">Оновити стиль</span> переносить вигляд виділення в стиль — зміняться всі фрагменти з цим стилем у проєкті. Видалений символьний стиль не змінює вигляду фрагментів.</p>"},{"id":"5.5","tytul":"Списки","html":"<p>Список <b>Список</b> у властивостях тексту: <b>Маркери</b>, <b>Тире</b> або <b>Номери</b>. Знак списку стоїть перед кожним абзацом, а наступні рядки абзацу — рівно під першим. У тексті, що тече через кілька рамок, нумерація продовжується. Скорочення: <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>8</kbd> (маркери) і <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>7</kbd> (номери).</p>"},{"id":"5.6","tytul":"Текстова рамка","html":"<p>Частина <b>Текстова рамка</b> знадобиться, коли текст має займати стале місце — напр. тексти з даних різної довжини (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.6\">Текст різної довжини</a>):</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><b>Фіксована висота рамки</b></td><td>Рамка не росте з текстом. Висоту вводите в мм або змінюєте верхнім чи нижнім маркером.</td></tr><tr><td><b>Вертикальне вирівнювання</b></td><td>Угорі, посередині або внизу рамки.</td></tr><tr><td><b>Зменшувати текст, якщо він не вміщується</b></td><td>Шрифт зменшується, доки текст не вміститься, — але не менше від <b>найменшого розміру</b>.</td></tr></tbody></table></div><p>Текст, який і так не вміщується, обрізається внизу рамки й потрапляє до списку попереджень.</p><figure><img src=\"img/instrukcja/ramka-tekstu.png\" alt=\"Рамка з фіксованою висотою\" loading=\"lazy\"><figcaption>Рамка з фіксованою висотою</figcaption></figure>"},{"id":"5.7","tytul":"Колонки й текст через кілька рамок","html":"<p>Довший текст може текти через кілька рамок: те, що не вміщується в першій, переходить до наступної. Частина <b>Перетікання тексту</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Кнопка</th><th>Що робить</th></tr></thead><tbody><tr><td><span class=\"ui\">Розділити на колонки</span></td><td>Перетворює рамку на 2, 3 або 4 колонки поруч.</td></tr><tr><td><span class=\"ui\">Додати рамку з продовженням</span></td><td>Нова рамка поруч (або нижче), до якої тече решта тексту.</td></tr><tr><td><span class=\"ui\">Продовження на наступній сторінці</span></td><td>Рамка на наступній сторінці — за потреби разом із новою сторінкою.</td></tr><tr><td><span class=\"ui\">Зв'язати текстові рамки</span></td><td>Зв'язує дві виділені рамки.</td></tr><tr><td><span class=\"ui\">Роз'єднати рамки</span></td><td>Кожна рамка залишається зі своєю частиною тексту.</td></tr><tr><td><span class=\"ui\">Попередня рамка</span>, <span class=\"ui\">Наступна рамка</span></td><td>Переходять до сусідньої рамки, також на іншій сторінці.</td></tr></tbody></table></div><p>Пишете в будь-якій рамці, а текст перетікає одразу. Вигляд тексту (шрифт, розмір, список) спільний для зв'язаних рамок. Фіолетова лінія показує, куди тече текст із виділеної рамки.</p><p><b>Довгий текст через багато сторінок (книга).</b> Увімкніть <b>Додавати сторінки, доки весь текст не поміститься</b> — коли текст не вміщується в останній рамці, після її сторінки додаються нові сторінки (у тому самому розділі, з його шаблонами) з рамкою в тому самому місці й розмірі. Коли тексту поменшає, порожні додані сторінки в кінці зникають. Сторінки додаються після завершення введення (Esc або клацання поруч), після вставлення і після зміни вигляду тексту.</p><p><b>Абзац з нової сторінки</b> (напр. розділ): поставте курсор в абзаці й увімкніть <b>Цей абзац з нової сторінки (напр. розділ)</b> — абзац і все після нього переходить до наступної рамки. Вибір робиться для кожного абзацу окремо: розділ може починатися з нової сторінки або текти далі. Якщо додавання сторінок увімкнено, наступна рамка з'являється сама.</p><figure><img src=\"img/instrukcja/uklad.png\" alt=\"Колонки, списки й таблиця\" loading=\"lazy\"><figcaption>Колонки, списки й таблиця</figcaption></figure>"},{"id":"5.8","tytul":"Шрифти","html":"<p>На вибір є 55 родин шрифтів із польськими літерами, які можна використовувати в комерційному друці: гротески для тексту (напр. Inter, Lato, Roboto), вузькі для заголовків (Oswald, Bebas Neue), антикви (Lora, Merriweather, Playfair Display, EB Garamond), рукописні й декоративні (Caveat, Pacifico, Dancing Script), коміксові (Bangers для вигуків, Comic Neue і Pangolin для діалогів) і друкарські машинки. Більшість має й українські літери (кирилицю) – зокрема Inter, Roboto, Lora і Pangolin; якщо шрифт їх не має, експорт PDF про це скаже (такий текст піде як зображення).</p><p><span class=\"ui\">⋯</span> → <span class=\"ui\">Шрифти проєкту…</span> показує зразки, дає файли шрифтів для завантаження (напр. для друкарні) і дозволяє завантажити <b>власний шрифт</b> (TTF, OTF, WOFF, WOFF2; кожне накреслення окремо) — також зі списку шрифтів: <span class=\"ui\">+ Завантажити власний шрифт…</span>. Завантажений шрифт залишається в обліковому записі, у «Моїх шрифтах».</p><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> Для друку власний шрифт найкраще завантажувати як TTF або OTF, окремим файлом для жирного і курсиву. Інші файли потраплять у PDF як криві — текст буде чітким, але виділити його не вдасться.</p><figure><img src=\"img/instrukcja/czcionki.png\" alt=\"Вікно шрифтів\" loading=\"lazy\"><figcaption>Вікно шрифтів</figcaption></figure><p>Угорі списку <b>Шрифт</b> є <b>Використано в проєкті</b> — шрифти з текстів усіх сторінок, шаблонів і стилів, найчастіші спершу, з кількістю використань (напр. «Inter · 5×»). Нижче — повний список.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-czcionki-uzyte.png\" alt=\"«Використано в проєкті» у списку шрифтів\" loading=\"lazy\"><figcaption>«Використано в проєкті» у списку шрифтів</figcaption></figure><p>Якщо у вас є бренд-кит (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.9\">Бренд-кит</a>), над ними є група <b>Бренд</b> — шрифт заголовків і шрифт тексту бренду.</p>"},{"id":"5.9","tytul":"Верстка абзацу","html":"<p>Згортана частина <b>Верстка абзацу</b> у властивостях тексту визначає, як текст розбивається на рядки. Ті самі налаштування можна зберегти в стилі (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.4\">Стилі</a>).</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Що робить</th></tr></thead><tbody><tr><td><b>Польські правила верстки</b></td><td>Увімкнено в нових текстах. Рядок не розривається після скорочення (np., tj., ul., dr…), після ініціалу (J. Kowalski), між числом і одиницею, датою або наступними цифрами (5 kg, 12 maja, 10 000), а тире не починає рядка — як у польських стандартах PN-83/P-55366 і PN-70/P-55036. Разом із <b>Переносити слова</b>: щонайбільше 3 рядки з перенесенням поспіль, щонайменше 2 літери перед дефісом і 3 після нього, без перенесення останнього слова абзацу і слів із великої літери (слово, довше за рядок, переноситься завжди). Під час вирівнювання по ширині пробіли можуть також трохи стискатися (до 20 %), тож рядків із «дірками» менше. У тексті, що тече через рамки, заголовок (короткий абзац більшим або жирним шрифтом) не залишається сам у кінці рамки — він переходить разом із наступним абзацом, а рамки на лівій і правій сторінці розвороту закінчуються на однаковій висоті (вирівнювання шпальт: коли висячі рядки або заголовок скоротили одну, друга теж коротша). Під перемикачем є зауваження про місця, що не відповідають правилам, і кнопка <b>Виправити знаки</b>: лапки „…” замість прямих, коротке тире (–) замість дефіса між пробілами, три крапки одним знаком (…) замість трьох крапок, без подвійних пробілів і пробілів перед комою — форматування фрагментів зберігається.</td></tr><tr><td><b>Розбивати весь абзац одразу</b></td><td>Увімкнено в нових текстах. Рядки абзацу добираються разом, а не по черзі — як «композитор абзацу» в програмах верстки. Програма зважує всі можливі місця розриву й вибирає варіант із найрівнішими пробілами між словами і якнайменшою кількістю перенесених слів; польські правила верстки й далі діють. Найкраще це видно при вирівнюванні по ширині: замість одного рядка з великими «дірками» пробіли розподіляються на кілька рядків. Абзац, що обтікає інший елемент, має буквицю або табуляції, розбивається рядок за рядком.</td></tr><tr><td><b>Переносити слова</b></td><td>Довгі слова переносяться в кінці рядка за польськими правилами — текст, вирівняний по ширині, тоді не має «дірок». Поруч задаєте найкоротше слово для перенесення і скільки літер залишається перед дефісом і після нього.</td></tr><tr><td><b>Сполучники в кінці рядка</b></td><td>Поодинокі <b>a, i, o, u, w, z</b> (або також дволітерні: do, na, że…) переходять на наступний рядок разом зі словом, як у польській верстці.</td></tr><tr><td><b>Висячі рядки</b></td><td>Текст, що тече через кілька рамок (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.7\">Колонки й текст через кілька рамок</a>), не залишає самотнього рядка абзацу внизу чи вгорі рамки.</td></tr><tr><td><b>Вирівняти за сіткою базових ліній</b></td><td>Рядки стають на лінії сітки розділу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.13\">Сітка базових ліній</a>).</td></tr><tr><td><b>Не обтікати інші елементи</b></td><td>Текст лежить на елементах з обтіканням, замість обтікати їх (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.12\">Обтікання текстом</a>) — напр. підпис на фото.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-sklad-akapitu.png\" alt=\"Верстка абзацу у властивостях тексту\" loading=\"lazy\"><figcaption>Верстка абзацу у властивостях тексту</figcaption></figure><p><b>Попередження про верстку.</b> Текст, що не відповідає польським правилам (сполучник або скорочення в кінці рядка, число, відокремлене від одиниці, тире на початку рядка, понад 3 рядки з перенесенням поспіль, перенесене останнє слово абзацу, дуже короткий останній рядок абзацу, розріджений рядок, прямі лапки, три крапки, подвійні пробіли…), з'являється в попередженнях редактора і в перевірці перед друком (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20.1\">Список зауважень</a>) із прикладом місця. Попередження для навмисного тексту вимкніть кнопкою <b>Вимкнути</b>.</p>"},{"id":"5.10","tytul":"Буквиця","html":"<p>Буквиця — це збільшена перша літера абзацу на кілька рядків. У частині <b>Верстка абзацу</b> виберіть <b>Буквиця</b>: <b>на 2 рядки</b> … <b>на 5 рядків</b>. Літера росте від верхнього краю першого рядка до базової лінії останнього, а текст її обтікає. <b>Шрифт буквиці</b> і <b>Колір буквиці</b> можуть відрізнятися від тексту.</p><p>Буквицю отримує перший абзац тексту. У тексті, що тече через кілька рамок, — лише в першій рамці.</p><figure><img src=\"img/instrukcja/sklad.png\" alt=\"Буквиця, перенесення слів, табуляції з крапками і текст, що обтікає коло\" loading=\"lazy\"><figcaption>Буквиця, перенесення слів, табуляції з крапками і текст, що обтікає коло</figcaption></figure>"},{"id":"5.11","tytul":"Табуляції","html":"<p>Клавіша <kbd>Tab</kbd> у тексті, який ви редагуєте, вставляє табуляцію: текст після неї перескакує до найближчої позиції. Без заданих позицій табуляції стоять кожні 12,5 мм.</p><p>У частині <b>Верстка абзацу</b> <span class=\"ui\">Додати табуляцію</span> додає позицію. Кожна має:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Поле</th><th>Значення</th></tr></thead><tbody><tr><td><b>Табуляція N</b></td><td>Позиція в мм від лівого краю рамки.</td></tr><tr><td><b>Вирівнювання</b></td><td><b>ліворуч</b>, <b>по центру</b>, <b>праворуч</b> або <b>по комі</b> (числа з комою одне під одним).</td></tr><tr><td><b>Заповнення</b></td><td>Порожньо, крапки, рисочки або лінія перед текстом — напр. зміст «Розділ 1 . . . . . 12».</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-tabulatory.png\" alt=\"Табуляція праворуч із крапками\" loading=\"lazy\"><figcaption>Табуляція праворуч із крапками</figcaption></figure>"},{"id":"5.12","tytul":"Обтікання текстом","html":"<p>Фото, фігура або група можуть відштовхувати текст. Виділіть елемент і в частині <b>Інші</b> виберіть <b>Обтікання текстом</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Значення</th><th>Що означає</th></tr></thead><tbody><tr><td><b>текст обтікає рамку елемента</b></td><td>Рядки закінчуються перед прямокутником елемента (або починаються за ним).</td></tr><tr><td><b>текст обтікає фігуру</b></td><td>Для еліпса, багатокутника і фігури з пера — рядки йдуть уздовж її краю.</td></tr><tr><td><b>текст перескакує під елемент</b></td><td>Поруч з елементом тексту немає, продовження — під ним.</td></tr></tbody></table></div><p><b>Відступ тексту від елемента</b> — це вільне місце навколо елемента (типово 2 мм). Обтікання діє на всі тексти на сторінці — також під час переміщення елемента. Текст вибирає той бік елемента, з якого має більше місця.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-oblewanie.png\" alt=\"Обтікання текстом у частині «Інші»\" loading=\"lazy\"><figcaption>Обтікання текстом у частині «Інші»</figcaption></figure>"},{"id":"5.13","tytul":"Сітка базових ліній","html":"<p>Сітка базових ліній ставить рядки всіх колонок і сторінок на однаковій висоті — як у книгах, де рядки з обох боків аркуша збігаються, якщо подивитися на світло.</p><ol class=\"kroki\"><li>У налаштуваннях розділу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>) увімкніть <b>Сітка базових ліній у цьому розділі</b>: <b>Крок</b> (зазвичай міжрядковий інтервал основного тексту) і <b>Перша лінія</b> (мм від верхнього краю сторінки, зазвичай верхнє поле).</li><li>У меню вигляду (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.6\">Правий нижній кут і меню вигляду</a>) <b>Сітка базових ліній</b> показує ці лінії на сторінці.</li><li>Текстам, які мають стояти на сітці, увімкніть <b>Вирівняти за сіткою базових ліній</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.9\">Верстка абзацу</a>) — найкраще в стилі основного тексту.</li></ol>"},{"id":"5.14","tytul":"Текст по дузі, колу й контуру; вигин","html":"<p>Виділіть текст і в частині <b>Форма тексту</b> панелі виберіть <b>Форму</b>. Готові приклади є також у <span class=\"ui\">Бібліотека</span>, у категорії <b>Тексти</b>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-ksztalt-tekstu.png\" alt=\"Текст по дузі, по колу і вигнутий\" loading=\"lazy\"><figcaption>Текст по дузі, по колу і вигнутий</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Форма</th><th>Що робить і що налаштовуєте</th></tr></thead><tbody><tr><td><b>Дуга</b></td><td>Напис по дузі. <b>Вигин</b> у %: додатний – дуга вгору, від'ємний – униз.</td></tr><tr><td><b>Коло (контур)</b>, <b>Еліпс</b></td><td>Напис довкола, напр. печатка: радіус, початок, літери назовні або всередину.</td></tr><tr><td><b>По контуру</b></td><td>Напис уздовж лінії будь-якої фігури на сторінці (намальованої пером або з Бібліотеки) — виберіть її в <b>Лінія з фігури на сторінці</b>.</td></tr><tr><td><b>Вигинання</b></td><td>Літери, вигнуті як дуга, опуклість, хвиля, прапор або звуження; <b>Сила вигину</b> у %.</td></tr></tbody></table></div><ul class=\"punkty\"><li>Для дуги й вигинів маркер ◆ під текстом вигинає текст сильніше або слабше.</li><li>Двічі клацніть текст, щоб його виправити, — під час введення він стоїть прямо.</li><li>Текст по фігурі — це один рядок; шрифт, колір, стилі й поля <code>{…}</code> працюють як звичайно.</li><li><b>Прямо</b> повертає звичайний текст.</li></ul>"},{"id":"5.15","tytul":"Знайти й замінити","html":"<p>Лупа на верхній панелі або <span class=\"ui\">⋯</span> → <span class=\"ui\">Знайти й замінити…</span> (<kbd>Ctrl</kbd>+<kbd>F</kbd>; <kbd>Ctrl</kbd>+<kbd>H</kbd> — одразу з полем заміни).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-znajdz.png\" alt=\"Знайти й замінити поруч зі сторінкою\" loading=\"lazy\"><figcaption>Знайти й замінити поруч зі сторінкою</figcaption></figure><ol class=\"kroki\"><li>Введіть шуканий текст. Список показує кожен збіг: сторінку або шаблон і шматок тексту навколо.</li><li>Клацніть збіг (або <kbd>Enter</kbd> у полі, <kbd>Shift</kbd>+<kbd>Enter</kbd> — назад) — редактор відкриє цю сторінку й виділить знайдений фрагмент.</li><li>Щоб замінити, введіть новий текст у другому полі й клацніть <span class=\"ui\">Замінити</span> (вибраний збіг) або <span class=\"ui\">Замінити всі</span>.</li></ol><div class=\"tabela-instrukcji\"><table><thead><tr><th>Параметр</th><th>Значення</th></tr></thead><tbody><tr><td><b>Враховувати регістр</b></td><td>«Календар» не знайде «календар».</td></tr><tr><td><b>Цілі слова</b></td><td>«кіт» не знайде «котика».</td></tr><tr><td><b>Також у даних</b></td><td>Шукає також у клітинках таблиць даних (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14\">Таблиці даних</a>).</td></tr><tr><td><b>У назвах стилів</b></td><td>Шукає також у назвах стилів абзацу й символьних стилів (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.4\">Стилі</a>).</td></tr></tbody></table></div><ul class=\"punkty\"><li>Пошук охоплює всі сторінки й шаблони, також тексти в групах.</li><li>Поля у фігурних дужках, напр. <code>{miesiac}</code>, залишаються недоторканими — якщо ви не введете дужку в шуканому тексті.</li><li>Вигляд фрагментів (напр. жирне слово) залишається на своєму місці після заміни.</li><li><span class=\"ui\">Замінити всі</span> скасуєте одним <span class=\"ui\">Скасувати</span>.</li></ul>"},{"id":"5.16","tytul":"Перевірка правопису","html":"<p>Слова, яких немає в польському словнику, підкреслено хвилястою червоною лінією — лише в редакторі, ніколи в PDF.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-pisownia-dymek.png\" alt=\"Підказки біля підкресленого слова\" loading=\"lazy\"><figcaption>Підказки біля підкресленого слова</figcaption></figure><ol class=\"kroki\"><li>Двічі клацніть текст і клацніть (на телефоні торкніться) підкреслене слово — або клацніть його правою кнопкою миші. Біля слова з'явиться бульбашка з підказками й <span class=\"ui\">Додати до словника</span>.</li><li>Клацніть підказку (напр. «wcześniej») — слово зміниться в цьому місці.</li><li>Власну назву, якої словник не знає (напр. назву фірми), додайте кнопкою <span class=\"ui\">Додати до словника</span>. Ваш словник зберігається в обліковому записі, тож працює в кожному проєкті.</li></ol><p>Усі підозрілі слова виділеного тексту видно також на панелі, у частині <b>Правопис</b> — там підказка змінює слово в усіх місцях цього тексту.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-pisownia.png\" alt=\"Частина «Правопис» на панелі тексту\" loading=\"lazy\"><figcaption>Частина «Правопис» на панелі тексту</figcaption></figure><ul class=\"punkty\"><li>Пропускаються поля <code>{…}</code>, числа, слова з цифрами, адреси сайтів та e-mail.</li><li>Вимкнути перевірку можна в меню вигляду: <b>Перевіряти правопис</b>.</li></ul>"},{"id":"5.17","tytul":"Текст ШІ: виправлення і переклад","html":"<p>ШІ виправить, скоротить або перекладе текст – у кожному проєкті. Пише Google Gemini вашим ключем (як отримати ключ – <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.11\">Зображення ШІ</a>); одна зміна коштує частку гроша.</p><ol class=\"kroki\"><li>Виділіть текстову рамку – зміните весь текст. Або двічі клацніть текст і виділіть фрагмент – зміните лише його.</li><li>Клацніть <span class=\"ui\">ШІ ▾</span> на панелі вставлення → <b>Покращити або перекласти текст…</b>.</li><li>Клацніть, що зробити: <span class=\"ui\">Скоротити</span>, <span class=\"ui\">Розширити</span>, <span class=\"ui\">Простіше</span>, <span class=\"ui\">Урочистіше</span>, <span class=\"ui\">Виправити помилки</span>, <span class=\"ui\">Польською</span>, <span class=\"ui\">Англійською</span> або <span class=\"ui\">Українською</span>.</li><li>За мить результат з’явиться в полі <b>Результат (можна виправити)</b>. Виправте його, якщо хочете, або клацніть іншу кнопку, щоб спробувати інакше.</li><li><span class=\"ui\">Замінити</span> вставляє результат на місце тексту. <kbd>Ctrl</kbd>+<kbd>Z</kbd> скасовує.</li></ol><p>Поля у фігурних дужках, напр. <code>{imie}</code>, лишаються без змін.</p><p><b>Переклад усього проєкту.</b> Для багатьох текстів одразу (напр. календар трьома мовами) тримайте тексти в таблиці даних і перекладіть стовпець: кнопка <b>✦</b> біля назви стовпця у вікні <b>Дані</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14.6\">Заповнити стовпець за допомогою ШІ</a>), напр. «переклади стовпець opis англійською». Інші зміни в багатьох місцях одразу зробить асистент ШІ (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Асистент ШІ в Makietka (власний ключ)</a>).</p>"}]},
  {"nr":"6","tytul":"Фігури, лінії та кольори","czesc":"Редактор","ikona":"olowek","wstep":"Фігури, лінії, малювання й кольори: заливки, градієнти та обведення.","sekcje":[{"id":"6.1","tytul":"Прямокутник, еліпс і багатокутник","html":"<p><span class=\"ui\">Фігури ▾</span> → <b>Прямокутник</b>, <b>Еліпс</b> і <b>Багатокутник або зірка</b> вставляють фігури із заливкою та обведенням (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.5\">Заливка</a>, <a href=\"#\" data-cel=\"6.6\">Обведення</a>). <b>Багатокутник або зірка</b> спершу пропонує вибір: трикутник, ромб, п'яти-, шести- й восьмикутник або зірку з 4, 5, 6, 8 чи 12 променями. Клавіша <kbd>P</kbd> одразу вставляє трикутник. Розділ <b>Форма</b>:</p><ul class=\"punkty\"><li>прямокутник — <b>Заокруглення</b> кутів у мм,</li><li>багатокутник — ті самі готові фігури, що й під час вставлення (трикутник … зірка 12), <b>Кількість сторін</b> (3–24) і перемикач <b>Зірка</b>; зміна зберігає розташування й розмір.</li></ul>"},{"id":"6.2","tytul":"Лінія","html":"<p><span class=\"ui\">Фігури ▾</span> → <b>Лінія</b> вставляє відрізок. Розділ <b>Лінія</b>: <b>Колір</b>, <b>Товщина</b> в мм і <b>Тип</b> — суцільна, штрихова, пунктирна або штрих – крапка (штрихи ростуть разом із товщиною). З <kbd>Shift</kbd> лінія буде горизонтальною, вертикальною або під кутом 45°. Лінія, намальована від руки, і фігура з пера мають той самий розділ, а замкнена фігура з пера — ще й <b>Заливку</b>. Готові лінії (тонка, товста, штрихова, подвійна, вертикальна, декоративні) є в Бібліотеці, у категорії <b>Лінії та роздільники</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.8\">Бібліотека</a>).</p>"},{"id":"6.3","tytul":"Малювання від руки","html":"<p><span class=\"ui\">Фігури ▾</span> → <b>Малювання від руки</b> (<kbd>B</kbd>): ведіть по сторінці, як олівцем, — тремтіння руки згладжується. Кожен штрих — окремий елемент. Режим лишається ввімкненим, тож можна намалювати кілька ліній.</p><p>Колір і товщину наступних ліній задаєте у властивостях, у розділі <b>Пензель</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.5\">Властивості й шари</a>). <span class=\"ui\">Завершити малювання</span> або <kbd>Esc</kbd> завершує малювання.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-rysowanie.png\" alt=\"Малювання: колір і товщина пензля\" loading=\"lazy\"><figcaption>Малювання: колір і товщина пензля</figcaption></figure>"},{"id":"6.4","tytul":"Перо й редагування точок","html":"<p><span class=\"ui\">Фігури ▾</span> → <b>Перо</b> (<kbd>N</kbd>) створює фігуру з точок:</p><ul class=\"punkty\"><li>клацання ставить кутову точку, клацання з перетягуванням — точку з дугою,</li><li>клацання першої точки замикає фігуру,</li><li><kbd>Enter</kbd> або подвійне клацання завершує відкриту фігуру,</li><li><kbd>Backspace</kbd> скасовує останню точку, <kbd>Esc</kbd> відкидає розпочату фігуру.</li></ul><p><b>Редагування точок:</b> двічі клацніть фігуру або виберіть <span class=\"ui\">Редагувати точки</span>. Перетягуйте точки, а маркерами виділеної точки змінюйте дуги. Подвійне клацання на лінії додає точку, <kbd>Delete</kbd> видаляє виділену. <kbd>Enter</kbd> підтверджує, <kbd>Esc</kbd> повертає фігуру до стану перед редагуванням. Так само змінюється й лінія, намальована від руки.</p><figure><img src=\"img/instrukcja/pioro.png\" alt=\"Редагування точок\" loading=\"lazy\"><figcaption>Редагування точок</figcaption></figure>"},{"id":"6.5","tytul":"Заливка","html":"<p>Розділ <b>Заливка й обведення</b>, список <b>Заливка</b>:</p><p><b>Немає</b>, <b>Один колір</b>, <b>Лінійний градієнт</b> (в одному напрямку, під заданим <b>Кутом</b>), <b>Радіальний градієнт</b> (від центру назовні, охоплення — <b>Радіус</b>) або <b>Візерунок</b>.</p><p>Смуга градієнта показує кольори. <span class=\"ui\">Додати колір</span> додає ще один; клацання кольору на смузі дає змогу змінити його та його положення у %, <span class=\"ui\">Видалити цей колір із градієнта</span> його видаляє.</p><p>Кожен колір градієнта має поле <b>Непрозорість</b> — наприклад, колір, що переходить у прозорість над фото.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-krycie-przejscia.png\" alt=\"Непрозорість кольору в градієнті\" loading=\"lazy\"><figcaption>Непрозорість кольору в градієнті</figcaption></figure><p><b>Візерунок</b> заповнює фігуру повторюваним візерунком із Бібліотеки — смуги, крапки, клітинка, ялинка, хвилі та інші. Ви вибираєте його з плиток, а під ними задаєте <b>Колір візерунка</b>, <b>Колір тла</b>, <b>Масштаб візерунка</b> і <b>Поворот візерунка</b>. Візерунок не розтягується, коли ви змінюєте розмір фігури, а у файлі PDF лишається чітким (векторним). Замкнена фігура з пера та фігури з Бібліотеки мають у розділі <b>Лінія</b> перемикач <b>Заповнити візерунком</b>. Плитка візерунка в Бібліотеці, коли фігуру виділено, запитує: <span class=\"ui\">Заповнити виділену фігуру</span> чи <span class=\"ui\">Вставити на сторінку</span>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-wzor-ksztaltu.png\" alt=\"Фігури, заповнені візерунком\" loading=\"lazy\"><figcaption>Фігури, заповнені візерунком</figcaption></figure>"},{"id":"6.6","tytul":"Обведення","html":"<p>Колір обведення і <b>Товщина обведення</b> в мм. Товщина не змінюється, коли ви збільшуєте фігуру. Коли обведення ввімкнене, є також <b>Непрозорість обведення</b> (напівпрозора рамка) і <b>Тип лінії</b> — суцільна, штрихова, пунктирна або штрих – крапка; штрихи ростуть разом із товщиною.</p><p>Фігура (зокрема із зображенням усередині) може мати <b>М'які краї</b> — так само, як фото (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.10\">Рамка і м'які краї</a>).</p>"},{"id":"6.7","tytul":"Вибір кольору","html":"<p>Клацання кружечка кольору відкриває вікно кольору: піпетку, <b>Код кольору</b> (наприклад, <code>#2f5bd3</code>), готові й нещодавно використані кольори, а також <b>Використано в проєкті</b> — кольори з усіх сторінок, шаблонів і стилів, найчастіші спочатку (біля додаткового кольору видно його назву, наприклад «PANTONE 186 C», <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.1\">Додаткові кольори</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kolory-uzyte.png\" alt=\"Використано в проєкті у вікні кольору\" loading=\"lazy\"><figcaption>Використано в проєкті у вікні кольору</figcaption></figure><p>Якщо у вас є набір бренду (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.9\">Бренд-кит</a>), над «Використано в проєкті» є розділ <b>Бренд</b> — кольори бренду з назвами (назву й код видно, якщо навести курсор).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-marka-kolor.png\" alt=\"Кольори бренду у вікні кольору\" loading=\"lazy\"><figcaption>Кольори бренду у вікні кольору</figcaption></figure>"}]},
  {"nr":"7","tytul":"Зображення","czesc":"Редактор","ikona":"olowek","wstep":"Фото й графіка: вставлення, кадрування, рамки, фільтри та видалення фону.","sekcje":[{"id":"7.1","tytul":"Вставлення зображення","html":"<p><span class=\"ui\">Зображення</span> запитує, звідки взяти зображення:</p><ul class=\"punkty\"><li><span class=\"ui\">Завантажити з пристрою</span> — вибір файлу PNG, JPEG, WebP, GIF або SVG,</li><li><span class=\"ui\">Вибрати із зображень проєкту</span> — зображення, яке вже є в проєкті, без другої копії.</li></ul><p>У проєкті без зображень одразу відкривається вибір файлу. Зображення також можна вставити, перетягнувши файл на сторінку або вставивши з буфера обміну (<kbd>Ctrl</kbd>+<kbd>V</kbd>) — наприклад, знімок екрана чи зображення, скопійоване з вебсторінки.</p>"},{"id":"7.2","tytul":"Кадрування","html":"<p>Двічі клацніть зображення або виберіть <span class=\"ui\">Кадрувати перетягуванням</span>: ви пересуваєте фото в рамці й змінюєте її краї. <kbd>Enter</kbd> підтверджує, <kbd>Esc</kbd> скасовує. Те саме числами: <b>Обрізання (% оригіналу)</b> — <b>Згори</b>, <b>Знизу</b>, <b>Ліворуч</b>, <b>Праворуч</b>.</p>"},{"id":"7.3","tytul":"Властивості зображення","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Параметр</th><th>Значення</th></tr></thead><tbody><tr><td><span class=\"ui\">Замінити фото</span></td><td>Інше фото в тій самій рамці (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.4\">Заміна фото</a>).</td></tr><tr><td><span class=\"ui\">Зображення проєкту…</span></td><td>Вікно всіх зображень (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.5\">Вікно «Зображення проєкту»</a>).</td></tr><tr><td>Опис під заголовком</td><td>Розміри оригіналу в пікселях і роздільність у цьому розмірі (dpi). Для друку — щонайменше 300 dpi; якщо менше, опис змінює колір.</td></tr><tr><td><b>Рамка</b></td><td>Рамка навколо фото: колір, <b>Товщина</b>, <b>Непрозорість обведення</b>, <b>Тип лінії</b> (суцільна, штрихова, пунктирна, штрих – крапка) і <b>Заокруглення кутів</b> у мм — заокруглення обрізає й саме фото (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.10\">Рамка і м'які краї</a>).</td></tr><tr><td><b>Віддзеркалити горизонтально</b></td><td>Перевертає зображення.</td></tr><tr><td><b>Зображення з даних</b></td><td>Інше зображення на кожній розмноженій сторінці (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.5\">Зображення з даних</a>).</td></tr></tbody></table></div>"},{"id":"7.4","tytul":"Заміна фото","html":"<p><span class=\"ui\">Замінити фото</span> вставляє інший файл у ту саму рамку: розмір, розташування, поворот, обведення й тінь зберігаються, а фото з іншими пропорціями обрізається під рамку.</p>"},{"id":"7.5","tytul":"Вікно «Зображення проєкту»","html":"<p><span class=\"ui\">⋯</span> → <span class=\"ui\">Зображення проєкту…</span> показує всі зображення проєкту: мініатюру, повну назву файлу, розміри, обсяг і місця використання (номери сторінок, шаблони, таблиці даних).</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Кнопка</th><th>Що робить</th></tr></thead><tbody><tr><td><span class=\"ui\">Завантажити зображення…</span></td><td>Додає файли з пристрою, кілька одночасно — також ZIP-архів із зображеннями.</td></tr><tr><td><span class=\"ui\">Копіювати назву</span></td><td>На картці зображення: копіює назву файлу, наприклад, до таблиці даних.</td></tr><tr><td><span class=\"ui\">⋯</span> на картці</td><td>Рідше потрібні дії для цього зображення: <span class=\"ui\">Перейменувати</span>, <span class=\"ui\">Замінити файл…</span>, <span class=\"ui\">Копіювати назву</span>, <span class=\"ui\">Видалити зображення…</span>.</td></tr><tr><td><span class=\"ui\">Перейменувати</span></td><td>Нова назва (також клацанням назви); клітинки таблиць із цією назвою змінюються разом із нею.</td></tr><tr><td><span class=\"ui\">Замінити файл…</span></td><td>Новий файл замість старого — скрізь, де зображення використано.</td></tr><tr><td><span class=\"ui\">Видалити</span></td><td>Видаляє виділені зображення. Використані зображення застосунок не видалить — скаже, де вони є.</td></tr><tr><td><span class=\"ui\">Видалити невикористані</span></td><td>Видаляє зображення, які ніде не використано.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-obrazu.png\" alt=\"Меню ⋯ на картці зображення\" loading=\"lazy\"><figcaption>Меню ⋯ на картці зображення</figcaption></figure><p>Клацання зображення виділяє його; <kbd>Ctrl</kbd> додає наступні, <kbd>Shift</kbd> — увесь діапазон. Той самий файл, завантажений удруге, не створює копії. Інший файл із такою самою назвою — застосунок покаже обидва зображення і запитає: <span class=\"ui\">Замінити</span>, <span class=\"ui\">Залишити обидва</span> чи <span class=\"ui\">Пропустити</span>. Якщо в проєкті є повторені зображення з часів до появи цього вікна, угорі з'являється смуга з кнопкою <span class=\"ui\">Упорядкувати</span> — вона об'єднує копії в один файл. Коли виділено кілька зображень, <span class=\"ui\">Копіювати назви</span> копіює всі назви одразу, наприклад, до стовпця таблиці даних.</p><p class=\"ramka-instrukcji uwaga\"><b>Увага.</b> Видалене зображення не поверне <span class=\"ui\">Скасувати</span>.</p><figure><img src=\"img/instrukcja/obrazy-projektu.png\" alt=\"Зображення проєкту\" loading=\"lazy\"><figcaption>Зображення проєкту</figcaption></figure>"},{"id":"7.6","tytul":"Малюнки SVG","html":"<p>Файл SVG вставляється як зображення: виглядає точно й лишається чітким за будь-якого збільшення, але змінити в ньому кольори чи написи не вийде.</p><p><span class=\"ui\">Розкласти малюнок на елементи</span> (у властивостях зображення) перетворює його на сторінці на <b>групу звичайних фігур і написів</b> у тому самому місці. Фігурам можна змінити колір і точки, а написи виправити, як будь-який текст. Файл SVG не змінюється й лишається у вікні зображень проєкту.</p><p>Нічого при цьому не зникає:</p><ul class=\"punkty\"><li><b>обрізання</b> та <b>градієнти</b> лишаються фігурами,</li><li><b>проста маска</b> (біла фігура) стає обрізанням, а <b>візерунок</b> (наприклад, крапки, клітинка) — повтореними фігурами, обрізаними за своєю формою,</li><li>фрагменти з <b>ефектами, яких редактор не має</b> (розмиття, тінь із фільтра, маска з градієнтом, змішування кольорів, наконечники ліній, текст уздовж контуру) лишаються <b>зображенням</b> у тому самому місці, у роздільності для друку. Після розкладання застосунок скаже, скільки їх; решта малюнка редагується.</li></ul><p><kbd>Ctrl</kbd>+<kbd>Z</kbd> повертає весь малюнок.</p><figure><img src=\"img/instrukcja/rysunek-svg.png\" alt=\"Малюнок SVG до й після розкладання\" loading=\"lazy\"><figcaption>Малюнок SVG до й після розкладання</figcaption></figure>"},{"id":"7.7","tytul":"Зображення у фігурі","html":"<p>Будь-яка фігура може бути рамкою для зображення: прямокутник, еліпс, багатокутник, зірка й замкнена фігура з пера.</p><ol class=\"kroki\"><li>Виділіть фігуру й у розділі <b>Зображення у фігурі</b> виберіть <span class=\"ui\">Вставити зображення у фігуру</span> — або перетягніть файл зображення просто на фігуру.</li><li>Зображення заповнює фігуру й обрізається за її краями.</li><li>Двічі клацніть фігуру, щоб пересунути зображення і збільшити його за кути; <kbd>Enter</kbd> підтверджує, <kbd>Esc</kbd> скасовує. На телефоні скористайтеся полями <b>Масштаб</b> і <b>Зсув</b>.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-obraz-w-ksztalcie.png\" alt=\"Фігура із зображенням і розділ «Зображення у фігурі»\" loading=\"lazy\"><figcaption>Фігура із зображенням і розділ «Зображення у фігурі»</figcaption></figure><figure><img src=\"img/instrukcja/obraz-w-ksztalcie-kadr.png\" alt=\"Кадрування зображення у фігурі: усе зображення напівпрозоре, фігура як контур\" loading=\"lazy\"><figcaption>Кадрування зображення у фігурі: усе зображення напівпрозоре, фігура як контур</figcaption></figure><p>Фігуру змінюєте як завжди — розмір, точки, обведення, тінь, — а зображення слідує за нею. <span class=\"ui\">Вийняти зображення</span> залишає звичайне зображення на місці фігури. На сторінках із даними виберіть <b>Зображення зі стовпця</b>: на кожній сторінці з'явиться інше зображення.</p><p>Фото можна перетворити на фігуру одним клацанням: у розділі <b>Кадрування</b> — <span class=\"ui\">Заокруглені кути</span> або <span class=\"ui\">Коло</span>. Заокруглення потім зміните в розділі <b>Заливка й обведення</b>.</p>"},{"id":"7.8","tytul":"Видалення фону","html":"<p>Виділіть фото (або фігуру із зображенням) і виберіть <span class=\"ui\">Видалити фон…</span>.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Інструмент</th><th>Що робить</th></tr></thead><tbody><tr><td><b>Чарівна паличка</b></td><td>Клацніть фон — зникає колір, подібний до клацнутого. <b>Допуск</b> визначає, наскільки подібний.</td></tr><tr><td><b>Лише суміжні з клацнутим місцем</b></td><td>Не чіпає таких самих кольорів усередині фото.</td></tr><tr><td><b>Видалити</b> / <b>Відновити</b></td><td>Пензлі для виправлення країв, мишею або пальцем.</td></tr><tr><td><b>Згладжування країв</b></td><td>Пом'якшує край.</td></tr></tbody></table></div><p><span class=\"ui\">Зберегти як нове зображення</span> додає новий файл до зображень проєкту й вставляє його замість старого; оригінал лишається.</p><figure><img src=\"img/instrukcja/usun-tlo.png\" alt=\"Вікно «Видалити фон»\" loading=\"lazy\"><figcaption>Вікно «Видалити фон»</figcaption></figure>"},{"id":"7.9","tytul":"Фільтри","html":"<p>У розділі <b>Фільтри</b> фото або зображення у фігурі можна налаштувати <b>яскравість</b>, <b>контраст</b>, <b>насиченість</b> і <b>розмиття</b>, а також увімкнути <b>відтінки сірого</b> або <b>сепію</b>. Файл не змінюється; <span class=\"ui\">Без фільтрів</span> повертає оригінал.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-filtry.png\" alt=\"Фільтри зображення\" loading=\"lazy\"><figcaption>Фільтри зображення</figcaption></figure>"},{"id":"7.10","tytul":"Рамка і м'які краї","html":"<p>Розділ <b>Рамка</b> фото: колір (поле <b>немає</b> вимикає рамку), <b>Товщина</b> в мм, <b>Непрозорість обведення</b>, <b>Тип лінії</b> і <b>Заокруглення кутів</b> у мм. Заокруглення обрізає саме фото, а рамка йде по заокругленню. Товщина й заокруглення лишаються такими самими, коли ви змінюєте розмір фото.</p><p>Розділ <b>М'які краї</b> (фото й фігури): <b>Ширина переходу</b> в мм — на такій відстані від краю фото плавно зникає в прозорість; 0 — це чіткий край. <b>Тип</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Тип</th><th>Вигляд</th></tr></thead><tbody><tr><td><b>рівно вздовж краю</b></td><td>Перехід іде вздовж краю — прямокутника, фігури або прозорих місць зображення PNG.</td></tr><tr><td><b>овальна віньєтка</b></td><td>Посередині видно овал, який м'яко зникає до країв і кутів.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-obramowanie.png\" alt=\"Рамка із заокругленням і овальна віньєтка\" loading=\"lazy\"><figcaption>Рамка із заокругленням і овальна віньєтка</figcaption></figure><p>Рамку, заокруглення і м'які краї переносить також <span class=\"ui\">Копіювати стиль</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.13\">Копіювати стиль (пензель формату)</a>).</p>"},{"id":"7.11","tytul":"Зображення ШІ","html":"<p>ШІ намалює зображення з опису – у кожному проєкті, не лише в коміксі. Малює його Google Gemini вашим ключем; вартість оплачуєте в Google, а Makietka показує її перед кожним генеруванням.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-obraz-ai.png\" alt=\"Вікно «Зображення ШІ»\" loading=\"lazy\"><figcaption>Вікно «Зображення ШІ»</figcaption></figure><ol class=\"kroki\"><li>Виділіть рамку, фігуру або кадр коміксу, який має заповнити зображення. Без виділення зображення потрапить на середину сторінки.</li><li>Клацніть <span class=\"ui\">ШІ ▾</span> на панелі вставлення → <b>Зображення з опису…</b>.</li><li>У полі <b>Що має бути на зображенні</b> опишіть по-своєму: хто, що робить, де, який настрій і стиль, напр. «Руда дівчинка з жовтим рюкзаком махає на бруківці, ранок, кольорова дитяча ілюстрація».</li><li>Виберіть <b>Якість</b>: <b>Ескіз – швидко й найдешевше</b> (для спроб), <b>Детальний – для друку</b> або <b>Найкращий – персонажі й деталі</b>.</li><li><b>Форма зображення</b> (квадрат, вертикальне, горизонтальне, панорама, високе) підібрана до рамки – змінюйте її лише для зображення на сторінку.</li><li>Перевірте <b>Вартість</b> (і скільки ви витратили цього місяця) й клацніть <span class=\"ui\">Згенерувати</span>. За 10–30 секунд зображення буде в рамці та у вікні <b>Зображення проєкту</b>.</li></ol><div class=\"tabela-instrukcji\"><table><thead><tr><th>Якість</th><th>Для чого</th><th>Прибл. вартість одного зображення</th></tr></thead><tbody><tr><td>Ескіз</td><td>спроби, попередній перегляд, зображення для екрана</td><td>0,14 зл</td></tr><tr><td>Детальний</td><td>друк</td><td>0,41 зл</td></tr><tr><td>Найкращий</td><td>друк, персонажі й дрібні деталі</td><td>0,55 зл</td></tr></tbody></table></div><ul class=\"punkty\"><li><b>Написів на зображенні немає</b> – Makietka просить ШІ їх не малювати і щоб зображення заповнювало всю рамку, без білих країв. Текст додаєте в Makietka (текстові рамки, бульбашки), тож його легко виправити й перекласти.</li><li><b>Ще раз:</b> виділіть рамку із зображенням ШІ й знову <span class=\"ui\">ШІ ▾</span> → <b>Зображення з опису…</b>. У вікні є опис, з якого постало теперішнє зображення – виправте в ньому, що хочете, або згенеруйте без змін. Попередні версії лишаються в <b>Зображеннях проєкту</b> – повернетеся до них одним вибором (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.5\">Вікно «Зображення проєкту»</a>).</li><li><b>Виправити поточне зображення:</b> виділіть рамку із зображенням (від ШІ або вашим) і виберіть <span class=\"ui\">ШІ ▾</span> → <b>Виправити зображення в рамці…</b> – або у вікні <b>Зображення з опису…</b> дайте відповідь на питання <b>Що зробити із зображенням у рамці</b>. Виберіть <b>Виправити поточне зображення – опиши лише зміну</b> і напишіть саму зміну, напр. «додай дівчинці червоний капелюх» або «зміни пору на вечір». ШІ отримує поточне зображення і змінює лише те, про що ви просите, – решта лишається. <b>Намалювати заново</b> малює все зображення з опису.</li><li><b>Без ключа Google Gemini</b> пункти малювання й писання в <span class=\"ui\">ШІ ▾</span> неактивні (сірі), а вгорі меню є <b>У вас немає ключа для генерування зображень і текстів – додайте ключ…</b> – відкриває налаштування ШІ, де додасте ключ (нижче).</li><li><b>Скільки витрачено:</b> <span class=\"ui\">Налаштування облікового запису</span> → <b>Штучний інтелект</b> показує витрати цього місяця на цьому пристрої. Там же задасте <b>Місячний ліміт витрат на зображення й тексти ШІ</b> – понад нього Makietka не згенерує ні зображення, ні тексту, доки ви не зміните ліміт.</li><li>Зображення намалює й асистент ШІ на ваше прохання, напр. «встав на сторінку 3 фото заходу сонця над морем» (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Асистент ШІ в Makietka (власний ключ)</a>) – у розмові він напише, що малює і скільки це приблизно коштує.</li></ul><p><b>Як отримати ключ Gemini</b></p><ol class=\"kroki\"><li>Відкрийте Google AI Studio (aistudio.google.com) й увійдіть акаунтом Google.</li><li>Клацніть <b>Get API key</b> → <b>Create API key</b>. Скопіюйте ключ.</li><li>Щоб генерувати зображення, увімкніть у Google AI Studio оплату (<b>Billing</b>) – без неї працюють лише безкоштовні тексти.</li><li>У Makietka: <span class=\"ui\">Налаштування облікового запису</span> → <b>Штучний інтелект</b> → <b>Чат у Makietka</b> → <span class=\"ui\">Додати ключ</span> → <b>Google Gemini</b>, вставте ключ. Першого разу задасте <b>пароль до ключів ШІ</b> – ключ зашифровано (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Асистент ШІ в Makietka (власний ключ)</a>).</li></ol>"}]},
  {"nr":"8","tytul":"Таблиця","czesc":"Редактор","ikona":"olowek","wstep":"Таблиця на сторінці — для прайс-листів, планів, списків. Це не те саме, що таблиця даних для розмноження сторінок (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14\">Таблиці даних</a>).","sekcje":[{"id":"8.1","tytul":"Вставлення таблиці","html":"<p><span class=\"ui\">Таблиця</span> відкриває вікно <b>Вставити таблицю</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Поле</th><th>Значення</th></tr></thead><tbody><tr><td><b>Рядки</b></td><td>Кількість рядків (1–60).</td></tr><tr><td><b>Стовпці</b></td><td>Кількість стовпців (1–12).</td></tr><tr><td><b>Найменша висота рядка (мм)</b></td><td>Рядок не буде нижчим; він росте, коли текст не вміщується.</td></tr><tr><td><b>Перший рядок – заголовок</b></td><td>Перший рядок жирний, із товстішою лінією під ним.</td></tr></tbody></table></div><p>Таблицю ви пересуваєте, збільшуєте й обертаєте цілком, як будь-який елемент. <b>Одне клацання клітинки</b> виділеної таблиці вибирає цю клітинку (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.3\">Рядки, стовпці та їхній розмір</a>), <b>подвійне</b> — починає в ній введення тексту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.2\">Введення тексту в клітинках</a>).</p><figure><img src=\"img/instrukcja/tabela.png\" alt=\"Таблиця\" loading=\"lazy\"><figcaption>Таблиця</figcaption></figure>"},{"id":"8.2","tytul":"Введення тексту в клітинках","html":"<p>Двічі клацніть клітинку, щоб писати в ній. <kbd>Tab</kbd> переходить до наступної клітинки, <kbd>Shift</kbd>+<kbd>Tab</kbd> — до попередньої; <kbd>Tab</kbd> в останній клітинці додає рядок. Клітинка — це звичайний текст: можна виділити жирним фрагмент, змінити шрифт, вставити поле з даних (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Поля в тексті</a>). Рядок росте разом із текстом — також на сторінках, розмножених із даних.</p>"},{"id":"8.3","tytul":"Рядки, стовпці та їхній розмір","html":"<p><b>Уся таблиця</b>: <b>Рядки</b> і <b>Стовпці</b> <span class=\"ui\">−</span> <span class=\"ui\">+</span> (останній рядок і стовпець), <b>Перший рядок – заголовок</b>, <b>Ширина таблиці</b> в мм (стовпці змінюються пропорційно), <b>Висота рядків</b> (найменша — рядок росте сам разом із текстом) і <span class=\"ui\">Вирівняти ширину стовпців</span>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-tabela-cala.png\" alt=\"Уся таблиця\" loading=\"lazy\"><figcaption>Уся таблиця</figcaption></figure><p><b>Стовпець і рядок</b> — клацніть один раз клітинку виділеної таблиці (або пишіть у ній): ширина цього стовпця й висота цього рядка в мм, <span class=\"ui\">Стовпець перед</span>, <span class=\"ui\">Стовпець після</span>, <span class=\"ui\">Рядок вище</span>, <span class=\"ui\">Рядок нижче</span> і видалення.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-tabela-komorka.png\" alt=\"Стовпець і рядок вибраної клітинки\" loading=\"lazy\"><figcaption>Стовпець і рядок вибраної клітинки</figcaption></figure><p><b>Ширина всіх стовпців</b> (згорнутий розділ) — ширина кожного стовпця в мм, одна під одною.</p><p>Межу стовпців можна пересунути й мишею: коли таблицю виділено, над межами стовпців є сині маркери. Сусідній стовпець звужується на стільки ж, а останній маркер змінює ширину всієї таблиці.</p>"},{"id":"8.4","tytul":"Об'єднання клітинок","html":"<p>Під час введення тексту в клітинці: <span class=\"ui\">Об'єднати з клітинкою праворуч</span> і <span class=\"ui\">Об'єднати з клітинкою нижче</span>. Клацнувши кілька разів, ви створите клітинку на кілька стовпців або рядків. <span class=\"ui\">Розділити клітинки</span> повертає окремі клітинки.</p>"},{"id":"8.5","tytul":"Лінії та фон","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Розділ</th><th>Що налаштовуєте</th></tr></thead><tbody><tr><td><b>Лінії таблиці</b></td><td>Колір і товщина ліній (0 — без ліній).</td></tr><tr><td><b>Лінії рядка, стовпця, таблиці</b></td><td>Які лінії — зовнішні, горизонтальні, вертикальні — для цього рядка, цього стовпця або всієї таблиці.</td></tr><tr><td><b>Лінії цієї клітинки</b></td><td>Кожен край клітинки окремо: як у таблиці, інша лінія або без лінії.</td></tr><tr><td><b>Фон рядків</b></td><td>Колір рядка заголовка й кожного другого рядка (смугаста таблиця).</td></tr><tr><td><b>Текст у клітинках</b></td><td>Шрифт, розмір, колір, вирівнювання й відступ від краю клітинки.</td></tr></tbody></table></div>"}]},
  {"nr":"9","tytul":"Шари","czesc":"Редактор","ikona":"olowek","wstep":"Список усіх елементів сторінки — щоб виділяти, приховувати й змінювати їхній порядок.","sekcje":[{"id":"9.1","tytul":"Панель «Шари»","html":"<p>Панель <b>Шари</b> показує всі елементи відкритої сторінки, від того, що лежить згори, до того, що лежить у самому низу. На комп'ютері це вкладка <span class=\"ui\">Шари</span> угорі правої колонки (<kbd>F7</kbd>), із кількістю елементів сторінки; на телефоні її відкриває кнопка <span class=\"ui\">Шари</span> внизу екрана.</p><figure><img src=\"img/instrukcja/warstwy.png\" alt=\"Шари\" loading=\"lazy\"><figcaption>Шари</figcaption></figure>"},{"id":"9.2","tytul":"Рядок шару","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>У рядку</th><th>Що робить</th></tr></thead><tbody><tr><td><b>Назва</b></td><td>Клацання виділяє елемент, подвійне клацання перейменовує його.</td></tr><tr><td><b>Маркер ⋮⋮</b></td><td>Перетягніть рядок, щоб змінити порядок, — мишею або пальцем.</td></tr><tr><td><b>Око</b></td><td>Приховує елемент. Прихований елемент не друкується.</td></tr><tr><td><b>Замок</b></td><td>Блокує розташування й розмір.</td></tr><tr><td><span class=\"ui\">⋯</span></td><td><span class=\"ui\">На передній план</span>, <span class=\"ui\">Вище</span>, <span class=\"ui\">Нижче</span>, <span class=\"ui\">На задній план</span>, <span class=\"ui\">Перейменувати</span>, <span class=\"ui\">Копіювати стиль</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.13\">Копіювати стиль (пензель формату)</a>), <span class=\"ui\">Зберегти в бібліотеці</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.8\">Бібліотека</a>).</td></tr></tbody></table></div><p>Виділення в списку стане в пригоді, коли елемент лежить під іншим і на сторінці в нього важко влучити.</p>"},{"id":"9.3","tytul":"Групи, таблиці й шаблони в списку","html":"<ul class=\"punkty\"><li>Трикутник біля групи або таблиці розгортає її вміст. Клацання елемента групи відкриває групу з цим елементом виділеним (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.5\">Групи</a>); клацання клітинки таблиці починає в ній введення тексту.</li><li>Угорі й унизу списку є елементи шаблонів сторінки (над вмістом і під вмістом). Тут їх не змінити — клацання відкриває шаблон для редагування (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.5\">Власний шаблон і редагування</a>).</li></ul>"}]},
  {"nr":"10","tytul":"Сторінки, розділи й розвороти","czesc":"Редактор","ikona":"olowek","wstep":"Порядок сторінок, розділи з різними форматами, розвороти, обкладинка з корінцем і нумерація.","sekcje":[{"id":"10.1","tytul":"Панель сторінок","html":"<p>Панель ліворуч показує мініатюри всіх сторінок у порядку друку, згруповані в розділи (сірі заголовки). Клік на мініатюрі відкриває сторінку. Сторінка, розмножена з даних, має значок <b>×N</b> — стільки разів вона вийде у друці (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Серії</a>). Мініатюри запам'ятовуються на пристрої: наступного разу, коли ви відкриєте проєкт, вони з'являються одразу, а заново малюються лише сторінки, змінені відтоді.</p><p>На телефоні сторінки стоять у горизонтальній смузі, яку ви гортаєте пальцем.</p><figure class=\"kadr telefon\"><img src=\"img/instrukcja/k-strony-telefon.png\" alt=\"Смуга сторінок на телефоні\" loading=\"lazy\"><figcaption>Смуга сторінок на телефоні</figcaption></figure><figure><img src=\"img/instrukcja/strony.png\" alt=\"Панель сторінок із меню сторінки\" loading=\"lazy\"><figcaption>Панель сторінок із меню сторінки</figcaption></figure>"},{"id":"10.2","tytul":"Додавання й упорядкування сторінок","html":"<ul class=\"punkty\"><li>Плитка <b>+</b> наприкінці сторінок розділу додає порожню сторінку після поточної.</li><li><span class=\"ui\">Розділ</span> унизу панелі створює новий розділ.</li><li><b>Перетягніть мініатюру</b>, щоб змінити порядок; кинута в іншому розділі, вона переходить до нього.</li><li><span class=\"ui\">⋯</span> на мініатюрі: <span class=\"ui\">Перейменувати</span>, <span class=\"ui\">Дублювати</span>, <span class=\"ui\">Перемістити вище</span>, <span class=\"ui\">Перемістити нижче</span>, <span class=\"ui\">Видалити сторінку</span>.</li><li><span class=\"ui\">⋯</span> біля заголовка розділу: <span class=\"ui\">Налаштування розділу</span>, <span class=\"ui\">Додати сторінку до розділу</span>, <span class=\"ui\">Перемістити розділ вище</span>, <span class=\"ui\">Перемістити розділ нижче</span>, <span class=\"ui\">Видалити розділ</span>.</li></ul>"},{"id":"10.3","tytul":"Властивості сторінки","html":"<p>Коли нічого не виділено, панель властивостей показує налаштування відкритої сторінки:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><b>Назва сторінки</b></td><td>Назва у списку сторінок.</td></tr><tr><td><b>Розділ</b></td><td>Перенесення сторінки до іншого розділу.</td></tr><tr><td><b>Тло</b></td><td>Колір тла цієї сторінки.</td></tr><tr><td><b>Шаблони</b></td><td>Шаблони сторінок із розділу або власний вибір для цієї сторінки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.4\">На яких сторінках є шаблон</a>).</td></tr><tr><td><b>Серія</b></td><td>Розмноження сторінки з таблиці даних (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Серії</a>).</td></tr><tr><td><b>Напрямні</b></td><td>Напрямні, задані числом (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.4\">Лінійки й напрямні</a>).</td></tr><tr><td><span class=\"ui\">Вставити скопійовані елементи</span></td><td>Вставляє елементи з буфера обміну в те саме місце.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-seria.png\" alt=\"Налаштування сторінки: серія\" loading=\"lazy\"><figcaption>Налаштування сторінки: серія</figcaption></figure>"},{"id":"10.4","tytul":"Налаштування розділу","html":"<p>Розділ — це частина публікації з власними налаштуваннями, напр. «Обкладинка» і «Блок». Вікно відкриєте кнопкою формату на верхній панелі або через <span class=\"ui\">⋯</span> біля заголовка розділу → <span class=\"ui\">Налаштування розділу</span>.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><b>Назва розділу</b></td><td>Назва у списку сторінок.</td></tr><tr><td><b>Розташування сторінок</b></td><td><b>Окремі</b> або <b>Розвороти</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.5\">Розвороти</a>).</td></tr><tr><td><b>Тип розділу</b></td><td>Чим є розділ у публікації – картка з іконкою й описом: <b>Звичайна</b>, <b>Блок (внутрішня частина книги)</b>, <b>Обкладинка</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.6\">Обкладинка з корінцем</a>), <b>Передній форзац</b> і <b>задній</b>, <b>Суперобкладинка</b>, <b>Вкладка</b>, <b>Підкладка / спинка</b>, <b>Складана листівка</b>, <b>Річний календар</b>, <b>Тристоронній календар</b>, <b>Висічка</b>, <b>Аркуш виробів</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.11\">Спеціальні розділи: суперобкладинка, листівка, календарі, висічки, вироби</a>), <b>Паперова модель / вирізанка</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.12\">Паперові моделі й вирізанки</a>), <b>Комікс</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.13\">Комікс</a>). Тип сам визначає формат, зони, нумерацію й корінець обкладинки — назва розділу на це не впливає. Тип вибираєте через <span class=\"ui\">Розділ</span> і змінюєте тут.</td></tr><tr><td><b>Формат</b></td><td>Розмір сторінки в мм. Зміна тут не зачіпає елементів — щоб масштабувати їх разом із форматом, натисніть <span class=\"ui\">Змінити формат і підігнати елементи…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.9\">Зміна формату з масштабуванням</a>).</td></tr><tr><td><b>Поля й виліт</b></td><td>Вводите їх на схемі сторінки, у мм.</td></tr><tr><td><b>Перша сторінка розділу</b></td><td>У розворотах: <b>Права (як у книжці)</b> або <b>Ліва (одразу повний розворот)</b>. Швидше: на панелі <b>Властивості</b> сторінки (нічого не виділено) перемикач <b>Почати розділ з лівої сторінки</b> – міняє ліві й праві сторінки одним кліком, напр. після додавання однієї сторінки.</td></tr><tr><td><b>Нумерація сторінок</b></td><td><b>Продовження попереднього розділу</b>, <b>Почати з номера…</b> або <b>Без номерів (напр. обкладинка)</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.8\">Нумерація сторінок</a>).</td></tr><tr><td><b>Зошити (стежити за кількістю сторінок)</b></td><td><b>Не стежити</b> або кожні 4, 8, 16, 32 сторінки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.7\">Зошити</a>).</td></tr><tr><td><b>Шаблони на сторінках цього розділу</b></td><td>Типові шаблони сторінок розділу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.4\">На яких сторінках є шаблон</a>).</td></tr><tr><td><b>Основа (на чому друкуєте)</b></td><td><b>Білий папір</b>, <b>Кольоровий папір</b> (із кольором) або <b>Прозора плівка</b>. Колір паперу видно на сторінках, у попередньому перегляді та в 3D-макеті, а плівку – як шахівницю; у PDF основа не друкується (це папір, а не фарба). Білий – не фарба: на кольоровому папері й плівці білі елементи вийдуть кольору основи – задайте їм <b>Біла підкладка</b> (Кольори для друку → Облагородження). «Перевірити перед друком» про це нагадує.</td></tr><tr><td><b>Мітки різу в PDF-файлі</b></td><td>Мітки різу на сторінках цього розділу у файлі для друкарні.</td></tr><tr><td><b>Сітка базових ліній</b></td><td><b>Відступ</b> і <b>Перша лінія</b> (мм від верху) — рядки текстів із «Вирівняти за сіткою» стоять на цих лініях (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.13\">Сітка базових ліній</a>).</td></tr></tbody></table></div><figure><img src=\"img/instrukcja/sekcje.png\" alt=\"Налаштування розділу\" loading=\"lazy\"><figcaption>Налаштування розділу</figcaption></figure>"},{"id":"10.5","tytul":"Розвороти","html":"<p>У розділі з розворотами сторінки утворюють пари: ліва й права, як у розгорнутій книжці.</p><ul class=\"punkty\"><li>Ліву й праву сторінку ви редагуєте <b>разом</b>. Нові елементи потрапляють на поточну сторінку — вибираєте її кліком у її області.</li><li>Поля <b>дзеркальні</b>: внутрішнє біля корінця, зовнішнє біля краю.</li><li>Елемент може лежати <b>через корінець</b>, напр. фото на весь розворот — кожна сторінка надрукує свою частину. Елемент належить сторінці, на якій лежить його центр.</li><li>Товста темна лінія — це корінець. Не ставте текст впритул до нього — після зшивання його може бути не видно; застосунок попереджає про елементи, що заходять у смугу біля корінця.</li><li>Кнопка з двома аркушами біля масштабу перемикає весь розворот і одну сторінку (на телефоні за замовчуванням одна сторінка).</li><li><b>Сторінка сама переходить із правого боку на лівий</b> (і навпаки): коли ви додаєте, видаляєте або переміщуєте сторінку перед нею (або перемикаєте <b>Почати розділ з лівої сторінки</b>), її елементи переходять на дзеркальні місця — номер біля зовнішнього краю лишається біля зовнішнього (з вирівнюванням до нього), фото біля корінця лишається біля корінця, а текстова рамка, вписана в поля, потрапляє в нові поля. Текст і зображення не перевертаються. Елемент, який має лишитися на місці, позначте на панелі (<b>Інші</b> → <b>Стала позиція, коли сторінка змінює бік</b>); елемент через корінець належить парі сторінок і не переноситься. Сторінки, розмножені з даних, теж: примірник, який випадає на другий бік, має віддзеркалене розташування.</li></ul><figure><img src=\"img/instrukcja/rozkladowki.png\" alt=\"Розворот\" loading=\"lazy\"><figcaption>Розворот</figcaption></figure>"},{"id":"10.6","tytul":"Обкладинка з корінцем","html":"<p>Обкладинка — це окремий розділ з однією широкою сторінкою: задня сторона, корінець і передня. Створите її у вікні розділу (<b>Тип розділу</b> → <b>Обкладинка</b>), у меню розділу (<span class=\"ui\">Перетворити на обкладинку з корінцем</span>) або одразу у вікні нового проєкту (поле <b>Обкладинка</b>).</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Що означає</th></tr></thead><tbody><tr><td><b>Палітурка</b></td><td><b>М’яка клеєна (з корінцем)</b>, <b>Скріпкова – зшита скобами (без корінця)</b> або <b>Тверда (картон із загином)</b> — для твердої задаєте <b>Загин</b>, <b>Біг</b>, <b>Припуск картону</b>, <b>Товщина картону</b> (мм) і <b>Корінець</b>: <b>Заокруглений</b> (шитий блок з опуклим корінцем – 3D-макет показує дугу) або <b>Прямий</b> (плаский).</td></tr><tr><td><b>Папір блоку</b></td><td><b>Щільність</b> — <b>Щільність (г/м²)</b> і <b>Тип паперу</b> (офсетний, крейдований матовий, крейдований глянцевий, об'ємний) — або <b>Товщина аркуша</b> в мм від друкарні.</td></tr><tr><td><b>Сторінки блоку</b></td><td><b>Обчислити автоматично</b> — з усіх сторінок блоку, разом із повтореннями серій — або <b>Ввести</b> кількість. <b>Блок – це розділи</b> вибирає, які розділи враховуються, коли їх кілька.</td></tr></tbody></table></div><p>Схема у вікні показує задню сторону, корінець і передню, а під нею результат, напр. «Корінець 6,6 мм · Обкладинка 352,6 × 246 мм». Ширина й висота обкладинки обчислюються автоматично.</p><p><b>Розміри</b> — коли друкарня дає корінець або весь розмір обкладинки:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Вибір</th><th>Що відбувається</th></tr></thead><tbody><tr><td><b>Обчислити автоматично</b></td><td>Корінець – з паперу й кількості сторінок, розмір – з формату блоку.</td></tr><tr><td><b>Ввести корінець</b></td><td><b>Корінець (мм)</b> від друкарні замість обчисленого. Решта обчислюється як звичайно.</td></tr><tr><td><b>Ввести розмір</b></td><td><b>Ширина обкладинки</b> і <b>Висота обкладинки</b> (мм, без вильоту) — задня й передня сторони ділять решту ширини порівну навколо корінця. Корінець теж можна ввести; порожнє поле — корінець обчислюється.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-okladka-wymiary.png\" alt=\"Розміри обкладинки, введені вручну\" loading=\"lazy\"><figcaption>Розміри обкладинки, введені вручну</figcaption></figure><figure class=\"kadr\"><img src=\"img/instrukcja/k-okladka-okno.png\" alt=\"Вікно розділу: обкладинка з корінцем, схема й результат\" loading=\"lazy\"><figcaption>Вікно розділу: обкладинка з корінцем, схема й результат</figcaption></figure><p>На полотні пунктирні лінії показують згини (корінець, біги, загини), а сині рамки — безпечні зони задньої сторони, корінця й передньої.</p><figure><img src=\"img/instrukcja/okladka.png\" alt=\"Обкладинка на полотні: задня сторона, корінець, передня\" loading=\"lazy\"><figcaption>Обкладинка на полотні: задня сторона, корінець, передня</figcaption></figure><p>Коли в блоці побільшає сторінок або ви зміните папір, обкладинка перераховується сама: задня сторона лишається, передня зсувається разом із корінцем, написи на корінці лишаються по його центру, а тло на всю обкладинку розтягується. На панелі елемента, у частині <b>Інші</b>, список <b>На обкладинці тримається</b> (автоматично, задньої сторони, корінця або передньої) показує, чого тримається елемент; перемикач <b>Припасувати ширину до корінця</b> розтягує смужку на корінці на всю його ширину. Попередження «Ширший за корінець» означає, що елемент заходить на задню або передню сторону.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-okladka-przypiecie.png\" alt=\"Елемент, прикріплений до частини обкладинки\" loading=\"lazy\"><figcaption>Елемент, прикріплений до частини обкладинки</figcaption></figure><p class=\"ramka-instrukcji uwaga\"><b>Увага.</b> шаблони сторінок, призначені розділу обкладинки, самі не зсуваються.</p><p><b>Матеріал обкладинки й кути.</b> У тому самому вікні:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Поле</th><th>Що вибираєте</th></tr></thead><tbody><tr><td><b>Матеріал обкладинки</b></td><td><b>Друкована обкладинка</b> (картон із друком) або обклеювальний матеріал без друку: <b>Палітурне полотно</b>, <b>Екошкіра</b>, <b>Структурний папір</b>, <b>Оксамит (велюр)</b>.</td></tr><tr><td><b>Плівка</b></td><td>Для друкованої обкладинки: <b>матова</b>, <b>глянцева</b>, <b>soft-touch</b> або <b>без плівки</b>.</td></tr><tr><td><b>Колір обклеювального матеріалу</b></td><td>Типові кольори цього матеріалу (напр. полотно темно-синє, бордове, пляшково-зелене) або <b>Інший колір…</b>.</td></tr><tr><td><b>Кути</b></td><td><b>прямі</b> або <b>заокруглені</b> 3, 5, 6 чи 10 мм — на полотні червоні дуги в кутах показують, що буде відрізано.</td></tr></tbody></table></div><p>На обклеювальному матеріалі графіка обкладинки не друкується — лишаються елементи з тисненням фольгою або конгревом (Кольори для друку → Облагородження). 3D-макет показує матеріал у вибраному кольорі, з фактурою тканини, шкіри або паперу, а на ньому — тиснення фольгою й конгрев. <b>Перевірити перед друком</b> нагадує про обклеювальний матеріал і кути.</p><p><b>Специфікація для друкарні</b> (меню <b>⋯</b>) завантажує два файли: текст для замовлення або листа і JSON. У них є формати й кількості сторінок розділів, палітурка й корінець, папір блоку, матеріал, плівка й кути обкладинки, стрічка-закладка, зошити, основа, режим кольорів, додаткові кольори й облагородження.</p>"},{"id":"10.7","tytul":"Зошити","html":"<p>Блок, зшитий або склеєний із зошитів, мусить мати кількість сторінок, кратну розміру зошита. У налаштуваннях розділу виберіть <b>Зошити</b>: кожні 4, 8, 16 або 32 сторінки.</p><p>У списку сторінок під назвою розділу побачите, напр., «46 з 48 – бракує 2 до повного зошита (×16)». <span class=\"ui\">Доповнити порожніми</span> додає відсутні порожні сторінки в кінці розділу — скасуєте це, як будь-яку зміну. <b>Перевірити перед друком</b> теж нагадає про неповний зошит, а для скріпкової палітурки — про кількість сторінок, не кратну 4.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-skladki.png\" alt=\"Лічильник зошита й «Доповнити порожніми»\" loading=\"lazy\"><figcaption>Лічильник зошита й «Доповнити порожніми»</figcaption></figure>"},{"id":"10.8","tytul":"Нумерація сторінок","html":"<p>Номер сторінки вставите полем <code>{номер}</code> — найкраще в шаблоні сторінки, щоб він був на кожній сторінці (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.7\">Поля в шаблоні</a>). Нумерація залежить від налаштувань розділу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>) і рахує сторінки після розмноження серій. Нумеруються лише розділи блоку (тип <b>Звичайна</b>, <b>Блок</b>, <b>Річний календар</b>): обкладинка, форзаци, суперобкладинка, вкладка, підкладка й окремі друки не мають номерів і не зсувають нумерації — перша сторінка блоку має номер 1 навіть тоді, коли перед нею стоять обкладинка й форзац. Інші записи номера (римські, з нулями) є в таблиці полів (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15.2\">Поля документа</a>).</p>"},{"id":"10.9","tytul":"Зміна формату з масштабуванням","html":"<p>Календар з A4 на A3, книжка з B5 на A5 — формат зміните разом з елементами:</p><ul class=\"punkty\"><li>один розділ: вікно розділу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>) → <span class=\"ui\">Змінити формат і підігнати елементи…</span>,</li><li>увесь проєкт: <span class=\"ui\">⋯</span> → <span class=\"ui\">Змінити формат проєкту…</span>.</li></ul><ol class=\"kroki\"><li>Виберіть <b>Новий формат</b> зі списку або введіть <b>Ширина (мм)</b> і <b>Висота (мм)</b>; <span class=\"ui\">Змінити орієнтацію</span> повертає аркуш.</li><li>Виберіть, <b>Що з елементами</b>:</li></ol><div class=\"tabela-instrukcji\"><table><thead><tr><th>Спосіб</th><th>Що відбувається</th></tr></thead><tbody><tr><td><b>Масштабувати все</b></td><td>Елементи, шрифт, лінії, поля, напрямні й шаблони сторінок змінюються пропорційно. <b>Масштаб</b>: <b>Умістити всю сторінку (по центру)</b>, <b>Припасувати за шириною</b> або <b>Припасувати за висотою</b>.</td></tr><tr><td><b>Залишити розміри, змістити відносно країв</b></td><td>Розміри лишаються; елемент тримається найближчого краю або центру. Тло й смуги на всю ширину чи висоту розтягуються на нову сторінку.</td></tr><tr><td><b>Лише змінити формат</b></td><td>Елементи лишаються там, де є.</td></tr></tbody></table></div><ol class=\"kroki\"><li>Попередній перегляд <b>Зараз → Після зміни</b> показує першу сторінку до й після. Під ним є зауваги, напр. скільки елементів вийде за сторінку.</li><li><span class=\"ui\">Змінити формат</span>. Усю зміну скасуєте одним <span class=\"ui\">Скасувати</span> (<kbd>Ctrl</kbd>+<kbd>Z</kbd>).</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-format.png\" alt=\"Зміна формату з переглядом до й після\" loading=\"lazy\"><figcaption>Зміна формату з переглядом до й після</figcaption></figure><p>Обкладинка з корінцем (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.6\">Обкладинка з корінцем</a>) перераховується сама після зміни формату блоку. Елементи, які після зміни виходять за сторінку, покаже <b>Перевірити перед друком</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>).</p>"},{"id":"10.10","tytul":"Готові розділи (шаблони документів)","html":"<p>Цілий готовий документ вставите одним кліком як новий розділ: настінний календар, планер на 365 днів, блокнот, запрошення, дипломи для списку людей, візитівки, листівку, меню, розділ книжки й понад 30 інших. Де: унизу панелі сторінок кнопка <span class=\"ui\">Готовий</span> (поруч із <span class=\"ui\">Розділ</span>) і в Бібліотеці категорія <b>Готові розділи</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.8\">Бібліотека</a>). Шаблони цілих проєктів (книжка з обкладинкою й форзацами, брошура…) окремо — під час створення нового проєкту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.2\">Новий проєкт</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-gotowe-sekcje.png\" alt=\"Готові розділи – галерея шаблонів\" loading=\"lazy\"><figcaption>Готові розділи – галерея шаблонів</figcaption></figure><ol class=\"kroki\"><li>Виберіть вид угорі (<b>Книжка</b>, <b>Календарі</b>, <b>Планери й блокноти</b>, <b>Запрошення й дипломи</b>, <b>Фірма й реклама</b>, <b>Інші</b>) або введіть слово в <b>Пошук</b>. Мініатюра показує першу сторінку у форматі вашого проєкту, а під нею видно, скільки сторінок буде створено. Позначка <b>з даними</b> – сторінки беруть вміст із таблиці (напр. 365 днів, люди для дипломів).</li><li>Клацніть шаблон. Побачите попередній перегляд перших сторінок і налаштування: - запитання шаблону, напр. <b>Рік</b> календаря або <b>Кількість сторінок</b> блокнота, - <b>Кольори</b>: кольори бренду (коли у вас є набір бренду, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.9\">Бренд-кит</a>), кольори шаблону або одна з готових палітр, - шаблони з власним форматом (візитівка 85 × 55 мм, диплом A4 горизонтально, етикетка 70 × 40 мм) мають перемикач формату – зніміть позначку, щоб шаблон припасувався до формату розділу.</li><li><span class=\"ui\">Вставити як новий розділ</span>. Розділ стає після поточного, а редактор переходить на його першу сторінку.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-gotowe-szczegoly.png\" alt=\"Подробиці шаблону – перегляд, рік і кольори\" loading=\"lazy\"><figcaption>Подробиці шаблону – перегляд, рік і кольори</figcaption></figure><p>Шаблон — не заморожений файл: він будується для вашого формату, полів і вильоту, у кольорах і шрифтах бренду. Після вставлення це звичайні сторінки, шаблони сторінок (напр. номер сторінки), стилі й таблиця даних із серією (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14\">Таблиці даних</a>, <a href=\"#\" data-cel=\"16\">Серії</a>) – змінюєте в них усе, як у власних. Сірі поля – це місця для фото: вставте в них зображення (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.7\">Зображення у фігурі</a>). Увесь вставлений розділ прибирає одне <span class=\"ui\">Скасувати</span> (<kbd>Ctrl</kbd>+<kbd>Z</kbd>).</p>"},{"id":"10.11","tytul":"Спеціальні розділи: суперобкладинка, листівка, календарі, висічки, вироби","html":"<p>Спеціальний розділ працює як обкладинка з корінцем (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.6\">Обкладинка з корінцем</a>): він знає, чим є надрукована річ. Сам обчислює свій формат, підписує на сторінці зони (панелі, клапани), малює лінії згинів (біги, пунктир), перфорації (крапки) і різу (суцільна рожева лінія), попереджає про текст на згині та про елементи за лінією різу, а в PDF-файлі дає аркуш у повному розмірі. Вибираєте його як <b>Тип розділу</b> через <span class=\"ui\">Розділ</span> або в налаштуваннях розділу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>). Схема у вікні показує зони й згини наживо, під нею — розміри аркуша.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-sekcja-ulotka.png\" alt=\"Складана листівка в налаштуваннях розділу\" loading=\"lazy\"><figcaption>Складана листівка в налаштуваннях розділу</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Тип</th><th>Що обчислює</th></tr></thead><tbody><tr><td><b>Передній / задній форзац</b></td><td>Тверда палітурка: аркуш завширшки у дві сторінки блоку, зі згином посередині. Половина <b>На обкладинці (приклеєна)</b> приклеюється до внутрішньої сторони обкладинки, друга – це перший (передній) або останній (задній) вільний аркуш книжки. <b>Друк</b>: чистий, надрукована видима сторона або обидві сторони; <b>Папір</b> (г/м²) — вільний аркуш додається до товщини корінця. Форзац не має номерів сторінок.</td></tr><tr><td><b>Суперобкладинка з клапанами</b></td><td>Задня сторона, корінець і передня з твердої обкладинки проєкту (кришки й корінець), два клапани (<b>Клапан обкладинки</b>, 0 – приблизно половина передньої сторони) і запас на згин біля кришки. Побільшає сторінок – суперобкладинка перерахується сама, а елементи передньої сторони зсунуться разом із нею.</td></tr><tr><td><b>Складана листівка</b></td><td>Аркуш на 2, 3 або 4 панелі, <b>Фальцювання</b>: <b>Рулонне</b> (C-фальц – панель, що загинається всередину, вужча на <b>Вкорочення</b>, щоб не мнулася) або <b>Гармошка</b> (Z – панелі рівні). Розділ має дві сторінки: зовнішню (з панеллю <b>Обкладинка</b>) і внутрішню.</td></tr><tr><td><b>Календар із датами (рік)</b></td><td><b>Рік</b>, <b>Сторінка на</b> місяць, тиждень або день, початок тижня і <b>Свята</b> (Польща: сталі й рухомі – Великдень, Трійця, Боже Тіло). Створює таблицю даних і серію: перша сторінка розділу розмножується для кожного місяця, тижня або дня. Зміна року перераховує все.</td></tr><tr><td><b>Тристоронній календар</b></td><td>Шапка, три календарні сітки одна під одною, віконце на середній і рекламна смуга – з бігом під шапкою й перфораціями.</td></tr><tr><td><b>Висічка</b></td><td><b>Конверт</b> (C6, DL, C5, квадрат), <b>Папка</b> з кишенею й прорізами для візитки або <b>Коробка</b> (довжина, ширина, висота → розгортка з кришкою, дном, клапанами й клейовим клапаном). <b>Друк з обох боків</b> додає другу сторінку – внутрішній бік аркуша: зони, згини й лінія різу на ній віддзеркалені по горизонталі так, як вони випадуть після перевертання аркуша, тож внутрішній бік коробки чи конверта ви проєктуєте в правильному місці. Лінії висічки йдуть у PDF лише з першої сторінки; 3D-макет показує внутрішній бік.</td></tr><tr><td><b>Аркуш виробів</b></td><td>Наліпки, візитівки, етикетки: ви проєктуєте один виріб (або наступні з даних – серія), а в PDF вони стоять поруч на аркуші (SRA3, A3, A4, B2) з мітками різу. <b>Різання</b>: прямокутник (гільйотина), <b>наліпка</b> із заокругленими кутами, <b>кругла / овальна наліпка</b> (коло або овал у розмірах виробу) або <b>бирка з отвором</b> – зрізані верхні кути (зріз у полі заокруглення) і отвір Ø 5 мм для шнурка; перевірка перед друком попереджає про елементи в отворі й поза висічкою. Готовий шаблон: <b>Бирки для подарунків</b> (для кого, побажання, від кого – з таблиці).</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-sekcja-wykrojnik.png\" alt=\"Висічка коробки на сторінці: зони, згини й лінія різу\" loading=\"lazy\"><figcaption>Висічка коробки на сторінці: зони, згини й лінія різу</figcaption></figure><p><b>Поля календаря з датами</b> для вставлення в текст (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Поля в тексті</a>): <code>{data}</code>, <code>{dzien}</code>, <code>{miesiac}</code>, <code>{dzien_tygodnia}</code>, <code>{tydzien}</code>, <code>{swieto}</code>; стовпець <code>wolne</code> має значення «tak» у неділі й свята – використайте його в кольорі, залежному від даних (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17\">Вигляд із даних</a>), щоб свята були червоними. Власні стовпці, дописані до цієї таблиці, лишаються після зміни року.</p><p><b>У PDF-файлі</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Експорт у PDF і PNG</a>): лінія різу висічки – окремий додатковий колір <b>CutContour</b>, згини – <b>Crease</b>, перфорації – <b>Perforation</b>: друкарня їх не друкує, а лише вирізає, бігує й перфорує. Для суперобкладинки, листівки й тристороннього календаря (ріжуться прямо) згини й перфорації позначені рисками за форматом, поруч із мітками різу. Аркуш виробів компонується сам, коли в експорті вибрано <b>Розташування аркушів: Звичайне</b>. Зауваги про текст на згині й елементи за лінією різу показує також <b>Перевірити перед друком</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>).</p><p>Готові розділи (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.10\">Готові розділи (шаблони документів)</a>) <b>Складана брошура</b>, <b>Візитівки</b> та <b>Етикетки й наліпки</b> вставляються одразу як складана листівка й аркуш виробів, а <b>Обкладинка</b> у твердій палітурці — разом із двома чистими форзацами.</p><p><b>Книжка у твердій палітурці</b> складається з розділів таких типів: <b>Обкладинка</b> (тверда палітурка), <b>Передній форзац</b>, <b>Блок</b>, за потреби <b>Вкладка</b> (напр. фото на крейдованому папері — з власним папером, без номерів сторінок) і <b>Задній форзац</b>. Корінець обкладинки обчислюється з блоку й додає вільні аркуші форзаців та аркуші вкладок, кожен зі своїм папером. <b>Перевірити перед друком</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>) попереджає, коли тверда обкладинка не має форзаців (кнопка <span class=\"ui\">Додати форзаци</span> додає обидва, чисті), і коли форзац стоїть при м'якій палітурці. Тверда обкладинка може також мати <b>Закладка – стрічка в корінці</b> вибраного кольору. В експорті PDF (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Експорт у PDF і PNG</a>) <b>Файли для друкарні: обкладинка, форзаци, блок…</b> дає окремий файл для кожної частини: обкладинки, суперобкладинки, форзаців, блоку, вкладок і кожного окремого друку.</p><p>Розділ зі старішого проєкту, який має в назві «wyklejka» (форзац), а тип звичайний, один раз отримує підказку «Розділ … схожий на форзац – задати тип…?» з кнопкою <span class=\"ui\">Задати тип</span>. Це лише пропозиція — без кліку розділ лишається звичайним.</p>"},{"id":"10.12","tytul":"Паперові моделі й вирізанки","html":"<p>Модель із паперу або картону з багатьох деталей – будиночок, коробку з перегородками, геометричне тіло, іграшку – робите в розділі типу <b>Паперова модель / вирізанка</b>. Кожна сторінка цього розділу – це один <b>аркуш</b> із деталями. У налаштуваннях розділу:</p><ul class=\"punkty\"><li><b>Аркуш</b> – A4, A3, A5, Letter (домашній принтер) або <b>Власний</b> (аркуш друкарні, плотер), вертикально або горизонтально;</li><li><b>Матеріал</b> – папір або картон зі <b>щільністю</b> (товщина обчислюється сама: картон 300 г/м² ≈ 0,39 мм), палітурний картон або власна товщина в міліметрах; від товщини залежить ширина прорізів;</li><li><b>Друк і різання</b> – <b>домашній принтер</b> (лінії різу й згинів друкуються – ріжете ножицями й ножем) або <b>друкарня з плотером</b> (лінії йдуть у PDF окремими кольорами: різ, згини й клей – друкарня їх не друкує); <b>поле принтера</b> – смуга біля краю, яку принтер не задрукує;</li><li><b>Зворот аркуша</b> – не використовується, теж друкується або <b>лише місця склеювання</b> (без друку).</li></ul><p>Поля розділу дорівнюють полю принтера, а вильоту немає – модель вирізається по контуру деталей.</p><p>У цьому розділі панель вставлення має додаткові інструменти:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Інструмент</th><th>Що робить</th></tr></thead><tbody><tr><td><span class=\"ui\">Шаблон</span></td><td>Готова модель за розмірами: <b>Коробка з накладною кришкою</b> (дві деталі – кришка більша на дві товщини матеріалу й 0,5 мм зазору, тож насувається щільно, але без зусилля), <b>Коробка із вставним клапаном</b> (кришка на завісі з язиком, що вставляється за передню стінку – відкривається й закривається без клею), <b>Коробка з замком</b> (язик кришки входить у проріз у передній стінці завширшки в товщину матеріалу + 0,2 мм), <b>Обертове коло</b> для книжок (два диски на заклепці – верхній із віконцем на одне з 3–12 полів нижнього; віконце й хрестик під заклепку – лінії різу), <b>Повзунок</b> для книжок (аркуш із надрізом біля краю і смужка у формі літери T – вузька частина проходить крізь надріз, широкий кінець лишається під аркушем і не дає витягнути смужку; параметри: ширина смужки й хід), <b>Коробка-подушка</b> (дві стінки з дугами на кінцях: опукла дуга різу й увігнутий <b>згин по дузі</b> – після втискання кінців усередину коробка закривається сама; згин по дузі друкується як біг по кривій, а 3D-макет показує його пласким, бо картон гнеться по кривій пружно), <b>Клапанці</b> для книжок (lift-the-flap: 1–6 віконець, вирізаних з трьох боків і зігнутих на четвертому – згин працює як завіса; другий аркуш під сподом для прихованих малюнків, клей лише поза віконцями), <b>Лоток</b>, <b>Прямокутний паралелепіпед</b>, <b>Призма</b> (3–12 граней), <b>Піраміда</b>, <b>Хрестоподібні вставні перегородки</b> (коротші на дві товщини, нижчі на одну, із прорізами товщина + 0,2 мм), тіла з кривими стінками – <b>Циліндр</b>, <b>Конус</b>, <b>Зрізаний конус</b> (чашка, абажур) і <b>Куля з клинів</b> (глобус, 4–24 клини – кожен приклеюється клапанами до наступного), <b>Ваза</b> (тіло обертання з профілю, 6–32 сегменти – смуги стінок і пласке дно), готові моделі <b>Будиночок із двосхилим дахом</b>, <b>Автомобіль</b> і <b>Черепаха</b> (панцир із сегментів, голова, лапи й хвіст – приклеюються під панцир) (тіла із силуету, розгорнуті автоматично, як у <span class=\"ui\">3D-модель</span>): бічна поверхня розгорнута точно (кут сектора обчислюється з висоти й діаметрів), дно й кришка з багатьох коротких сторін, клапани вздовж дуги з одним номером (шов – перевірка стежить, щоб обидві сторони мали однакову довжину) – <b>Pop-up листівка з V-згином</b> (трикутник, приклеєний до двох скісних полів під тим самим кутом до корінця, що і його краї – на розгорнутій листівці лежить пласко, під час закривання встає й ховається всередині; кут 15–75°), <b>Pop-up листівка з платформою</b> (листівка й смужка, приклеєна клапанами до полів з обох боків корінця: після відкриття стоїть як коробка, після закриття лежить пласко всередині; <b>Шари: 2</b> доклеює на ній другу, меншу платформу) та <b>Pop-up листівка (вирізанка)</b>: один аркуш із надрізами й згинами, з якого після відкриття листівки під прямим кутом вискакують коробочки (1–4, глибина й висота на вибір; надрізи закінчуються перед краєм, тож після закриття нічого не стирчить); <b>3D-макет</b> показує її відкритою під прямим кутом із коробочками, що вискочили). Деталі мають згини, клапани й номери пар; вікно показує товщину матеріалу розділу.</td></tr><tr><td><span class=\"ui\">Деталь</span></td><td>Нова деталь – прямокутник 60 × 40 мм із літерою (A, B, C…).</td></tr><tr><td><span class=\"ui\">З фігури</span></td><td>Виділений прямокутник, багатокутник, еліпс або фігуру з пера (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6\">Фігури, лінії та кольори</a>) перетворює на деталь – будь-який контур. Дуги з пера лишаються дугами (густо, приблизно кожні 2 мм), тож круглі форми ріжуться гладко.</td></tr><tr><td><span class=\"ui\">Тіло з фігури</span></td><td>Виділена фігура – це основа тіла: <b>призма</b> (стінки перпендикулярні, вибраної висоти, кришка біля першої стінки) або <b>піраміда</b> (стінки до вершини над центром основи), або <b>стінки з дахом</b> – два з'єднані тіла: стінки з дном і окремий дах (піраміда без основи, розгорнута віялом навколо вершини, з <b>Висотою даху</b>); клапани вгорі стінок мають ті самі номери пар, що й нижні краї даху, тож дах наклеюється на стінки, як на будиночку. Виходить одна деталь із розгорткою – стінка на кожній стороні, клапани з номерами пар і згини. Працює з будь-яким багатокутником, також увігнутим (зірка, літера L) – для увігнутого перевірте, чи стінки на розгортці не накладаються одна на одну.</td></tr><tr><td><span class=\"ui\">3D-модель</span></td><td>Тіло з 3D-програми або з мережі (<b>OBJ</b> чи <b>STL</b>), розгорнуте на площину – як у програмах для паперових моделей: Makietka ділить грані на трикутники, розгортає їх уздовж найпласкіших ребер (пласкі грані лишаються цілими, без ліній), ставить згини «гора» й «долина» з кутом і клапани з номерами пар. Коли деталь накладалася б сама на себе, наступні грані переходять до наступної деталі. Ви задаєте найбільший розмір моделі в мм; потім <span class=\"ui\">Розкласти</span> розміщує деталі на аркушах. Найкраще – моделі до кількох сотень граней (у Blender: Decimate). До OBJ можна додати файл <b>MTL</b> (виберіть обидва разом) – кожна деталь отримує колір матеріалу, який займає в ній найбільше місця; без MTL матеріали отримують кольори з палітри. Коли модель має <b>текстуру</b> (UV-координати в OBJ і зображення <code>map_Kd</code> у MTL), виберіть разом із ними файл зображення (PNG, JPG або WebP) – кожна деталь отримує друк: зображення, перенесене на її грані точно так, як воно лежить на моделі. Друк потрапляє до <b>Зображень проєкту</b> («… – nadruk.png») і зсувається разом із деталлю під час <span class=\"ui\">Розкласти</span>; після <span class=\"ui\">Розрізати</span> і <span class=\"ui\">Об'єднати</span> зникає (він охоплював усю деталь). Коли зображення бракує, Makietka повідомляє, який файл шукає.</td></tr><tr><td><span class=\"ui\">Згин</span></td><td>Два кліки на краях деталі: лінія згину ділить її на грані. Лінія по самому краю або поза деталлю не додається.</td></tr><tr><td><span class=\"ui\">З'єднати</span></td><td>Клацніть біля краю, який отримає <b>клейовий клапан</b>, потім біля краю іншої деталі (або тієї самої), до якого він приклеюється – обидва отримують <b>однаковий номер</b>. Другий клік посередині грані замість біля краю додає там <b>місце склеювання</b> завдовжки з край. Коли краї мають різну довжину, застосунок про це скаже.</td></tr><tr><td><span class=\"ui\">Клей</span></td><td>Клік у деталі додає місце склеювання (з <kbd>Shift</kbd> – на звороті, без друку, коли зворот аркуша призначено під клей).</td></tr><tr><td><span class=\"ui\">Лінія склеювання</span></td><td>Склеювання не завжди біля краю: допоміжна лінія <b>в будь-якому місці грані</b> – вона не мусить доходити до краю чи бути замкненою. Без виділення: два кліки в деталі (початок і кінець). Криву, хвилю або ламану намалюйте на деталі лінією, дугою чи пером, виділіть і скористайтеся <span class=\"ui\">Лінія склеювання</span> – вона стане лінією склеювання (замкнена фігура, напр. коло, теж). Потім <span class=\"ui\">З'єднати</span>: край або клапан іншої деталі, а потім лінія – вони отримують однаковий номер. <b>Пряма</b> лінія: доклеєна деталь стане під кутом (зігнеться на лінії); <b>крива</b>: вигнеться й обгорнеться вздовж неї. Лінія друкується зеленою рискою з номером, а у файлі для друкарні йде на форму клею; на панелі деталі (<b>Лінії склеювання</b>) побачите довжину, зміните номер або перенесете її на зворот. <b>Перевірити перед друком</b> порівняє довжину краю й лінії, а інструкція зі складання скаже, чи приклеювана деталь стане під кутом, чи обгорнеться по кривій.</td></tr><tr><td><span class=\"ui\">Надріз</span></td><td>Лінія різу всередині деталі або від її краю, <b>під будь-яким кутом</b> – два кліки (кінці притягуються до вершин, кінців згинів та інших надрізів, до 1,5 мм). Криві й ламані: намалюйте на деталі лінію, дугу або фігуру пером, виділіть і скористайтеся <span class=\"ui\">Надріз</span> – виходить один надріз із багатьох відрізків. Надрізи разом зі згинами ділять грань: напр. два скісні надрізи від кінців згину дають трикутний клапанець, який у 3D-макеті відхиляється на своєму згині (pop-up вирізанка). Надріз друкується на формі різу разом із контуром; на панелі деталі (<b>Надрізи</b>) видно довжину, і їх можна видалити. <b>Перевірити перед друком</b> попереджає, коли надріз виходить за деталь. Проріз (<span class=\"ui\">Проріз</span>) – це інше: вузький отвір завширшки під язичок.</td></tr><tr><td><span class=\"ui\">Виріз</span></td><td>Отвір у деталі: намалюйте на ній замкнену фігуру (прямокутник, еліпс, багатокутник, фігуру з пера), виділіть її й скористайтеся <span class=\"ui\">Виріз</span>. Шматок усередині випадає – у редакторі він має сіре штрихування (це відходи), у 3D-макеті в грані дірка. <b>Віконце з дверцятами</b>: замість вирізу зробіть <span class=\"ui\">Надріз</span> на трьох сторонах, а четверту сторону зігніть (<span class=\"ui\">Згин</span> або надрізи від кінців згину) – дверцята відхиляються на завісі й відкривають отвір.</td></tr><tr><td><span class=\"ui\">На деталь</span></td><td>Грань – це не лише колір: виділіть текст, зображення, фігуру або оздобу, що лежить на деталі, і скористайтеся <span class=\"ui\">На деталь</span> – елемент переходить на грань і відтоді є частиною деталі: зсувається й обертається разом із нею, лишається на своєму місці, коли ви змінюєте згини й клапани, їде з нею під час <span class=\"ui\">Розкласти</span> (елементи, що лежать цілком на деталі, <span class=\"ui\">Розкласти</span> розміщує на ній сам), під час <span class=\"ui\">Розрізати</span> потрапляє до шматка, на якому лежить, а в 3D-макеті є на своїй грані й згинається разом із нею. Графіка грані <b>обрізана по контуру деталі</b> – те, що виступає, не друкується за лінією різу ані на клапанах. Панель деталі → <b>На гранях</b> показує, скільки елементів є на гранях; <b>Вийняти з деталі (для редагування)</b> повертає їх на сторінку в те саме місце – напр. щоб виправити текст – потім знову <span class=\"ui\">На деталь</span>.</td></tr><tr><td><span class=\"ui\">Розкласти</span></td><td>Усі деталі розділу розміщуються наново на аркушах – рядами в полі друку (без поля принтера), спершу найвищі; деталь, що не вміщається горизонтально, повертається на 90°; відсутні аркуші додаються в кінці розділу (при двосторонньому друці деталі йдуть на першу сторінку аркуша). Інші елементи сторінок лишаються. Деталь, завелика навіть після повороту, лишається на місці – застосунок про це скаже.</td></tr><tr><td><span class=\"ui\">Інструкція</span></td><td>Інструкція зі складання з моделі: що надрукувати (матеріал, щільність), які деталі вирізати (з номерами аркушів), скільки згинів «від себе» і «до себе» має кожна деталь, потім склеювання пар по черзі – «Намажте клеєм клапан 3 (деталь A) і приклейте під край 4 деталі B з номером 3», «Вставте язичок 7 у проріз 7». <span class=\"ui\">Завантажити (.txt)</span> або <span class=\"ui\">Вставити як сторінку</span> – новий розділ A4 після аркушів із пронумерованими кроками (можна виправляти як звичайний текст).</td></tr><tr><td><span class=\"ui\">Проріз</span></td><td>Два кліки в деталі: проріз під язичок або перегородку – ширина дорівнює товщині матеріалу + 0,2 мм зазору.</td></tr><tr><td>Розрізати (на панелі деталі)</td><td>Два кліки на краях ділять деталь на дві – напр. коли після <span class=\"ui\">3D-модель</span> деталь не вміщається на аркуші. Краї зберігають клапани й номери, згини потрапляють до своєї деталі (ті, що перетинають лінію, обрізаються до неї), а на лінії різу утворюється нова пара: клапан на одній деталі, край для склеювання на другій.</td></tr><tr><td>Об'єднати (на панелі деталі)</td><td>Клік біля краю з номером пари з'єднує обидві деталі в одну: друга обертається й зсувається так, щоб краї пари збіглися, а край склеювання стає згином (гора, 90°). Коли деталі накладалися б одна на одну, Makietka відмовляє – вони лишаються окремими.</td></tr></tbody></table></div><p><kbd>Esc</kbd> завершує інструмент. Деталь переміщуєте й обертаєте, як будь-який елемент; розтягнути її не можна (розміри – це розміри моделі). Виділена деталь має на панелі <b>Властивості</b>:</p><ul class=\"punkty\"><li><b>Деталь</b> – назву (літеру), колір граней, перемикач <b>Номери пар і назва деталі</b> та кнопки інструментів;</li><li><b>Краї</b> – кожен край із довжиною й типом: <b>Різання</b>, <b>Клейовий клапан</b> (із шириною), <b>Для склеювання (без клапана)</b> або <b>Язичок у проріз</b> (із довжиною) – і <b>номером пари</b>;</li><li><b>Згини</b> – <b>гора</b> (від себе, штрих-пунктир – друк лишається зовні; такі згини в шаблонах і нові згини) або <b>долина</b> (до себе, штрихи) і <b>кут після згину</b> – кут між гранями в готовій моделі (коробка 90°, стінки шестикутної призми 120°), а в pop-up листівці перемикач <b>Корінець листівки (pop-up)</b>;</li><li><b>Місця склеювання</b> і <b>Прорізи</b> – номер пари, розміри, на звороті, видалення.</li></ul><p>На аркуші клапани світло-сірі з номером пари, а той самий номер стоїть біля краю або в місці, до якого вони приклеюються – після вирізання ви знаєте, що з чим склеїти. Файл для плотера (меню <b>⋯</b>) і PDF для друкарні отримують контур різу деталей із клапанами й прорізами, згини (також біля основи кожного клапана) і місця склеювання.</p><p><b>Що з чим з'єднується.</b> Коли нічого не виділено, панель сторінки в розділі паперової моделі має список <b>З'єднання</b>: кожен номер із тим, що його несе, напр. «1 – A: клапан 2 ↔ B: край 4», а за кількох аркушів також номер аркуша. Наведення на пункт підсвічує помаранчевим обидві сторони пари на аркуші, клік виділяє деталь. Номер без пари або використаний понад двічі має смужку попередження. Наведення миші на деталь підсвічує всі її пари.</p><p><b>Перевірити перед друком</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>) стежить за моделлю: деталь, що виходить за аркуш або заходить у поле принтера, деталі, що накладаються одна на одну разом із клапанами (їх не вирізати), номер без пари (невідомо, до чого це приклеїти), номер, використаний понад двічі, пара країв різної довжини, місце склеювання, менше за клапан, проріз, вужчий за матеріал або коротший за язичок, а в pop-up листівці – деталь, яка після закриття листівки виступає за неї (на скільки міліметрів), і листівка, яка не закривається пласко, бо смужка платформи або плече V не відповідає відстані між місцями склеювання. Біля кожної заваги <span class=\"ui\">Відкрити зразок</span> виділяє деталь.</p><p><b>3D-макет</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"19.4\">3D-макет</a>) має для розділу паперової моделі модель <b>Паперова модель (з деталей)</b>: спершу аркуші лежать пласко друком догори, потім кожна деталь складається по своїх згинах – із друком з аркуша на гранях і картоном усередині (<b>Складені деталі</b> – стоять поруч так, як лежать на аркушах). Останнє положення, <b>Склеєна модель</b>, склеює деталі попарно в одне тіло – від найбільшої деталі наступні приходять туди, де мають приклеїтися: край до краю (з таким поворотом, щоб збігалися всі пари цієї деталі; без інших пар – під <b>Кутом після склеювання</b> з панелі краю: 180° пласко, як продовження, 90° перпендикулярно), край до прямої лінії склеювання, місця склеювання або прорізу – деталь стає перпендикулярно з боку друку, край до кривої лінії склеювання – деталь вигинається й обгортається вздовж кривої, зберігаючи свої згини (напр. козирок смужки лишається загнутим). Оздоби, тексти й зображення на гранях їдуть разом із ними. Деталі без пар з рештою лишаються на аркуші.</p><p><b>Pop-up у русі.</b> Коли згин листівки має на панелі ввімкнений <b>Корінець листівки (pop-up)</b> (pop-up шаблони мають його одразу), у вікні макета з'являється повзунок <b>Відкриття pop-up листівки</b> (0–180°). Листівка відкривається навколо корінця, а доклеєні платформи, V-згини, другі шари й вирізанки рухаються так, як у справжній книжці: грані жорсткі, згини працюють як завіси, а місця склеювання тримають доклеєні деталі. При 180° усе лежить пласко, при 90° елементи стоять, а коли листівка майже закрита – складаються всередину. Налаштування зберігається в кадрі.</p><p><b>Елементи під кутом із будь-якої деталі.</b> Шаблон V не потрібен: намалюйте на листівці з корінцем дві прямі <b>лінії склеювання</b> з обох боків корінця (скісно до нього) і з'єднайте з ними краї будь-якої деталі – у макеті деталь стане під кутом, що випливає з геометрії. Панель листівки для кожної прямої лінії показує <b>кут до корінця</b> і відстань від нього, а панель доклеєної деталі має розділ <b>Pop-up</b>: під яким кутом вона стоїть, коли листівка відкрита на 90°, як далеко сягає від листівки і чи після закриття ховається в листівці, чи виступає (на скільки міліметрів).</p>"},{"id":"10.13","tytul":"Комікс","html":"<p>Комікс – це доповнення до звичайної публікації: зошита, книжки, окремих аркушів або файлу для перегляду на екрані. Усе працює без ШІ; ШІ (із зірочкою ✦) може допомогти написати сценарій і намалювати кадри.</p><p><b>Як почати</b></p><ul class=\"punkty\"><li><b>З шаблону:</b> <b>Новий проєкт</b> → <b>Почати з: Готового шаблону</b> → <b>Комікс</b>. Ви отримаєте сторінки з готовими кадрами, приклад сценарію, картки двох персонажів (Аля й Оля) і місця (Містечко).</li><li><b>Порожній проєкт:</b> <b>Новий проєкт</b> → <b>Почати з: Порожньої сторінки</b> → позначте <b>Це комікс – кадри, бульбашки, сценарій і персонажі</b>.</li><li><b>До наявного проєкту:</b> <span class=\"ui\">Розділ</span> → тип <b>Комікс</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>).</li></ul><p>У шаблоні вибираєте <b>Форму</b> коміксу:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Форма</th><th>Що отримуєте</th></tr></thead><tbody><tr><td><b>Зошит (брошура) з обкладинкою – для друку</b></td><td>Обкладинка на скобі (з місцем для назви й малюнка) і сторінки коміксу, скріплені скобами.</td></tr><tr><td><b>Книжка в м’якій обкладинці – для друку</b></td><td>Обкладинка з корінцем і сторінки коміксу.</td></tr><tr><td><b>Окремі аркуші – без обкладинки</b></td><td>Лише сторінки коміксу, напр. для друку вдома.</td></tr><tr><td><b>На екран – PDF або презентація (горизонтально)</b></td><td>Горизонтальні сторінки, як слайди, без вильоту – для перегляду в попередньому перегляді або як PDF для екрана.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-komiks.png\" alt=\"Сторінка коміксу з кадрами й бульбашками; на панелі Кадри, Бульбашка і Комікс\" loading=\"lazy\"><figcaption>Сторінка коміксу з кадрами й бульбашками; на панелі Кадри, Бульбашка і Комікс</figcaption></figure><p><b>Панель коміксу.</b> На сторінці коміксу панель вставлення має додаткові кнопки:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Кнопка</th><th>Що робить</th></tr></thead><tbody><tr><td><span class=\"ui\">Кадри</span></td><td>Готове розташування кадрів на цій сторінці, відступ між кадрами, виліт; у тому самому вікні <span class=\"ui\">Розділити кадр</span>.</td></tr><tr><td><span class=\"ui\">Бульбашка ▾</span></td><td>Меню: бульбашка <b>Мова</b>, <b>Думка</b>, <b>Крик</b>, <b>Шепіт</b>, <b>Оповідь</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.14\">Бульбашка</a>), <b>Звуковий ефект</b> (напис «БАХ!» великими літерами з обведенням) і <b>Місток</b> (з’єднує дві виділені бульбашки одного персонажа).</td></tr><tr><td><span class=\"ui\">Комікс</span></td><td>Вікно <b>Комікс крок за кроком</b> – увесь комікс за п’ять кроків (опис нижче).</td></tr></tbody></table></div><p>Інструменти ШІ для коміксу – <b>Сценарій зі ШІ</b>, <b>Еталонні зображення персонажів і місць</b>, <b>Намалювати кадри</b> – є в меню <span class=\"ui\">ШІ ▾</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.11\">Зображення ШІ</a>), а розмова зі ШІ – під <span class=\"ui\">Асистент ШІ</span> на верхній панелі (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Асистент ШІ в Makietka (власний ключ)</a>). Коли у вас немає ключа Google Gemini, пункти малювання й писання неактивні (сірі), а вгорі меню є <b>У вас немає ключа для генерування зображень і текстів – додайте ключ…</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.11\">Зображення ШІ</a>).</p><p><b>Комікс у Бібліотеці.</b> <span class=\"ui\">Бібліотека</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.8\">Бібліотека</a>) має категорію <b>Комікс</b>: бульбашки кожного виду й звуковий ефект, готові розкладки кадрів (клік замінює кадри на цій сторінці; зображення й бульбашки лишаються), растр і лінії руху, а на сторінці комікса також <b>Вікна комікса</b>: <b>Комікс крок за кроком</b>, <b>Сценарій</b>, <b>Персонажі, місця й реквізит</b>, <b>Завантажити готові сторінки</b> і <b>Вебтун – для читання на телефоні</b>. Це зручний шлях на телефоні, де панель коротша.</p><h4>Комікс крок за кроком</h4><p><span class=\"ui\">Комікс</span> відкриває вікно з п’ятьма кроками. Біля кожного кроку видно, що вже є (напр. «Є: 5 реплік на 2 сторінках»). Робіть їх по черзі або поверніться до будь-якого – кожна кнопка відкриває своє вікно.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-komiks-okno.png\" alt=\"Вікно «Комікс крок за кроком»\" loading=\"lazy\"><figcaption>Вікно «Комікс крок за кроком»</figcaption></figure><ol class=\"kroki\"><li><b>Історія</b> – <span class=\"ui\">Відкрити сценарій</span> (вікно <b>Сценарій</b>, нижче) або <span class=\"ui\">Написати зі ШІ…</span> (Сценарій зі ШІ, нижче).</li><li><b>Персонажі, місця й реквізит</b> – <span class=\"ui\">Персонажі, місця й реквізит…</span>: картки персонажів, місць і реквізиту та <b>Стиль малюнків</b>. Мініатюри показують еталонні зображення.</li><li><b>Кадри й зображення</b> – <span class=\"ui\">Розташування кадрів…</span>, <span class=\"ui\">Намалювати кадри цієї сторінки…</span> (ШІ) або <span class=\"ui\">Завантажити готові сторінки…</span>.</li><li><b>Бульбашки</b> – <span class=\"ui\">Розставити бульбашки</span>: тексти зі сценарію потрапляють у бульбашки в кадрах.</li><li><b>Готовий комікс</b> – <span class=\"ui\">Попередній перегляд</span>, <span class=\"ui\">PDF…</span> (для друку або для екрана) і <span class=\"ui\">Вебтун</span> (стрічка для читання на телефоні).</li></ol><h4>Крок 1. Сценарій</h4><p>Вікно <b>Сценарій</b> показує комікс сторінка за сторінкою: на кожній сторінці кадри, у кожному кадрі репліки. Не треба вписувати номери чи пам’ятати назви стовпців.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-komiks-scenariusz.png\" alt=\"Вікно «Сценарій»: сторінка, кадри, план, місце, хто в кадрі й репліки\" loading=\"lazy\"><figcaption>Вікно «Сценарій»: сторінка, кадри, план, місце, хто в кадрі й репліки</figcaption></figure><p>У кожному кадрі:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Поле</th><th>Що вибрати або вписати</th></tr></thead><tbody><tr><td><b>План</b></td><td>Як видно сцену: <b>загальний план</b> (усе місце), <b>повний план</b> (персонажі з ніг до голови), <b>середній план</b> (від пояса вгору), <b>великий план</b> (обличчя), <b>деталь</b> (важливий предмет), <b>згори</b>, <b>знизу</b>, <b>з-за плеча</b>. <b>План: будь-який</b> – без вимог.</td></tr><tr><td><b>Місце</b></td><td>Місце з карток (крок 2) – його опис і зображення стануть тлом кадру.</td></tr><tr><td><b>Персонажі в кадрі</b></td><td>Позначте персонажів, яких видно в кадрі, зокрема тих, що нічого не говорять (ті, хто говорить, позначені самі). Біля кожного персонажа в кадрі виберіть <b>емоцію</b> (радість, смуток, злість, страх, здивування, цікавість, спокій, втома) і впишіть, <b>що робить</b>, напр. «біжить, махає рукою». Тоді ШІ малює персонажа з таким виразом обличчя і в такому русі.</td></tr><tr><td><b>Реквізит у кадрі</b></td><td>Предмети з карток реквізиту, які видно в кадрі (напр. <b>Посилка</b>). Їхній опис і еталонне зображення йдуть до ШІ.</td></tr><tr><td><b>Що видно в кадрі</b></td><td>Коротко, напр. «Аля біжить вуличкою, позаду будинки». На сторінку не потрапляє – це опис для художника або ШІ.</td></tr><tr><td><b>Репліки</b></td><td><span class=\"ui\">+ Репліка</span>: <b>Хто говорить</b> (персонаж із карток або <b>Оповідь</b>), <b>Вид бульбашки</b> (мова, думка, крик, шепіт) і <b>Текст бульбашки</b>. Значок кошика видаляє репліку.</td></tr></tbody></table></div><p><span class=\"ui\">+ Кадр</span> додає кадр на сторінці, <span class=\"ui\">+ Сторінка</span> – нову сторінку сценарію; значок кошика біля кадру видаляє кадр. <span class=\"ui\">Зберегти</span> зберігає сценарій. Персонажів і місця додасте на кроці 2 – потім виберете їх тут зі списку.</p><p><b>Для досвідчених.</b> Сценарій – це звичайна таблиця даних <b>Scenariusz</b> (один рядок на репліку, стовпці <b>strona</b>, <b>kadr</b>, <b>ujęcie</b>, <b>miejsce</b>, <b>w kadrze</b>, <b>opis sceny</b>, <b>postać</b>, <b>tekst</b>, <b>rodzaj</b>). <span class=\"ui\">Таблиця</span> у вікні «Сценарій» відкриває її у вікні <b>Дані</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14\">Таблиці даних</a>) – там вставите сценарій з електронної таблиці (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14.3\">Виправлення даних у застосунку</a>) або додасте стовпці з іншими мовами. Сторінка 1 – це перша сторінка коміксу (обкладинка не рахується).</p><p><b>Сценарій зі ШІ.</b> <span class=\"ui\">Написати зі ШІ…</span> на кроці 1 (або <span class=\"ui\">ШІ ▾</span> → <b>Сценарій зі ШІ</b>) розписує комікс за вас – разом з емоціями й діями персонажів:</p><ol class=\"kroki\"><li>Виберіть <b>З ідеї</b> й опишіть історію в 3–5 реченнях, напр. «Дві подруги, Аля й Оля, знаходять під дверима пакунок. Усередині кошеня…», і задайте <b>Скільки сторінок</b>. Або виберіть <b>З документа</b> й файл зі сценарієм чи оповіданням: Word (.docx), LibreOffice (.odt), Markdown (.md) або текст (.txt). З Google Docs: <b>Файл → Завантажити → Microsoft Word</b>. Діалоги з документа лишаються дослівно.</li><li>Клацніть <span class=\"ui\">Розписати</span>. За кілька секунд побачите попередній перегляд: сторінки, кадри, хто говорить, текст, що видно в кадрі.</li><li><span class=\"ui\">Зберегти сценарій</span> – сценарій потрапляє у вікно <b>Сценарій</b> (з планами, місцями й персонажами в кадрах), з’являються картки персонажів і місць (наявні картки лише доповнюються), а сторінки без кадрів отримують кадри. <span class=\"ui\">Назад</span> повертає до опису без збереження.</li></ol><p>Вартість – бл. один гріш; її видно перед розписуванням.</p><h4>Крок 2. Персонажі, місця й реквізит</h4><p><span class=\"ui\">Персонажі, місця й реквізит…</span> відкриває картки. Опишіть персонажа один раз – опис і еталонне зображення стежать, щоб він виглядав однаково в кожному кадрі (для вас, художника або ШІ).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-komiks-postacie.png\" alt=\"Картки персонажів і місць\" loading=\"lazy\"><figcaption>Картки персонажів і місць</figcaption></figure><ul class=\"punkty\"><li><b>Персонаж:</b> <b>Ім’я</b>, <b>Вигляд</b> (напр. «8 років, руді коси, зелена сукня»), <b>Прикмета</b> (напр. «жовтий рюкзак»), <b>Характер</b>, <b>Еталонне зображення</b> і <b>Колір бульбашки</b> (бульбашки цього персонажа отримають цей колір тла; білий – звичайна бульбашка).</li><li><b>Місце:</b> <b>Місце</b> (назва), <b>Опис</b>, <b>Пора дня</b>, <b>Світло</b> і <b>Еталонне зображення</b> – вигляд самого місця, без персонажів. У кадрах із цим місцем (вибраним у сценарії) зображення місця є тлом, а персонажі стоять на ньому.</li><li><b>Еталонне зображення:</b> <span class=\"ui\">Вибрати зображення…</span> – малюнок або фото з пристрою; або <span class=\"ui\">Намалювати з опису (ШІ)</span> – ШІ малює його з полів картки в стилі коміксу (вартість видно перед малюванням, бл. 0,14 зл). Персонаж – на весь зріст на білому тлі; місце – широкий вигляд без людей.</li><li><b>Реквізит:</b> предмет, який повертається в багатьох кадрах (рюкзак, повітряний змій, мапа) – <b>Реквізит</b> (назва), <b>Опис</b>, <b>Чий (персонаж)</b> і <b>Еталонне зображення</b> (сам предмет на білому тлі). У сценарії позначаєте його в кадрі (<b>Реквізит у кадрі</b>); реквізит, згаданий в описі сцени, ШІ візьме й без позначення. Шаблон <b>Комікс</b> має прикладову <b>Посилку</b>.</li><li><b>Стиль малюнків</b> (угорі вікна; кожна плитка показує ту саму прикладову сцену в цьому стилі): <b>Кольорова казка</b>, <b>Акварель</b>, <b>Простий мультяшний</b>, <b>Манга (чорно-біла)</b>, <b>Ретрокомікс</b>, <b>Ескіз олівцем</b>, <b>Європейський комікс (чиста лінія)</b>, <b>Комікс про супергероїв</b>, <b>Аніме (кольорове)</b> або <b>Витинанка з паперу</b> – діє для всіх зображень ШІ в цьому коміксі.</li></ul><figure class=\"kadr\"><img src=\"img/instrukcja/k-komiks-postac.png\" alt=\"Картка персонажа\" loading=\"lazy\"><figcaption>Картка персонажа</figcaption></figure><p>Клацання картки відкриває її для виправлення, <span class=\"ui\">Зберегти</span> зберігає, <span class=\"ui\">Видалити</span> видаляє картку (бульбашки й зображення на сторінках лишаються). Картки – це звичайні таблиці <b>Персонажі</b> і <b>Місця</b> – їх видно й у вікні <b>Дані</b>.</p><h4>Крок 3. Кадри й зображення</h4><p><b>Розташування кадрів.</b> <span class=\"ui\">Кадри</span> на панелі (або <span class=\"ui\">Розташування кадрів…</span> на кроці 3) показує 9 готових розташувань (1–9 кадрів). Клацніть попередній перегляд, задайте <b>Відступ між кадрами (мм)</b> і за потреби <b>На виліт</b> – кадри біля краю тоді виходять за сторінку аж до лінії обрізу. <span class=\"ui\">Розкласти кадри</span> замінює кадри на цій сторінці; зображення й бульбашки лишаються. <span class=\"ui\">Розділити кадр</span> у цьому вікні: клацніть на сторінці дві точки – лінія між ними ділить кадр на два (може бути косою). <kbd>Esc</kbd> завершує.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-komiks-kadry.png\" alt=\"Вікно «Кадри» – 9 готових розташувань\" loading=\"lazy\"><figcaption>Вікно «Кадри» – 9 готових розташувань</figcaption></figure><p>Кадр – це фігура з білим тлом і чорним контуром, з номером у порядку читання (рядами згори, у ряду зліва направо – у шарах «Kadr 1», «Kadr 2»…). Переміщуєте й змінюєте його як будь-яку фігуру; зображення вставите в кадр як у будь-яку фігуру (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.7\">Зображення у фігурі</a>), напр. перетягнувши файл на кадр. Персонаж може виходити за кадр – тоді покладіть зображення над кадром.</p><p><b>Намалювати кадри (ШІ).</b> Відкрийте сторінку коміксу й клацніть <span class=\"ui\">Намалювати кадри цієї сторінки…</span> на кроці 3 (або <span class=\"ui\">ШІ ▾</span> → <b>Намалювати кадри</b>). Ви не пишете запитів до ШІ – Makietka складає їх зі сценарію й карток:</p><ol class=\"kroki\"><li>Вікно показує кожен кадр сторінки: мініатюру, поле з описом і позначку. Опис українською, напр. «Кадр 2. План: повний план. Сцена: Аля біжить вулицею. У кадрі: Аля – 8 років, руді коси…, завжди: жовтий рюкзак, емоція: радість, робить: біжить. Місце (тло): Містечко…».</li><li>Виправте опис, якщо хочете. Кадри із зображенням не позначені – позначте їх, щоб намалювати ще раз.</li><li>Виберіть <b>Якість</b> і перевірте вартість під списком.</li><li><span class=\"ui\">Намалювати</span> – кадри заповнюються по черзі («Малюю 2 з 3…»). Еталонні зображення персонажів і місця йдуть до ШІ разом з описом, тож персонажі й тло виглядають однаково в кожному кадрі. Написів на зображеннях немає – текст у бульбашках.</li></ol><p><b>Уся сторінка одним зображенням.</b> У вікні малювання позначте <b>Уся сторінка одним зображенням – дешевше й цілісніше; ШІ малює й рамки кадрів (зображення замінить кадри сторінки, бульбашки лишаються)</b>. ШІ отримує описи всіх кадрів одразу, розкладку кадрів сторінки й еталонні зображення персонажів і малює всю сторінку – з рамками кадрів, одним світлом і одним стилем ліній. Коштує як одне зображення (напр. бл. 0,14 зл в ескізі замість бл. 0,42 зл за три кадри). Зображення лягає на всю сторінку з полями під обріз, а кадри сторінки зникають (вони вже на зображенні). Якщо хочете виправляти кадри окремо, малюйте кадр за кадром.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-komiks-cala-strona.jpg\" alt=\"Уся сторінка комікса, намальована одним зображенням (Ескіз), – перед додаванням бульбашок\" loading=\"lazy\"><figcaption>Уся сторінка комікса, намальована одним зображенням (Ескіз), – перед додаванням бульбашок</figcaption></figure><p><b>Намалювати ще раз.</b> Зображення не подобається? Знову відкрийте <span class=\"ui\">Намалювати кадри цієї сторінки…</span> й позначте цей кадр. Поле опису показує опис, <b>з якого постало теперішнє зображення</b> – виправте одне слово або намалюйте ще раз без змін. <span class=\"ui\">Опис зі сценарію</span> повертає до опису, складеного заново (напр. після зміни сценарію чи картки). Попередні зображення лишаються в <b>Зображеннях проєкту</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.5\">Вікно «Зображення проєкту»</a>). Дрібну зміну в одному кадрі (напр. «Аля має заплющити очі») зробите без малювання заново: виділіть кадр → <span class=\"ui\">ШІ ▾</span> → <b>Виправити зображення в рамці…</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.11\">Зображення ШІ</a>).</p><p><b>Зображення, зроблені деінде.</b> Не обов'язково малювати в Makietka. Зображення з безкоштовного Gemini, із Flow, з іншого генератора або власні малюнки й скани вставите так:</p><ol class=\"kroki\"><li>Відкрийте сторінку коміксу, з якої мають починатися зображення.</li><li><b>Перетягніть кілька файлів разом на сторінку</b> (або файл ZIP) – або клацніть <span class=\"ui\">Завантажити готові зображення…</span> на кроці 3 й виберіть файли.</li><li>Зображення потрапляють по черзі в порожні кадри: від цієї сторінки далі, в порядку читання, файли в порядку назв. Кадри із зображенням пропускаються. Якщо кадрів забракне, Makietka скаже, яких файлів не вставила.</li></ol><p>Одне зображення, кинуте на кадр, потрапляє в цей кадр (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.7\">Зображення у фігурі</a>). Номер у назві файлу ставить зображення на конкретне місце:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Назва файлу</th><th>Куди потрапляє</th></tr></thead><tbody><tr><td><code>01.png</code>, <code>стор 7.jpg</code>, <code>page_3.png</code></td><td>Уся сторінка 1 (7, 3) на виліт. Кадри цієї сторінки зникають (вони вже є на малюнку), бульбашки лишаються над зображенням.</td></tr><tr><td><code>s03-k2.png</code>, <code>стор3_кадр2.jpg</code></td><td>Кадр 2 на сторінці 3 – зображення заповнює кадр (перемістите його подвійним клацанням, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7\">Зображення</a>).</td></tr><tr><td>будь-яка інша, напр. <code>Gemini_Generated_Image_….png</code></td><td>Наступний порожній кадр.</td></tr></tbody></table></div><p>Сторінки рахуються від першої сторінки коміксу; бракуючі сторінки додаються в кінці розділу.</p><p><b>Описи кадрів для безкоштовного ШІ.</b> У вікні <b>Намалювати кадри</b> клацніть <span class=\"ui\">Копіювати описи кадрів</span>. Makietka копіює в буфер обміну описи всіх кадрів цієї сторінки – зі стилем малюнків і проханням «без написів і бульбашок». Вставте їх у безкоштовний Gemini або Flow, завантажте зображення й перетягніть їх на сторінку (вище). Без ключа Google Gemini вікно доступне саме для цього: <span class=\"ui\">Намалювати</span> неактивна (сіра), а копіювання описів працює.</p><h4>Крок 4. Бульбашки</h4><p><span class=\"ui\">Розставити бульбашки</span> ставить бульбашки з текстами зі сценарію у відповідних кадрах, із хвостиком донизу. Потім:</p><ol class=\"kroki\"><li>Перемістіть бульбашки й кінці хвостиків туди, де вони пасують до малюнка.</li><li>Виправляєте сценарій? Клацніть знову <span class=\"ui\">Розставити бульбашки</span> – зміниться лише текст; переміщені бульбашки лишаються на місці. Репліка, вилучена зі сценарію, вилучає свою бульбашку.</li></ol><ul class=\"punkty\"><li>Коли персонаж говорить двічі поспіль в одному кадрі, друга бульбашка стає під першою і з’єднується з нею <b>містком</b>. Вручну: виділіть дві бульбашки (із <kbd>Shift</kbd>) → <span class=\"ui\">Бульбашка ▾</span> → <b>Місток</b>; виділіть з’єднану бульбашку й виберіть <b>Місток</b> ще раз – роз’єднаєте.</li><li>Бульбашку вставите й вручну: <span class=\"ui\">Бульбашка ▾</span> → вид бульбашки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.14\">Бульбашка</a>). <b>Звуковий ефект</b> – це напис «БАХ!» великими літерами з обведенням – змініть текст, збільште, поверніть.</li><li><b>Стилі коміксу.</b> Бульбашки мають стиль <b>Діалог</b> (Comic Neue, великі літери), ефекти – стиль <b>Звуковий ефект</b> (Bangers, жовтий із чорним обведенням). Зміна стилю (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.4\">Стилі</a>) змінює одразу всі бульбашки або ефекти. В українському проєкті обидва стилі мають шрифт Pangolin (із кирилицею).</li><li><b>Мовні версії.</b> Додайте до таблиці сценарію (вікно <b>Дані</b>) стовпці <code>tekst_en</code>, <code>tekst_uk</code>… <span class=\"ui\">Розставити бульбашки</span> тоді запитає, з якого стовпця брати тексти – той самий комікс отримує тексти іншою мовою. Стовпець перекладе й ШІ: кнопка <b>✦</b> біля назви стовпця (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14.6\">Заповнити стовпець за допомогою ШІ</a>), напр. «переклади стовпець tekst англійською».</li></ul><h4>Крок 5. Готовий комікс</h4><ul class=\"punkty\"><li><span class=\"ui\">Попередній перегляд</span> – увесь комікс сторінка за сторінкою або розворотами (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"19\">Перегляд</a>).</li><li><span class=\"ui\">PDF…</span> – файл для друкарні або для екрана (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Експорт у PDF і PNG</a>). Комікс у формі <b>На екран</b> збережіть як PDF для екрана – відкриєте його на комп’ютері й телефоні, як презентацію.</li><li><span class=\"ui\">Вебтун</span> – сторінки коміксу одна під одною як зображення у файлі ZIP, готові до завантаження на платформу для читання коміксів на телефоні.</li></ul><p><b>Перевірити перед друком</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>) стежить за коміксом: текст у бульбашці менший за 7 pt, бульбашка, що виходить за сторінку або лежить на двох кадрах, хвостик, спрямований поза кадри, і порожні кадри (без зображення). Біля зауваження про бульбашку <span class=\"ui\">Відкрити зразок</span> виділяє її на сторінці.</p><p><b>Растр і лінії руху.</b> У <span class=\"ui\">Бібліотека</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.8\">Бібліотека</a>), у <b>Тлах і візерунках</b>, є коміксові візерунки: <b>Коміксний растр</b>, <b>Лінії руху (радіальні)</b> – для вибуху, здивування – і <b>Лінії руху (горизонтальні)</b> – для швидкості. Той самий візерунок можна накласти на виділену фігуру, напр. кадр (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.5\">Заливка</a>).</p><h4>Приклад: комікс зі ШІ від ідеї до PDF</h4><ol class=\"kroki\"><li><b>Новий проєкт</b> → <b>Почати з: Готового шаблону</b> → <b>Комікс</b>, форма <b>Зошит (брошура) з обкладинкою – для друку</b>, 8 сторінок.</li><li><span class=\"ui\">Комікс</span> → крок 1 <span class=\"ui\">Написати зі ШІ…</span> → <b>З ідеї</b>: «Аля й Оля знаходять під дверима пакунок із кошеням і шукають його власника», <b>Скільки сторінок</b>: 3 → <span class=\"ui\">Розписати</span> → <span class=\"ui\">Зберегти сценарій</span>.</li><li>Крок 1 <span class=\"ui\">Відкрити сценарій</span> – перегляньте кадри; напр. у кадрі 1 сторінки 1 задайте план <b>загальний план</b> і місце <b>Містечко</b>. <span class=\"ui\">Зберегти</span>.</li><li>Крок 2 <span class=\"ui\">Персонажі, місця й реквізит…</span> – виберіть <b>Стиль малюнків</b>, у кожній картці <span class=\"ui\">Намалювати з опису (ШІ)</span> → <span class=\"ui\">Зберегти</span>.</li><li>Перейдіть на першу сторінку коміксу. Крок 3 <span class=\"ui\">Намалювати кадри цієї сторінки…</span> → <span class=\"ui\">Намалювати</span>. Повторіть на наступних сторінках.</li><li>Крок 4 <span class=\"ui\">Розставити бульбашки</span> і перемістіть бульбашки туди, де вони пасують.</li><li>Крок 5 <span class=\"ui\">PDF…</span>.</li></ol><p><b>Скільки це коштує.</b> 3 сторінки по 3 кадри й два персонажі в якості <b>Ескіз</b>: 2 еталонні зображення + 9 кадрів = 11 зображень, <b>бл. 1,50 зл</b> і кілька хвилин. Сценарій – бл. один гріш. На 24 сторінки (бл. 85 зображень) вийде бл. 12 зл в ескізі; в якості <b>Детальний</b> – приблизно втричі більше. Makietka показує вартість перед кожним малюванням.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-komiks-ai-przyklad.png\" alt=\"Сторінка 1 прикладу коміксу, намальована ШІ (Ескіз), з бульбашками зі сценарію\" loading=\"lazy\"><figcaption>Сторінка 1 прикладу коміксу, намальована ШІ (Ескіз), з бульбашками зі сценарію</figcaption></figure><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> Зображення для кадрів можна зробити в будь-якій програмі – текст завжди лишається в бульбашках Makietki, не в зображенні, тож його легко виправити й перекласти.</p>"}]},
  {"nr":"11","tytul":"Шаблони сторінок","czesc":"Редактор","ikona":"olowek","sekcje":[{"id":"11.1","tytul":"Що таке шаблон сторінки і коли його використовувати","html":"<p>Деякі речі повторюються на багатьох сторінках: <b>номер сторінки, верхній колонтитул, нижній колонтитул, тло, рамка, лінії для письма</b>. Замість вставляти їх на кожну сторінку окремо, ви вставляєте їх один раз — як <b>шаблон сторінки</b>.</p><ul class=\"punkty\"><li>Шаблон лежить <b>під</b> вмістом кожної сторінки, яка його має. На самій сторінці ви його не виділите й не зсунете — завдяки цьому він випадково не з'їде.</li><li>Змінюєте його один раз, а змінюються <b>усі</b> ці сторінки.</li><li>Поле <code>{номер}</code> у шаблоні показує на кожній сторінці її власний номер: один шаблон, а на сторінках 1, 2, 3…</li><li>Сторінка може мати кілька шаблонів одночасно, напр. «Клітинка» під вмістом і «Номер сторінки» внизу.</li></ul><p>Коли шаблон, а коли звичайний елемент? Якщо щось має бути <b>на багатьох сторінках у тому самому місці</b> — шаблон. Якщо лише на одній сторінці — звичайний елемент.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-wzorce-galeria.png\" alt=\"Вікно «Шаблони сторінок»: що це таке і готові шаблони\" loading=\"lazy\"><figcaption>Вікно «Шаблони сторінок»: що це таке і готові шаблони</figcaption></figure>"},{"id":"11.2","tytul":"Де шаблони сторінок","html":"<ul class=\"punkty\"><li><span class=\"ui\">Шаблони</span> під списком сторінок (поруч із <span class=\"ui\">Розділ</span>) і на верхній панелі редактора — відкриває вікно <b>Шаблони сторінок</b>.</li><li>Меню ⋯ сторінки → <span class=\"ui\">Шаблони цієї сторінки…</span> — переходить на цю сторінку й відкриває вікно.</li><li>Меню ⋯ розділу → <span class=\"ui\">Шаблони розділу…</span>.</li><li>Властивості сторінки (нічого не виділено) → частина <b>Шаблони</b>: які шаблони є на цій сторінці; поки в проєкті немає шаблонів, там є кнопка <span class=\"ui\">Виберіть готовий шаблон сторінки…</span>.</li><li>Бібліотека → категорія <b>Шаблони сторінок</b> — ті самі готові шаблони, що й у вікні.</li></ul><p>Сторінка, на якій лежить шаблон, має на мініатюрі маленький фіолетовий знак; підказка на ньому каже, які це шаблони.</p>"},{"id":"11.3","tytul":"Готові шаблони сторінок","html":"<p>У вікні <b>Шаблони сторінок</b> нижче є галерея готових шаблонів із попереднім переглядом — на схемі елементи шаблону чіткі, а бліді блоки – це вміст сторінки. Групи:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Група</th><th>Приклади</th></tr></thead><tbody><tr><td>Нумерація</td><td>номер унизу, біля зовнішнього краю, «Сторінка 5 з 120», у колі, на бічній смузі, римський</td></tr><tr><td>Колонтитули</td><td>назва розділу, проєкт і розділ, кольорова смуга, нижній колонтитул із контактами</td></tr><tr><td>Тла й папір</td><td>лінії, клітинка, крапки, міліметрівка, зошит із полем, кольорове тло, водяний знак</td></tr><tr><td>Рамки</td><td>у полях, подвійна, заокруглена, обведення сторінки, кутики</td></tr><tr><td>Календар і планер</td><td>закладка на краю, заголовок дня, стовпець «Нотатки», тиждень</td></tr><tr><td>Книжка</td><td>колонтитул із назвою розділу, номер і розділ угорі</td></tr><tr><td>Каталог і пропозиція, Газетка, Запрошення</td><td>логотип і контакти, шапка, колонки, декоративна рамка, смуги</td></tr></tbody></table></div><p>Клік на картці додає шаблон до проєкту й <b>одразу на всі сторінки розділу</b> відкритої сторінки — вікно закривається, а шаблон видно на сторінці. <span class=\"ui\">Скасувати</span> в повідомленні або <kbd>Ctrl</kbd>+<kbd>Z</kbd> скасовує це одним кроком. Готові шаблони припасовуються до формату й полів розділу, а кольори й шрифти беруть із набору бренду (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.9\">Бренд-кит</a>), якщо він у вас є. Після додавання це звичайний шаблон — його можна змінити.</p>"},{"id":"11.4","tytul":"На яких сторінках є шаблон","html":"<p>У вікні, у частині <b>У цьому проєкті</b>, біля кожного шаблону:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Кнопка</th><th>Що робить</th></tr></thead><tbody><tr><td><span class=\"ui\">+ Додати до цієї сторінки</span></td><td>Вмикає шаблон лише на відкритій сторінці. Повторний клік (✓) його знімає.</td></tr><tr><td><span class=\"ui\">+ До всього розділу</span></td><td>Вмикає шаблон на сторінках розділу, які не мають власного вибору.</td></tr><tr><td><span class=\"ui\">Редагувати</span></td><td>Відкриває шаблон для редагування (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.5\">Власний шаблон і редагування</a>).</td></tr><tr><td><span class=\"ui\">⋯</span></td><td><span class=\"ui\">Перейменувати</span>, <span class=\"ui\">Дублювати</span>, <span class=\"ui\">Перемістити вище</span>, <span class=\"ui\">Перемістити нижче</span>, <span class=\"ui\">Видалити шаблон</span>.</td></tr></tbody></table></div><p>Окремій сторінці шаблони можна вибрати й у властивостях сторінки: <b>Шаблони сторінки на цій сторінці</b> → <b>Як у розділі</b> або <b>Власний вибір</b> і перемикачі біля назв.</p><figure><img src=\"img/instrukcja/okno-wzorcow.png\" alt=\"Вікно «Шаблони»\" loading=\"lazy\"><figcaption>Вікно «Шаблони»</figcaption></figure>"},{"id":"11.5","tytul":"Власний шаблон і редагування","html":"<p><span class=\"ui\">Намалювати власний шаблон</span> створює порожній шаблон і одразу його відкриває. <span class=\"ui\">Редагувати</span> відкриває наявний. Фіолетова смуга над сторінкою нагадує, що ви змінюєте шаблон — усе, що тут намалюєте, з'явиться на сторінках із цим шаблоном; <span class=\"ui\">Готово</span> повертає до сторінок. На звичайних сторінках елементи шаблону видно у списку шарів, а клік там відкриває шаблон.</p><figure><img src=\"img/instrukcja/wzorce.png\" alt=\"Редагування шаблону\" loading=\"lazy\"><figcaption>Редагування шаблону</figcaption></figure>"},{"id":"11.6","tytul":"Над вмістом і дзеркальне відображення","html":"<p>Елементи шаблону лежать <b>під</b> вмістом сторінки. Виділіть елемент у шаблоні й увімкніть:</p><ul class=\"punkty\"><li><b>Над вмістом сторінки</b> — елемент перекриє вміст, напр. рамка або водяний знак,</li><li><b>Віддзеркалювати на лівих сторінках</b> — елемент біля правого краю (напр. номер сторінки) на лівих сторінках розворотів перейде до лівого краю. Готові шаблони «біля зовнішнього краю» мають це ввімкненим.</li></ul>"},{"id":"11.7","tytul":"Поля в шаблоні","html":"<p>Введіть у шаблоні текст із полем, напр. <code>Сторінка {номер} з {кількість_сторінок}</code>, <code>{розділ}</code> або <code>{глава}</code> (назва поточного розділу книжки). На кожній сторінці з'явиться її значення. Найпростіше почати з готового шаблону з номером сторінки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.3\">Готові шаблони сторінок</a>).</p>"}]},
  {"nr":"12","tytul":"Допоміжні лінії, сітка й масштаб","czesc":"Редактор","ikona":"olowek","wstep":"Речі, які допомагають розміщувати елементи, але не друкуються: поля, виліт, сітка, напрямні, масштаб.","sekcje":[{"id":"12.1","tytul":"Лінії на сторінці","html":"<p>Допоміжні лінії не друкуються:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Лінія</th><th>Значення</th></tr></thead><tbody><tr><td><b>Червона</b></td><td>Край сторінки після обрізання.</td></tr><tr><td><b>Рожева смуга</b></td><td>Виліт. Тла й фото, які мають сягати краю, розтягніть аж до її кінця.</td></tr><tr><td><b>Синя пунктирна</b></td><td>Поле. Тексти тримайте всередині.</td></tr><tr><td><b>Товста темна</b></td><td>Корінець розвороту.</td></tr><tr><td><b>Пунктирні з підписами</b></td><td>На обкладинці: згини — корінець, біги, загини (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.6\">Обкладинка з корінцем</a>).</td></tr><tr><td><b>Бірюзова</b></td><td>Напрямна (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.4\">Лінійки й напрямні</a>).</td></tr></tbody></table></div><p>Кнопка допоміжних ліній (<kbd>W</kbd>) біля масштабу ховає їх усі.</p>"},{"id":"12.2","tytul":"Попередження","html":"<p>Елемент у полі або за вильотом, текст, який не вміщається, чи поле з помилкою отримують помаранчеву рамку й потрапляють до списку <b>Попередження</b>. На комп'ютері його відкриває кнопка з трикутником біля масштабу (<kbd>F8</kbd>) — число на ній показує, скільки є зауваг; віконце не блокує роботи, закриває його хрестик або <kbd>Esc</kbd>. На телефоні — кнопка <span class=\"ui\">Попередження</span> внизу екрана. Клік на пункті виділяє елемент. Коли це навмисно (напр. тло на виліт), натисніть <span class=\"ui\">Вимкнути</span>.</p><figure><img src=\"img/instrukcja/ostrzezenia.png\" alt=\"Попередження\" loading=\"lazy\"><figcaption>Попередження</figcaption></figure>"},{"id":"12.3","tytul":"Сітка","html":"<p>У меню вигляду (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.6\">Правий нижній кут і меню вигляду</a>): <b>Сітка</b> показує лінії через <b>Крок сітки</b> (у мм, від кута сторінки), а <b>Прилипати до сітки</b> ставить лівий верхній кут переміщуваного елемента на лінію сітки.</p><figure><img src=\"img/instrukcja/siatka.png\" alt=\"Сітка й напрямні\" loading=\"lazy\"><figcaption>Сітка й напрямні</figcaption></figure>"},{"id":"12.4","tytul":"Лінійки й напрямні","html":"<ul class=\"punkty\"><li><b>Лінійки</b> показують міліметри; нуль лежить у куті відкритої сторінки.</li><li><b>Напрямну</b> витягнете з лінійки: з верхньої вниз — горизонтальну, з лівої вправо — вертикальну. Напрямну можна зсунути; витягнута за сторінку, вона зникає.</li><li>У властивостях сторінки частина <b>Напрямні</b> дає змогу ввести положення числом і додати вертикальну або горизонтальну напрямну.</li><li><b>Заблокувати напрямні</b> в меню вигляду захищає їх від випадкового зсуву.</li></ul>"},{"id":"12.5","tytul":"Прилипання й відстані","html":"<p>Під час переміщення й зміни розміру елемент прилипає до країв, полів і центру сторінки, до напрямних та інших елементів:</p><ul class=\"punkty\"><li><b>рожева лінія</b> — край або центр вирівнялися з іншим елементом,</li><li><b>стрілки з числом</b> — відстань у мм до найближчих елементів,</li><li><b>фіолетові числа</b> — відступ дорівнює іншому відступу в ряду.</li></ul><p>Утримувана <kbd>Ctrl</kbd> тимчасово вимикає прилипання. Утримувана <kbd>Alt</kbd> при виділеному елементі показує також відстані до країв сторінки.</p><figure><img src=\"img/instrukcja/odleglosci.png\" alt=\"Рівні відступи\" loading=\"lazy\"><figcaption>Рівні відступи</figcaption></figure>"},{"id":"12.6","tytul":"Масштаб","html":"<ul class=\"punkty\"><li><span class=\"ui\">−</span> і <span class=\"ui\">+</span> у правому нижньому куті; клік на відсотках припасовує сторінку до вікна (<kbd>Ctrl</kbd>+<kbd>0</kbd>).</li><li><kbd>Ctrl</kbd> + коліщатко миші збільшує в місці курсора.</li><li>Пробіл + перетягування зсуває вигляд.</li><li>На сенсорному екрані — двома пальцями (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"28.1\">Жести</a>).</li></ul>"}]},
  {"nr":"13","tytul":"Книжка: зміст, колонтитул, виноски, перехресні посилання, покажчик","czesc":"Редактор","ikona":"olowek","wstep":"Зміст, назва розділу в нижньому колонтитулі, виноски, перехресні посилання й покажчик — оновлюються самі.","sekcje":[{"id":"13.1","tytul":"Коротко","html":"<p>Номери сторінок беруться з нумерації розділів (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.8\">Нумерація сторінок</a>), також зі сторінками, розмноженими серією (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Серії</a>).</p><figure><img src=\"img/instrukcja/ksiazka.png\" alt=\"Зміст, виноска й колонтитул на сторінках книжки\" loading=\"lazy\"><figcaption>Зміст, виноска й колонтитул на сторінках книжки</figcaption></figure>"},{"id":"13.2","tytul":"Заголовки","html":"<p>Заголовки – це тексти в стилях абзацу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.4\">Стилі</a>), які проєкт вважає назвами розділів книжки. З них утворюються зміст, колонтитул і список перехресних посилань.</p><ul class=\"punkty\"><li>Без налаштувань стиль <b>Заголовок</b> (Tytuł) – це заголовок 1 (розділ книжки), а <b>Заголовок</b> (Nagłówek) – заголовок 2.</li><li>Інші стилі задасте на панелі змісту: для кожного стилю виберіть <b>заголовок 1</b>, <b>заголовок 2</b>, <b>заголовок 3</b> або <b>не є заголовком</b>.</li></ul><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> надайте той самий стиль усім назвам розділів книжки – тоді зміст і колонтитул складуться самі.</p>"},{"id":"13.3","tytul":"Зміст","html":"<ol class=\"kroki\"><li>Відкрийте <span class=\"ui\">Бібліотека</span> → <b>Книжка</b> → <b>Зміст</b> (або <kbd>Ctrl</kbd>+<kbd>K</kbd> і «зміст»).</li><li>Зміст стає на сторінці як текст і одразу заповнюється заголовками з номерами сторінок.</li><li>Вигляд (шрифт, розмір, міжрядковий інтервал) змінюєте, як у будь-якому тексті.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-spis-tresci.png\" alt=\"Зміст і його панель\" loading=\"lazy\"><figcaption>Зміст і його панель</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Що робить</th></tr></thead><tbody><tr><td><b>Рівні</b></td><td><b>лише розділи</b>, <b>розділи й підрозділи</b> або <b>три рівні</b>; нижчі рівні мають відступ.</td></tr><tr><td><b>Крапки до номера сторінки</b></td><td>Заповнює проміжок між назвою й номером крапками.</td></tr><tr><td><b>Стиль «…»</b></td><td>Який стиль є заголовком і якого рівня (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.2\">Заголовки</a>).</td></tr><tr><td><span class=\"ui\">Оновити зараз</span></td><td>Складає зміст одразу. Зазвичай не потрібно – зміст оновлюється сам після кожної зміни.</td></tr></tbody></table></div><p>Довгий зміст перелийте в наступну рамку, також на наступній сторінці (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.7\">Колонки й текст через кілька рамок</a>). Вміст змісту не вводять вручну – під час наступного оновлення він склався б заново.</p>"},{"id":"13.4","tytul":"Колонтитул","html":"<p>Колонтитул (жива пагінація) – це назва поточного розділу книжки в нижньому або верхньому колонтитулі сторінки.</p><ol class=\"kroki\"><li>Відкрийте шаблон нижнього колонтитула (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11\">Шаблони сторінок</a>).</li><li>У тексті колонтитула виберіть <b>Вставити поле</b> → <b>{глава}</b>. Поруч можна дати номер сторінки: <code>{глава} – {номер}</code>.</li></ol><p>На кожній сторінці поле показує останній заголовок 1 до цієї сторінки. <code>{глава:2}</code> показує заголовок 2 – новий розділ книжки його обнуляє.</p>"},{"id":"13.5","tytul":"Виноски","html":"<ol class=\"kroki\"><li>Виділіть текст (або пишіть у ньому – виноска стане в місці курсора).</li><li>На панелі, у частині <b>Виноски, перехресні посилання, покажчик</b>, виберіть <span class=\"ui\">Вставити виноску</span> (або <kbd>Ctrl</kbd>+<kbd>K</kbd> і «виноска»).</li><li>У полі <b>Виноска 1</b> введіть текст.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-przypisy.png\" alt=\"Виноска на панелі й унизу сторінки\" loading=\"lazy\"><figcaption>Виноска на панелі й унизу сторінки</figcaption></figure><ul class=\"punkty\"><li>У тексті з'являється номер у верхньому індексі, а текст виноски – унизу тієї самої сторінки, над нижнім полем, під короткою рискою. У редакторі його видно одразу, але виділити його не можна: змінюєте його на панелі.</li><li>Номери рахуються самі. <b>Нумерація виносок</b>: <b>Заново в кожному розділі</b>, <b>Заново на кожній сторінці</b> або <b>В усьому проєкті</b>.</li><li>Текст, що тече крізь кілька рамок, забирає виноску з собою: виноска є на тій сторінці, на якій стоїть її номер.</li><li>Вигляд виносок: стиль абзацу з назвою <b>Виноска</b> (Przypis; якщо його немає – шрифт 8 пт).</li><li><span class=\"ui\">Видалити виноску</span> прибирає і номер із тексту, і текст виноски.</li></ul>"},{"id":"13.6","tytul":"Перехресні посилання","html":"<p>Перехресне посилання – це номер сторінки іншого місця в книжці, напр. «див. с. 12».</p><ol class=\"kroki\"><li>Виділіть текст, у якому має стояти посилання.</li><li>У частині <b>Виноски, перехресні посилання, покажчик</b> виберіть зі списку <b>Вставити перехресне посилання на</b> заголовок.</li><li>У тексті з'явиться «с. 12» – номер змінюється сам, коли сторінки зсуваються.</li></ol><p>У редакторі посилання видно як поле <code>{s:…}</code>; число побачите в попередньому перегляді й у PDF. Якщо видалите заголовок, замість номера стане «?», а <b>Перевірити перед друком</b> про це нагадає (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>).</p>"},{"id":"13.7","tytul":"Покажчик","html":"<ol class=\"kroki\"><li>Виділіть слово в тексті, який пишете.</li><li>Виберіть <span class=\"ui\">Додати до покажчика</span> (або <kbd>Ctrl</kbd>+<kbd>K</kbd> і «покажчик»). Без виділення застосунок запитає про гасло.</li><li>Вставте покажчик: <span class=\"ui\">Бібліотека</span> → <b>Книжка</b> → <b>Покажчик</b>.</li></ol><p>Покажчик містить гасла за абеткою (за польським порядком: ą після a, ł після l) з номерами всіх сторінок, на яких слово трапляється в будь-якому тексті – регістр літер не має значення, а сусідні сторінки об'єднуються в діапазон (3–5). Гасла тексту видно на панелі як жетони; клік на жетоні видаляє гасло.</p>"}]},
  {"nr":"14","tytul":"Таблиці даних","czesc":"Дані й серії","ikona":"dane","wstep":"Дані зберігаються в таблицях проєкту; з них беруться значення полів і повторені сторінки.","sekcje":[{"id":"14.1","tytul":"Вікно Дані","html":"<p>Таблиця — це аркуш: стовпці мають назви (напр. <code>dzien</code>, <code>imie</code>), а рядки — значення. З таблиць беруться значення полів у тексті (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Поля в тексті</a>) і повторені сторінки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Серії</a>).</p><p>Вікно відкриває <span class=\"ui\">Дані</span> на верхній панелі редактора. Ліворуч — список таблиць проєкту, праворуч — вибрана таблиця. <span class=\"ui\">+</span> додає порожню таблицю, <span class=\"ui\">Імпортувати CSV або Excel</span> — таблицю з файлу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14.2\">Імпорт з Excel і CSV</a>), <span class=\"ui\">Пропущений рядок</span> — рядок <code>[пропустити]</code> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.4\">Пропущені рядки</a>), а <span class=\"ui\">Завантажити таблицю як файл CSV</span> дає таблицю, щоб доповнити її в електронній таблиці. Зміни, зроблені за одне відкриття вікна, скасовує одне <span class=\"ui\">Скасувати</span>.</p><figure><img src=\"img/instrukcja/dane.png\" alt=\"Вікно Дані\" loading=\"lazy\"><figcaption>Вікно Дані</figcaption></figure>"},{"id":"14.2","tytul":"Імпорт з Excel і CSV","html":"<p><span class=\"ui\">Імпортувати CSV або Excel</span> завантажує файл <code>.xlsx</code>, <code>.xls</code>, <code>.ods</code> або <code>.csv</code>:</p><ul class=\"punkty\"><li>перший рядок файлу — це назви стовпців,</li><li>з файлу Excel з'являється по одній таблиці на кожен аркуш,</li><li>роздільник (крапку з комою, кому, табуляцію) і літери з діакритикою застосунок розпізнає сам,</li><li>числа й дати потрапляють у таблицю такими, якими їх видно в аркуші. Дату найкраще розбити на окремі стовпці, напр. <code>dzien</code>, <code>miesiac</code>, <code>rok</code>.</li></ul><p>Виправили дані в аркуші? Імпортуйте файл ще раз. Якщо в проєкті є таблиця з такою самою назвою, застосунок запитає, чи замінити її дані.</p><h4>Джерело даних, прив'язане до таблиці</h4><p>Таблиця пам'ятає, звідки вона прийшла. Під її назвою видно смужку, напр. «Дані з: goscie.xlsx, аркуш »Lista« · завантажено 18.11.2026, 14:20». Оригінальний файл (до 5 МБ) зберігається в проєкті – його немає серед зображень, і він не зникає під час прибирання.</p><ul class=\"punkty\"><li><span class=\"ui\">Завантажити нову версію…</span> – ви вибираєте виправлений файл; поля й серії залишаються. Перш ніж дані заміняться, ви побачите, що зміниться: кількість рядків, змінені клітинки, нові й видалені стовпці, а окремо — попередження, коли зникає стовпець, використаний у полях сторінок (ці поля були б порожні).</li><li><span class=\"ui\">Оновити з файлу</span> – у Chrome і Edge на комп'ютері браузер пам'ятає доступ до файлу, вибраного через «Завантажити нову версію…». Після виправлення в Excel достатньо одного клацання (браузер може один раз запитати дозвіл).</li><li><b>змінено в Makietka</b> – позначка біля таблиці, яку виправляли у вікні Дані після завантаження файлу. Нова версія файлу замінить ці виправлення – запитання про заміну теж про це нагадає.</li><li>Значок стрілки вниз завантажує збережений вихідний файл, значок таблиці – поточні дані як файл Excel (<code>.xlsx</code>), кошик від'єднує джерело (дані залишаються).</li></ul><p><b>Дані за посиланням</b> (значок ланцюжка поруч з <span class=\"ui\">Імпортувати</span>) – вставте адресу таблиці Google або файлу CSV/XLSX в інтернеті. Таблиця Google має бути публічною: Файл → Надати доступ → Опублікувати в інтернеті → CSV (підійде й звичайне посилання на таблицю, доступну всім, хто має посилання). Таблиця пам'ятає посилання, а <span class=\"ui\">Оновити за посиланням</span> завантажує дані заново, з тим самим порівнянням змін. Деякі сервіси не дозволяють завантаження з браузера – тоді застосунок про це скаже; завантажте файл і відкрийте його звичайним імпортом.</p>"},{"id":"14.3","tytul":"Виправлення даних у застосунку","html":"<ul class=\"punkty\"><li>Клацніть клітинку й пишіть. <kbd>Enter</kbd> переходить на рядок нижче, <kbd>Shift</kbd>+<kbd>Enter</kbd> робить новий рядок у клітинці.</li><li>Дані, скопійовані з Excel або Таблиць Google, вставляються, починаючи з виділеної клітинки (<kbd>Ctrl</kbd>+<kbd>V</kbd>); таблиця сама розростається вниз і праворуч.</li><li><b>×</b> біля рядка або стовпця видаляє його.</li><li>Назву стовпця змінюють, клацнувши заголовок. Застосунок виправить цю назву в усіх полях проєкту.</li></ul>"},{"id":"14.4","tytul":"Вигляд клітинок","html":"<p>Жирний шрифт, курсив і колір літер із файлу Excel переходять на сторінки: значення, вставлене в поле, отримує вигляд своєї клітинки — напр. свята жирним червоним. Переходить також вигляд частини тексту в клітинці.</p><p>У вікні Дані виділіть клітинку (<kbd>Shift</kbd>+клацання виділяє прямокутник із кількох клітинок) і використайте: <span class=\"ui\">B</span> — жирний, <span class=\"ui\">I</span> — курсив, колір літер, <span class=\"ui\">Очистити вигляд</span> (гумка).</p><p>Перемикач <b>Переносити вигляд клітинок на сторінки</b> вимикає перенесення — вигляд залишається збереженим у таблиці.</p>"},{"id":"14.5","tytul":"Контроль значень","html":"<p>Біля назви кожного стовпця є два знаки:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Знак</th><th>Що робить</th></tr></thead><tbody><tr><td><b>≠</b></td><td>Значення в стовпці не повинні повторюватися (напр. гасла дня). Повторені клітинки червоні, а перед друком застосунок покаже сторінки, на яких те саме значення трапляється двічі. Регістр літер і пробіли не мають значення.</td></tr><tr><td><b>☰</b></td><td>Список дозволених значень, напр. <code>praca; dom; wolne</code>. Інші значення підсвічено, і вони потрапляють до списку перед друком; у шаблоні даних клітинки отримують випадний список. <span class=\"ui\">Видалити список</span> його видаляє.</td></tr></tbody></table></div>"},{"id":"14.6","tytul":"Заповнити стовпець за допомогою ШІ","html":"<p>Кнопка <b>✦</b> біля назви стовпця у вікні <b>Дані</b> вписує значення в стовпець – напр. «коротка думка на цей день» у календарі або «опис одним реченням» для кожного товару. Напишіть, що вписати; ШІ бачить інші стовпці рядка (напр. дату чи назву). Типово заповнює лише <b>порожні клітинки</b>; вікно показує кількість рядків і вартість (зазвичай кілька грошів за сотні рядків). Перевірте результат – вміст, що має бути точним (цитати, вірші), беріть із джерела.</p>"}]},
  {"nr":"15","tytul":"Поля в тексті","czesc":"Дані й серії","ikona":"dane","wstep":"Поле — це місце в тексті, куди потрапляє значення з таблиці або з проєкту, напр. номер сторінки.","sekcje":[{"id":"15.1","tytul":"Вставлення поля","html":"<p>Поле — це назва стовпця у фігурних дужках, вписана у звичайний текст, напр. <code>Іменини: {imieniny}</code>. На готовій сторінці на місці поля з'являється значення з таблиці.</p><p>Виділіть текст і виберіть стовпець зі списку <span class=\"ui\">Вставити поле</span> у властивостях. Список починається зі стовпців таблиці цієї сторінки, далі йдуть поля документа (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15.2\">Поля документа</a>). Поле можна також вписати вручну.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-wstaw-pole.png\" alt=\"Вставити поле\" loading=\"lazy\"><figcaption>Вставити поле</figcaption></figure><p>У редакторі поля мають фіолетовий фон, а поле, якого застосунок не знає (напр. через одруківку), — червоний. Справжні значення видно на мініатюрах, у перегляді й у PDF.</p><ul class=\"punkty\"><li>Поля з таблиці працюють на сторінках серії з цією таблицею (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Серії</a>).</li><li>Поле з додаткової таблиці вписують із назвою таблиці: <code>{Tygodnie.haslo}</code> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.5\">Додаткові таблиці</a>).</li><li>Жирне поле дасть жирне значення.</li></ul><figure><img src=\"img/instrukcja/pola.png\" alt=\"Поля в тексті\" loading=\"lazy\"><figcaption>Поля в тексті</figcaption></figure>"},{"id":"15.2","tytul":"Поля документа","html":"<p>Поля документа випливають із самого проєкту й працюють на кожній сторінці, також у шаблонах сторінок:</p><div data-wstaw=\"pola\"></div><p>Назви полів документа працюють у кожній мові застосунку: <code>{номер}</code>, <code>{page}</code> (англ.) і <code>{nr}</code> (пол.) — це те саме поле. <b>Вставити поле</b> показує назви мовою, яку ви вибрали; проєкт, відкритий іншою мовою, рахується так само.</p><p>Поля <b>з налаштувань проєкту</b> — <code>{формат}</code>, <code>{палітурка}</code>, <code>{корінець}</code>, <code>{сторінок_блоку}</code>, <code>{папір}</code>, <code>{рік_календаря}</code> (і <code>{проєкт}</code>) — не треба заповнювати: вони беруть значення з налаштувань розділу, обкладинки й календаря і змінюються разом із ними, напр. вихідні дані «Формат {формат}, оправа {палітурка}, {сторінок_блоку} сторінок». У списку <b>Вставити поле</b> вони в окремій групі <b>З налаштувань проєкту</b>. Якщо в проєкті немає обкладинки чи календаря, поле порожнє.</p><p>Коли стовпець таблиці називається так само, як поле документа, на сторінках цієї таблиці перемагає стовпець.</p>"},{"id":"15.3","tytul":"Звичайні фігурні дужки","html":"<ul class=\"punkty\"><li>Увесь текст без полів: виділіть текст і ввімкніть <b>Фігурні дужки { } — звичайний текст, а не поля</b> (перемикач з'являється, коли в тексті є фігурні дужки).</li><li>Поле й дужки в одному тексті: впишіть дужки подвійно — <code>{{</code> і <code>}}</code> стануть одинарними дужками, напр. <code>День {dzien}, формула {{x}}</code> дасть «День 5, формула {x}».</li></ul>"}]},
  {"nr":"16","tytul":"Серії","czesc":"Дані й серії","ikona":"dane","wstep":"Серія повторює сторінку для кожного рядка таблиці — так з однієї сторінки з'являється календар на 365 днів.","sekcje":[{"id":"16.1","tytul":"Що таке серія","html":"<p>Ви проєктуєте одну сторінку дня — і отримуєте 365 сторінок, кожну з даними свого рядка. Серія може охоплювати кілька сусідніх сторінок (<b>блок</b>), напр. тиждень на розвороті: тоді весь блок повторюється разом.</p><p>Повторені сторінки не зберігаються окремо — вони створюються на льоту, тож зміна таблиці одразу змінює видання.</p>"},{"id":"16.2","tytul":"Нова серія","html":"<ol class=\"kroki\"><li>Клацніть порожнє місце сторінки — властивості покажуть налаштування сторінки.</li><li>У полі <b>Серія</b> виберіть <span class=\"ui\">+ Нова серія…</span>.</li><li>Налаштуйте серію у вікні (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.3\">Налаштування серії</a>) і клацніть <span class=\"ui\">Зберегти</span>.</li><li>Наступним сторінкам блоку виберіть ту саму серію.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-seria.png\" alt=\"Серія у властивостях сторінки\" loading=\"lazy\"><figcaption>Серія у властивостях сторінки</figcaption></figure><p>Сторінки серії мають у списку сторінок фіолетовий значок із кількістю повторень, напр. <b>×31</b>. <b>×0</b> означає, що всі рядки цієї сторінки пропускаються.</p><figure><img src=\"img/instrukcja/serie.png\" alt=\"Повторені сторінки в перегляді\" loading=\"lazy\"><figcaption>Повторені сторінки в перегляді</figcaption></figure>"},{"id":"16.3","tytul":"Налаштування серії","html":"<p>Вікно серії відкривається після вибору <span class=\"ui\">+ Нова серія…</span>, а для наявної серії — кнопкою <span class=\"ui\">Налаштування серії</span> у властивостях сторінки. Під полем <b>Серія</b> видно, скільки сторінок вийде в друці.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><b>Назва серії</b></td><td>Назва в списку серій.</td></tr><tr><td><b>Дані з таблиці</b></td><td>Таблиця, з якої беруться рядки.</td></tr><tr><td><b>Скільки разів повторити</b></td><td>Перемикач: <b>Стільки, скільки рядків у таблиці</b> або <b>Фіксовану кількість разів</b> (тоді з'являється поле <b>Кількість повторень</b>) — напр. 12 місяців; дані тоді йдуть по колу.</td></tr><tr><td><b>Як читати таблицю</b></td><td>Перемикач: <b>Рядок на весь блок</b> (стовпці напр. <code>s1_tytul</code>, <code>s2_tytul</code> для наступних сторінок) або <b>Рядок на кожну сторінку</b>.</td></tr><tr><td><b>Доповнити останній блок сторінками без даних</b></td><td>Серія закінчується на останньому рядку; з цим налаштуванням останній блок повний.</td></tr><tr><td><b>Стежити за лівою й правою сторінкою</b></td><td>На розворотах (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.6\">Серії на розворотах</a>).</td></tr><tr><td><b>Додаткові таблиці</b></td><td>Дані, що змінюються рідше, ніж сторінки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.5\">Додаткові таблиці</a>).</td></tr><tr><td><b>Дані, потрібні сторінкам</b></td><td>Поля, використані на сторінках блоку. <span class=\"ui\">Додати відсутні стовпці до таблиці</span> дописує відсутні.</td></tr><tr><td><span class=\"ui\">Завантажити шаблон даних (Excel)</span></td><td>Файл зі стовпцями, потрібними сторінкам (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.7\">Шаблон даних</a>).</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-seria-segmenty.png\" alt=\"Сегменти у вікні Серії\" loading=\"lazy\"><figcaption>Сегменти у вікні Серії</figcaption></figure>"},{"id":"16.4","tytul":"Пропущені рядки","html":"<p>Приклад: календар із блоком на тиждень (понеділок–неділя), а рік починається в четвер. Без нічого 1 січня потрапило б на сторінку понеділка. Тож допишіть на початку таблиці три <b>пропущені рядки</b> — за понеділок, вівторок і середу.</p><p>Пропущений рядок має в першій клітинці позначку <code>[пропустити]</code>. Він займає своє місце в блоці, але його сторінка не створюється: її немає в перегляді, у PDF ані в нумерації. Вставити його можна кнопкою <span class=\"ui\">Пропущений рядок</span> у вікні Дані — над рядком, у якому стоїть курсор, — або вписати <code>[пропустити]</code> в Excel. Позначка працює в кожній мові: <code>[пропустити]</code>, <code>[skip]</code> (англ.) і <code>[pomiń]</code> (пол.) означають те саме.</p><p>Кінець року нічого не потребує: серія закінчується на останньому рядку даних.</p>"},{"id":"16.5","tytul":"Додаткові таблиці","html":"<p>Додаткова таблиця дає дані, що змінюються рідше, ніж сторінки, — напр. гасло тижня на сторінках днів або картинку місяця. У вікні серії: <span class=\"ui\">Додати таблицю</span>, а потім <b>Новий рядок</b>:</p><ul class=\"punkty\"><li><b>через фіксовану кількість сторінок</b> — напр. кожні 7 сторінок для тижнів,</li><li><b>коли зміниться стовпець «…»</b> — напр. <code>miesiac</code>: новий рядок там, де в головній таблиці змінюється місяць. Кілька стовпців (напр. місяць і рік) можна вибрати в наступних списках <b>або стовпець</b>.</li></ul><p>Поле з додаткової таблиці: <code>{Tygodnie.haslo}</code>. Коли в додатковій таблиці забракне рядків, вікно серії покаже це червоним, а перед друком — у списку зауважень.</p>"},{"id":"16.6","tytul":"Серії на розворотах","html":"<p><b>Стежити за лівою й правою сторінкою – вставляти порожню сторінку, коли потрібно</b> робить так, що сторінка, спроєктована як ліва, завжди виходить ліворуч, а права — праворуч. Коли потрібно, застосунок вставляє порожню білу сторінку — напр. після серії, коли дані закінчуються на лівій сторінці. Порожня сторінка враховується в нумерації, як у друкованих книжках. <span class=\"ui\">Перевірити перед друком</span> показує, де стоять порожні сторінки.</p>"},{"id":"16.7","tytul":"Шаблон даних","html":"<p><span class=\"ui\">Завантажити шаблон даних (Excel)</span> дає файл саме з тими стовпцями, яких потребують сторінки, разом із даними, що вже є в таблиці. Аркуш «Instrukcja» описує кожен стовпець. Стовпці зі списком значень, назвами зображень або кадром мають випадні списки. Заповнений файл імпортуйте у вікні Дані.</p>"}]},
  {"nr":"17","tytul":"Вигляд із даних","czesc":"Дані й серії","ikona":"dane","wstep":"Колір, положення, зображення або видимість елемента можуть змінюватися на кожній повтореній сторінці.","sekcje":[{"id":"17.1","tytul":"Частина З даних","html":"<p>Елемент може змінюватися разом із даними на наступних повторених сторінках: колір, місце, розмір, поворот, зображення або видимість. Виділіть елемент і розгорніть частину <b>З даних</b> у властивостях.</p><p>У редакторі елемент виглядає як зразок (позиція 1, колір зразка, завжди видимий). Справжній вигляд кожної сторінки видно в перегляді, на мініатюрах і в PDF.</p><figure><img src=\"img/instrukcja/zakladki.png\" alt=\"Закладка на краю: інше місце й колір на кожній сторінці\" loading=\"lazy\"><figcaption>Закладка на краю: інше місце й колір на кожній сторінці</figcaption></figure>"},{"id":"17.2","tytul":"Колір із поля","html":"<p><b>Колір із поля</b> — стовпець із кольорами, напр. <code>#d1495b</code>, <code>2e86ab</code> або назва англійською (<code>navy</code>). Порожнє або помилкове значення залишає колір зразка. Лінія й фігура без заливки отримують колір обведення. Для заливки градієнтом ви вибираєте, що змінює колір із поля: перший колір, останній колір або весь градієнт у відтінках.</p>"},{"id":"17.3","tytul":"Положення, розмір і поворот із поля","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><b>Зсув по горизонталі з поля</b>, <b>Зсув по вертикалі з поля</b></td><td>Поле з числом — стовпець таблиці або напр. <code>{примірник}</code> (номер повторення).</td></tr><tr><td><b>Значення поля –</b></td><td><b>номер позиції</b> — елемент зсувається на <b>Крок</b> (мм) за кожну позицію; <b>Заново кожні</b> N повертає на початок. Або <b>зсув у мм</b> — число з таблиці напряму.</td></tr><tr><td><b>Ширина з поля</b>, <b>Висота з поля</b></td><td>Значення — це <b>відсоток розміру зразка (100 = без змін)</b> або <b>розмір у мм</b>. <b>Під час зміни розміру на місці лишається</b> — яка сторона або кут стоїть на місці.</td></tr><tr><td><b>Поворот із поля (градуси)</b></td><td>Кут, що додається до повороту зразка, напр. стрілка годинника на кожній сторінці інакше.</td></tr></tbody></table></div><p>Так роблять закладки на краю сторінки — на кожній сторінці нижче — або стовпчики з висотою з таблиці.</p>"},{"id":"17.4","tytul":"Показати елемент","html":"<p><b>Показати елемент</b>: <b>завжди</b> або лише тоді, коли вибране поле <b>не порожнє</b>, <b>порожнє</b> або <b>дорівнює</b> вписаному значенню. Приклад: зірочка біля свята — стовпець <code>swieto</code> і «не порожнє».</p>"},{"id":"17.5","tytul":"Зображення з даних","html":"<p>Вставте будь-яке зображення як зразок — воно задає місце й розмір. У властивостях зображення, у частині <b>Зображення з даних</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><b>Стовпець із назвою файлу</b></td><td>У кожному рядку назва файлу, напр. <code>styczen.jpg</code>. Файли завантажте всі разом у вікні Зображення проєкту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.5\">Вікно «Зображення проєкту»</a>).</td></tr><tr><td><b>Замінене зображення</b></td><td><b>вміщується в рамку (видно повністю)</b> — з вільним місцем з боків або зверху; <b>заповнює рамку (краї обрізано)</b> — без порожніх смуг.</td></tr><tr><td><b>Залишається частина фото</b></td><td>Під час заповнення: центр, верх, низ, ліва або права сторона — напр. «верх», щоб не обрізати голови на портретах.</td></tr><tr><td><b>Кадр зі стовпця</b></td><td><b>той самий на кожній сторінці</b> або стовпець, у якому для кожного фото ви впишете <code>góra</code>, <code>dół</code>, <code>lewa</code>, <code>prawa</code> або <code>środek</code>.</td></tr></tbody></table></div>"},{"id":"17.6","tytul":"Текст різної довжини","html":"<p>Тексти з таблиці мають різну довжину, а макет сторінки має залишатися тим самим. Задайте рамці <b>Фіксовану висоту</b> й увімкніть <b>Зменшувати текст, якщо він не вміщується</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.6\">Текстова рамка</a>). <span class=\"ui\">Перевірити перед друком</span> покаже сторінки, на яких текст усе одно не вміщується.</p><figure><img src=\"img/instrukcja/ramka-tekstu.png\" alt=\"Рамка фіксованої висоти\" loading=\"lazy\"><figcaption>Рамка фіксованої висоти</figcaption></figure>"}]},
  {"nr":"18","tytul":"Приклади","czesc":"Дані й серії","ikona":"dane","wstep":"Готові рецепти крок за кроком.","sekcje":[{"id":"18.1","tytul":"Книжковий календар","html":"<p>Одна сторінка на день, із днем тижня, іменинами й святами в кольорі.</p><ol class=\"kroki\"><li>Новий проєкт A5, розташування <b>Розвороти</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.2\">Новий проєкт</a>).</li><li>У вікні Дані імпортуйте таблицю <b>Dni</b> зі стовпцями <code>dzien</code>, <code>miesiac</code>, <code>dzien_tygodnia</code>, <code>imieniny</code>, <code>swieto</code> — або попросіть її в ШІ (запит нижче).</li><li>На сторінці вставте тексти <code>{dzien}</code>, <code>{dzien_tygodnia}</code> і <code>Іменини: {imieniny}</code> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15.1\">Вставлення поля</a>).</li><li>Клацніть порожнє місце сторінки й у <b>Серія</b> створіть серію з таблицею Dni (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.2\">Нова серія</a>) — з'явиться 365 сторінок.</li><li>Вставте невеликий текст <code>{swieto}</code> червоним кольором і задайте <b>Показати елемент → не порожнє</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.4\">Показати елемент</a>).</li><li>Номер сторінки й нижній колонтитул додайте як шаблон сторінки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.3\">Готові шаблони сторінок</a>).</li><li>Перевірте перегляд і експортуйте PDF (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"19\">Перегляд</a>, <a href=\"#\" data-cel=\"21\">Експорт у PDF і PNG</a>).</li></ol><div class=\"prompt-instrukcji\"><div class=\"prompt-naglowek\"><b>Запит для ШІ: таблиця днів для календаря</b><button type=\"button\" class=\"przycisk\" data-kopiuj-prompt data-ikona=\"kopiuj\">Копіювати</button></div><p class=\"ciche\">Скопіюйте, замініть назву проєкту й вставте в розмову зі ШІ, до якого підключено Makietka (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25\">Робота з ШІ</a>).</p><pre>Korzystając z łącznika Makietka, w projekcie „&lt;nazwa projektu&gt;”:\n1. Przeczytaj opis formatu (narzędzie opis_formatu) i przegląd projektu.\n2. Zrób tabelę danych „Dni 2027” z kolumnami: data, dzien, miesiac, dzien_tygodnia, swieto, kolor (kolor liczby: czarny w dni zwykłe, czerwony #c0392b w niedziele i święta).\n3. Wypełnij ją dla całego roku 2027 (polskie święta państwowe i kościelne w kolumnie swieto).\n4. Zrób stronę-wzór dnia: duża liczba {dzien} z kolorem z pola „kolor”, pod nią {dzien_tygodnia} i {miesiac}, a niżej {swieto}. Ustaw serię „Dni” z tą tabelą.\n5. Pokaż mi, ile stron powstanie, i uruchom kontrolę przed drukiem.</pre></div>"},{"id":"18.2","tytul":"Планер із картинкою місяця","html":"<ol class=\"kroki\"><li>Сторінки днів зробіть, як у календарі (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"18.1\">Книжковий календар</a>).</li><li>Додайте таблицю <b>Miesiące</b> зі стовпцями <code>miesiac</code> і <code>obraz</code> (назви файлів), а фото завантажте у вікні Зображення проєкту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.5\">Вікно «Зображення проєкту»</a>).</li><li>У вікні серії додайте її як додаткову таблицю: <b>Новий рядок → коли зміниться стовпець «miesiac»</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.5\">Додаткові таблиці</a>).</li><li>Вставте зображення на сторінку й у <b>Стовпець із назвою файлу</b> виберіть стовпець <code>obraz</code> таблиці Miesiące (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.5\">Зображення з даних</a>).</li></ol>"},{"id":"18.3","tytul":"Іменні запрошення","html":"<ol class=\"kroki\"><li>Проєкт у форматі запрошення, напр. 148 × 105 мм.</li><li>Таблиця <b>Goście</b> зі стовпцем <code>imie</code> — напр. вставлена з аркуша (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14.3\">Виправлення даних у застосунку</a>).</li><li>Спроєктуйте запрошення й впишіть у тексті <code>Дорога {imie}!</code> або <code>Дорогий {imie}!</code>.</li><li>Серія з таблицею Goście — одне запрошення для кожного гостя.</li><li>PDF <b>Для друкарні</b> з поділом на файли або одним файлом (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21.1\">Вікно експорту</a>).</li></ol>"}]},
  {"nr":"19","tytul":"Перегляд","czesc":"Готове видання","ikona":"pdf","wstep":"Перегляд показує все видання таким, яким воно вийде з друку.","sekcje":[{"id":"19.1","tytul":"Відкриття перегляду","html":"<p>Перегляд показує дані й повторювані сторінки, без допоміжних ліній і без ризику випадково щось змінити. Відкрийте його кнопкою <span class=\"ui\">Перегляд</span> на верхній панелі редактора (<kbd>Shift</kbd>+<kbd>W</kbd>) або з меню <span class=\"ui\">⋯</span> на картці проєкту — тоді перегляд відкривається одразу, без редактора.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-podglad.png\" alt=\"Перегляд на верхній панелі\" loading=\"lazy\"><figcaption>Перегляд на верхній панелі</figcaption></figure><p>Сторінки йдуть по черзі, розвороти стоять поруч. Сторінки серії мають підпис, напр. «3 з 31». Клацання сторінки відкриває її в редакторі; <span class=\"ui\">Редактор</span> або <kbd>Esc</kbd> повертає до редагування.</p><figure><img src=\"img/instrukcja/podglad.png\" alt=\"Перегляд\" loading=\"lazy\"><figcaption>Перегляд</figcaption></figure>"},{"id":"19.2","tytul":"Масштабування","html":"<ul class=\"punkty\"><li><span class=\"ui\">−</span> і <span class=\"ui\">+</span> на панелі; клацання відсотків повертає до 100%, тобто цілого розвороту у вікні.</li><li><kbd>Ctrl</kbd> + коліщатко миші збільшує в місці курсора.</li><li>На телефоні й планшеті: зведення двох пальців; подвійний дотик збільшує або повертає назад.</li></ul>"},{"id":"19.3","tytul":"Презентація","html":"<p><span class=\"ui\">Презентація</span> показує одну сторінку або розворот за раз, на весь екран. Стрілки й пробіл гортають сторінки, <kbd>Esc</kbd> або <span class=\"ui\">×</span> закриває. На телефоні проведення пальцем убік гортає сторінку, униз — закриває презентацію.</p>"},{"id":"19.4","tytul":"3D-макет","html":"<p><span class=\"ui\">3D-макет</span> поруч із <span class=\"ui\">Кольороподіл</span> на панелі перегляду показує проєкт як надруковану річ — наче фото продукту в студії: справжні розміри сторінок, товщина з паперу й кількості сторінок, світло з тінню на столі або стіні. Його можна обертати й гортати, перш ніж він піде до друкарні.</p><p>Кнопка повноекранного режиму в заголовку вікна (поруч із закриттям) розгортає макет на весь екран — зберігаються положення, гортання й вигляд. Та сама кнопка або Esc повертає до звичайного вікна. Це працює і для того, хто дивиться макет за посиланням.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-makieta.png\" alt=\"3D-макет: розгорнута книга у твердій палітурці\" loading=\"lazy\"><figcaption>3D-макет: розгорнута книга у твердій палітурці</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Тип</th><th>Як виглядає</th></tr></thead><tbody><tr><td><b>Книга – м'яка палітурка</b></td><td>Лежить на столі. Обкладинка з розділу обкладинки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.6\">Обкладинка з корінцем</a>): лицьовий бік, корінець і зворот, у розмірі блоку; жорстка, як картон — згинається лише біля корінця. Блок аркуш за аркушем, розгорнуті сторінки вигнуті біля корінця, краї аркушів видно збоку. Без розділу обкладинки обкладинкою є перша сторінка.</td></tr><tr><td><b>Книга – тверда палітурка</b></td><td>Жорсткі картонні кришки й корінець під тонким покривним матеріалом; біля бігу картон плавно спускається до найглибшого місця рівчака, без гострих кутів. Закрита прилягає до блоку; розгорнута — картон обертається в рівчаку бігу й лежить на тій самій висоті, що й закрита. Корінець обкладинки (заокруглений або прямий) завширшки як блок і два картони, стоїть на місці. Ширина бігу й товщина картону — з налаштувань обкладинки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.6\">Обкладинка з корінцем</a>). Форзац: аркуш, складений навпіл, приклеєний до картону лише там, де на ньому лежить; шматок між згином і краєм картону вільний (сталої довжини). Вільний аркуш форзацу склеєний з першою сторінкою блоку на 3 мм біля корінця: розгорнутий, він дугою повертає на картон і трохи піднімає першу сторінку, а перегорнута перша сторінка лягає на форзац і вирівнює його. Блок завжди має ту саму товщину. Ніщо не проходить крізь блок і не заходить під стіл.</td></tr><tr><td><b>Брошура на скріпці</b></td><td>Аркуші, складені навпіл, вкладені один в один і скріплені двома скобами в згині. Без корінця — усі аркуші виходять з одного місця й лише біля згину розходяться на свою висоту; передній край рівно обрізаний. Розгортається майже зовсім пласко. Добирається для обкладинки з кріпленням на скріпку.</td></tr><tr><td><b>Блокнот на спіралі</b></td><td>Кріплення Wire-O: біля кожного отвору два паралельні дроти. Діаметр кільця добирається з товщини блоку, як у виробників (від 1/4″ до 1¼″, крок 3:1 або 2:1); блок, товщий за близько 28 мм, отримує найбільше кільце й примітку під макетом. Блокнот лежить на дроті.</td></tr><tr><td><b>Настінний календар</b></td><td>Висить на стіні; спіраль Wire-O вгорі має посередині розрив із півкруглим вирізом для гачка. Перегорнутий аркуш переходить на зворот.</td></tr><tr><td><b>Настільний календар</b></td><td>Стоїть на столі на підставці з товстого картону; аркуші перегортаються через верх на другий бік.</td></tr><tr><td><b>Окремий аркуш</b></td><td>Листівка, плакат, запрошення — лежить на столі, лицьовий бік і зворот.</td></tr></tbody></table></div><p><b>Тип, дібраний до проєкту.</b> Список <b>Тип</b> показує вгорі лише те, чим проєкт є насправді — зазвичай один тип, щонайбільше два: тверда обкладинка — <b>Книга – тверда палітурка</b>; м'яка — книга або блокнот на спіралі; на скріпці — брошура на скріпці; без обкладинки з 12–14 аркушами або календар — настінний і настільний календар; одна, дві сторінки — аркуш; без обкладинки до 64 сторінок, кратно 4 — блокнот або брошура на скріпці; інші без обкладинки — блокнот або книга. Брошура на скріпці попереджає, коли кількість сторінок не кратна 4 або коли вона затовста для скоб (понад близько 64 сторінки). Решта типів нижче, у групі <b>Не відповідає проєкту</b>: якщо вибрати такий, макет скаже, чого бракує, і запропонує, що зробити (напр. змінити палітурку на тверду, додати обкладинку або почати із шаблону проєкту; бракуючі аркуші покаже білими).</p><div class=\"tabela-instrukcji\"><table><thead><tr><th><b>Складана листівка</b></th><th>З розділу типу листівка (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.11\">Спеціальні розділи: суперобкладинка, листівка, календарі, висічки, вироби</a>): складена обкладинкою догори, розгортається панель за панеллю (рулоном або гармошкою), потім перевертається на зовнішній бік.</th></tr></thead><tbody><tr><td><b>Коробка з висічки</b></td><td>З висічки коробки: спершу плаский аркуш із друком, потім стінки, клапани й кришка складаються в об'ємну форму.</td></tr><tr><td><b>Тристоронній календар</b></td><td>Висить на стіні: основа з шапкою, три календарні блоки й червоне віконце на середньому.</td></tr></tbody></table></div><p>Коли якийсь розділ блоку має інший формат, ніж решта (напр. форзац A4 при блоці A5, без заданого типу), макет не складе його правильно в книгу й скаже про це під зображенням – <span class=\"ui\">Задати тип розділу…</span> відкриває налаштування цього розділу (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>).</p><p>Список <b>Тип</b> показує лише те, що пасує до розділів проєкту: листівка, конверт, коробка й тристоронній календар — коли проєкт має такий розділ; книги, блокнот, календарі й аркуш — коли має звичайні сторінки. Коли проєкт має розділ <b>суперобкладинки</b>, книга у твердій палітурці показує її на обкладинці (лицьовий бік, корінець і зворот із суперобкладинки, клапани загорнуті всередину); перемикач <span class=\"ui\">Показати суперобкладинку</span> ховає її й відкриває обкладинку.</p><p>Тип добирається сам (з обкладинкою — книга; календар — з назви або з 12–14 аркушів; одна сторінка — аркуш); змінити його можна списком <b>Тип</b>. Для книги й блокнота задайте список <b>Положення</b>: <b>Лежить</b> або <b>Стоїть</b> — закрита стоїть на нижньому краї, розгорнута розкривається у «V», як на вітринній полиці (V розкривається разом з обкладинкою, плавно). Коли ви розгортаєте книгу, що стоїть, вигляд сам повертається прямо, щоб обидві сторінки було видно однаково, а після закриття повертається навскіс; якщо ви повернете вигляд пальцем або мишею, він залишиться там, де ви його поставили. Вибір запам'ятовується для проєкту.</p><p>На телефоні й планшеті макет тримає в пам'яті менше сторінок водночас і малює їх у меншій роздільності (без полиску плівки й лаку у світлі) – телефон з малою пам'яттю закривав вкладку браузера. Якщо вкладка все ж закриється з відкритим макетом, наступного разу макет працюватиме в <b>ощадному режимі</b> й повідомить про це над переглядом.</p><p>Формат блоку — це формат більшості сторінок проєкту. Розділи типу форзац (передній або задній) не є частиною блоку: у книзі передній форзац лежить на внутрішньому боці передньої обкладинки і як вільний аркуш перед сторінкою 1, задній — навпаки, як після палітурних робіт (аркуш A4 горизонтально при книзі A5 ділиться на дві половини). Тверда палітурка без форзаців у проєкті отримує чистий форзац. Інша сторінка, удвічі ширша за блок — напр. розворот на одному аркуші, — теж ділиться на дві сторінки.</p><ul class=\"punkty\"><li><b>Обертання</b> — перетягніть мишею або пальцем. Світло рухається разом із виглядом, а макет не можна повернути під стіл чи за стіну.</li><li><b>Наближення</b> — коліщатко миші, два пальці або <span class=\"ui\">−</span> і <span class=\"ui\">+</span>; <span class=\"ui\">Вигляд</span> повертає до вигляду спереду. Після наближення сторінки завантажуються ще раз у вищій роздільності — зблизька вони чіткі.</li><li><b>Гортання</b> — стрілки під макетом, клавіші <kbd>←</kbd> <kbd>→</kbd> або дотик до правої чи лівої половини зображення. Унизу видно, що розгорнуто, напр. «Сторінки 2–3» або «Аркуш 3 з 13».</li><li><span class=\"ui\">Завантажити зображення макета</span> зберігає зображення PNG у тому самому кадрі, що й на екрані — напр. для комерційної пропозиції або допису в мережі. Розмір вибираєте в частині <b>Експорт</b> (нижче). У темній темі тло студії темне.</li></ul><p>Людина з посиланням на перегляд (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"23.1\">Створення посилання</a>) теж бачить макет — в одному варіанті, без налаштувань. Посилання саме стежить за змінами: після збереження ракурсу покаже новий варіант, а посилання, створене раніше, отримає макет під час найближчого відкриття проєкту.</p><p class=\"ramka-instrukcji uwaga\"><b>Увага.</b> Макет малюється відеокартою. Пристрій без 3D-графіки (старий телефон, заблокована відеокарта, напр. Chrome на старішому Mac) показує <b>спрощений макет</b>: та сама книга, блокнот чи календар, з тими самими сторінками, обертанням пальцем і мишею та гортанням, лише без падаючих тіней, полиску й відблисків (над макетом є про це коротка примітка). Зображення макета (PNG) і збережені ракурси працюють так само. Знімок макета можна зберегти лише завантаженням — <span class=\"ui\">Завантажити зображення макета</span> (PNG), також у макеті за посиланням.</p><h4>Готові ракурси</h4><p>Над макетом є ряд плиток — один дотик задає камеру, положення й аркуші: <b>Передня сторона</b>, <b>¾ (класичний)</b>, <b>Згори (пласко)</b>, <b>Корінець</b>, <b>Стояча</b>, <b>Розворот згори</b>, <b>Віяло аркушів</b>, <b>Стос примірників</b>, <b>Передня і задня сторони</b> (два примірники поруч, другий перевернутий) та <b>На стіні</b> для настінних календарів (тинькована стіна, світло з вікна). Видно лише ракурси, що пасують до типу (настільний календар не має стосу й вигляду згори). Коробка в ракурсах спереду, ¾ і стосу складена, а згори – пласка. Вибравши ракурс, ви можете далі обертати й наближати.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-makieta-ujecia.png\" alt=\"Готові ракурси: віяло аркушів на дерев'яній стільниці\" loading=\"lazy\"><figcaption>Готові ракурси: віяло аркушів на дерев'яній стільниці</figcaption></figure><figure class=\"kadr\"><img src=\"img/instrukcja/k-makieta-stos.png\" alt=\"Стос примірників на дереві\" loading=\"lazy\"><figcaption>Стос примірників на дереві</figcaption></figure><h4>Ракурс і світло</h4><p>Згорнута частина <b>Ракурс і світло</b> під макетом збирає всі налаштування сцени (на телефоні так само):</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Група</th><th>Що налаштуєте</th></tr></thead><tbody><tr><td><b>Камера</b></td><td>обертання, нахил, відстань і <b>об'єктив</b> — малий кут — це телеоб'єктив (пласко, без спотворень), великий — ширококутний із сильною перспективою</td></tr><tr><td><b>Книжка</b></td><td>кут розгортання (180° — пласко), прочинена обкладинка, віяло аркушів і вибір розвороту зі списку</td></tr><tr><td><b>Світло</b></td><td>напрямок (зліва, справа, згори, вікно — низько збоку), відтінок (нейтральний, теплий, холодний), м'якість і сила тіні</td></tr><tr><td><b>Поверхня й тло</b></td><td>студійний градієнт, однотонний колір, дерево, папір, бетон, мармур, тканина, тинк або прозоре; колір тла (для фактур змінює їхній відтінок)</td></tr><tr><td><b>Примірники</b></td><td>один, два або три поруч, стос із 3 або 5, передня і задня сторони</td></tr><tr><td><b>Матеріали</b></td><td>оздоблення обкладинки (як у проєкті, мат, глянець, soft-touch), білий або кремовий папір, колір спіралі й підставки; <b>Золочення й лак із проєкту у світлі</b> — елементи з оздобленням друку (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.2\">Оздоблення друку: лак, золочення, тиснення, біла фарба</a>) блищать, як фольга й лак, коли ви обертаєте макет</td></tr></tbody></table></div><p><span class=\"ui\">Відновити типові</span> повертає початкові налаштування. Світло й тло запам'ятовуються для проєкту на цьому пристрої.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-makieta-swiatlo.png\" alt=\"Ракурс і світло: камера, книжка, світло, тло, примірники, матеріали\" loading=\"lazy\"><figcaption>Ракурс і світло: камера, книжка, світло, тло, примірники, матеріали</figcaption></figure><h4>Експорт і анімація</h4><p>У частині <b>Експорт</b> ви вибираєте розмір зображення: <b>Інтернет</b> (довша сторона 1600 px), <b>Друк</b> (4000 px), <b>Instagram</b> (квадрат 1080 × 1080) або <b>Власний</b>, а також <b>Прозоре тло</b> — залишається сам предмет із тінню, готовий для вставлення на сайт або в презентацію.</p><p><span class=\"ui\">Записати анімацію</span> робить короткий ролик: <b>Обертання навколо</b> або <b>Гортання</b> (від поточної сторінки), як <b>відео</b> (MP4, якщо браузер це вміє, інакше WebM) або <b>GIF</b>. Смуга поступу показує кадри; <span class=\"ui\">Скасувати</span> перериває запис.</p><h4>Збережені ракурси</h4><p>У частині <b>Збережені ракурси</b> введіть назву й торкніться <span class=\"ui\">Зберегти ракурс</span> — тип, камера, світло, тло, примірники й положення аркушів зберігаються в проєкті (також на інших пристроях і в людей, з якими ви працюєте; збереження можна скасувати). Дотик до назви в списку відновлює ракурс, кошик його видаляє.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-makieta-specjalne.png\" alt=\"Макети спеціальних розділів: листівка під час розгортання й складена коробка\" loading=\"lazy\"><figcaption>Макети спеціальних розділів: листівка під час розгортання й складена коробка</figcaption></figure><figure class=\"kadr\"><img src=\"img/instrukcja/k-makieta-kalendarz.png\" alt=\"3D-макет: настінний календар\" loading=\"lazy\"><figcaption>3D-макет: настінний календар</figcaption></figure><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> макет показує форму й товщину видання з паперу й кількості сторінок (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.6\">Обкладинка з корінцем</a>) — це перегляд, а не пробний друк. Кольори перевірите в <span class=\"ui\">Кольороподіл</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.6\">Перегляд кольороподілу</a>).</p>"},{"id":"19.5","tytul":"Живий перегляд","html":"<p>Відкритий перегляд оновлюється сам, коли проєкт змінюється деінде — на іншому пристрої, у співавтора або через ШІ. Він залишається в тому самому місці й масштабі; перемальовуються лише змінені сторінки.</p>"}]},
  {"nr":"20","tytul":"Перевірка перед друком","czesc":"Готове видання","ikona":"pdf","wstep":"Список місць, які варто перевірити, перш ніж надіслати файл до друкарні.","sekcje":[{"id":"20.1","tytul":"Список зауважень","html":"<p><span class=\"ui\">⋯</span> → <span class=\"ui\">Перевірити перед друком</span> переглядає весь проєкт — також кожну повторювану сторінку.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-kontrola.png\" alt=\"Перевірити перед друком у меню ⋯\" loading=\"lazy\"><figcaption>Перевірити перед друком у меню ⋯</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Зауваження</th><th>Що означає</th></tr></thead><tbody><tr><td><b>Текст не вміщується в рамку</b></td><td>На вказаних сторінках текст виходить за рамку сталої висоти — напр. через довше значення з таблиці.</td></tr><tr><td><b>Поле без значення</b></td><td>Поле з помилкою в назві або з видаленого стовпця.</td></tr><tr><td><b>Немає файлу зображення</b></td><td>У таблиці є назва зображення, яке не завантажено.</td></tr><tr><td><b>Повтори</b></td><td>Те саме значення в стовпці з <b>≠</b>, з номерами сторінок.</td></tr><tr><td><b>Значення поза списком</b></td><td>Значення поза списком стовпця з <b>☰</b>, з номерами рядків.</td></tr><tr><td><b>Немає даних</b></td><td>Додатковій таблиці забракло рядків до кінця серії.</td></tr><tr><td><b>Сторінки серії в розворотах</b></td><td>Де стоять порожні сторінки або з якої сторінки блок опиняється на протилежному боці.</td></tr><tr><td><b>Таблиця виходить за сторінку</b></td><td>Рядки виросли разом із вмістом, і таблиця вийшла за аркуш.</td></tr><tr><td><b>Неповний зошит</b></td><td>Розділу бракує сторінок до повного зошита (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.7\">Зошити</a>); при кріпленні на скріпку — кількість сторінок не ділиться на 4.</td></tr><tr><td><b>Покриття фарбою</b></td><td>Колір елемента після перерахунку профілем друкарні дає понад 300% фарби — після відкриття перегляду кольороподілу з профілем або експорту PDF/X-4 (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.6\">Перегляд кольороподілу</a>).</td></tr><tr><td><b>Елемент на полі або за вильотом</b></td><td>Як у списку попереджень у редакторі (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.2\">Попередження</a>).</td></tr></tbody></table></div><p><span class=\"ui\">Показати</span> біля зауваження відкриває перегляд на першій сторінці, якої воно стосується, з виділеним аркушем. <span class=\"ui\">Відкрити зразок</span> відкриває в редакторі сторінку-зразок. Зауваження не блокують експорт — той самий список є внизу вікна експорту PDF.</p><figure><img src=\"img/instrukcja/kontrola.png\" alt=\"Список зауважень\" loading=\"lazy\"><figcaption>Список зауважень</figcaption></figure>"}]},
  {"nr":"21","tytul":"Експорт у PDF і PNG","czesc":"Готове видання","ikona":"pdf","wstep":"Файл для друкарні, для перегляду на екрані або для друку вдома. Файл може також створити ШІ-асистент (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.5\">Файл PDF через ШІ</a>).","sekcje":[{"id":"21.1","tytul":"Вікно експорту","html":"<p>Виберіть <span class=\"ui\">⋯</span> → <span class=\"ui\">Експортувати в PDF…</span>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-pdf.png\" alt=\"Експортувати в PDF у меню ⋯\" loading=\"lazy\"><figcaption>Експортувати в PDF у меню ⋯</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><b>Тип файлу</b></td><td><b>Векторний – чіткий текст і фігури</b>: текст із вбудованими шрифтами, чіткий за будь-якого збільшення, його можна виділити. <b>Зображення сторінок – сторінка як фото</b>: кожна сторінка — одне зображення; виглядає скрізь однаково, але файл більший.</td></tr><tr><td><b>Діапазон</b></td><td><b>Увесь проєкт</b>, <b>Вибрані розділи</b> (позначте один або кілька; біля кожного кількість сторінок) або <b>Вибрані сторінки</b> – номери як у Word: <code>1-5, 8, 11-</code> (кома або крапка з комою між частинами, <code>11-</code> – від 11 до кінця, <code>-3</code> – від початку до 3). Номери рахуються в усьому друці, з повторами серій. Підсумок унизу одразу каже, скільки вийде сторінок, і підказує, коли щось не вдається прочитати.</td></tr><tr><td><b>Призначення</b></td><td><b>Для друкарні – з вильотом і мітками різу</b> або <b>Для перегляду – точно за форматом</b>. Мітки різу отримують розділи, у яких їх увімкнено (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>).</td></tr><tr><td><b>Розташування аркушів</b></td><td><b>Звичайні сторінки</b> або сторінки, розкладені на аркушах для самостійного друку (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21.6\">Брошура й кілька сторінок на аркуші</a>).</td></tr><tr><td><b>Якість</b></td><td>Роздільність фото: 300 dpi — стандарт для друку, 150 dpi — малий файл для проби, 600 dpi — дуже чітко.</td></tr></tbody></table></div><p>Унизу вікна є список <b>До перевірки перед друком</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>). <span class=\"ui\">Експортувати</span> зберігає файл; довгий експорт можна перервати кнопкою <span class=\"ui\">Скасувати</span> на картці поступу.</p><p>Великий файл (від 150 сторінок, один файл) створює сервер Makietka, а не ваш пристрій — картка поступу показує <b>Експорт у PDF – файл створює сервер Makietka</b>, а готовий файл завантажується сам. Він виглядає так само, бо сервер використовує той самий код. Виняток: PDF/X із власним профілем ICC (файл профілю є лише на вашому пристрої) завжди створює пристрій. Без інтернету або за проблем із сервером файл створює пристрій, як раніше.</p><figure><img src=\"img/instrukcja/pdf.png\" alt=\"Вікно експорту\" loading=\"lazy\"><figcaption>Вікно експорту</figcaption></figure>"},{"id":"21.2","tytul":"Додатково","html":"<p>Частина <b>Додатково</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><b>Перетворити текст на криві (без шрифтів у файлі)</b></td><td>Літери стають фігурами. Цього вимагають деякі друкарні; текст потім не можна виділити.</td></tr><tr><td><b>Кольори тексту й фігур у CMYK (чорний як чиста чорна)</b></td><td>Кольори записані чотирма друкарськими фарбами; чорний текст друкується лише чорною фарбою, тому він чіткий.</td></tr><tr><td><b>Стандарт для друкарні</b></td><td><b>Без стандарту – звичайний PDF</b>, <b>PDF/X-4 – крейдований папір (FOGRA39)</b>, <b>PDF/X-4 – некрейдований папір (FOGRA47)</b> або <b>PDF/X-4 – профіль від друкарні (файл .icc)</b> — <span class=\"ui\">Вибрати файл профілю…</span>.</td></tr><tr><td><b>Фото теж у CMYK (більший файл)</b></td><td>Для PDF/X-4: фото перераховані на друкарські фарби тим самим профілем.</td></tr><tr><td><b>Поділ на файли</b></td><td><b>Один файл</b>, <b>Окремий файл для кожного розділу</b> або <b>Частини по стільки сторінок</b> (<b>Сторінок у частині</b>). Кілька файлів ви отримуєте в архіві ZIP.</td></tr><tr><td><b>Додати файли шрифтів, використаних у проєкті</b></td><td>Завантажується ZIP із файлом PDF і текою <code>czcionki</code>.</td></tr><tr><td><b>PDF для читання на екрані: закладки й клікабельні посилання</b></td><td>Закладки й посилання для тих, хто читає на екрані (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21.7\">PDF для читання на екрані</a>). Типово увімкнено; недоступно для PDF/X-4 і розташування аркушів.</td></tr><tr><td><b>Оздоблення</b></td><td>Коли проєкт їх має: <b>Окремі форми в тому самому PDF-файлі</b>, <b>Окремий PDF-файл для кожного оздоблення</b> або <b>Пропустити оздоблення</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.4\">Оздоблення у файлі PDF</a>).</td></tr></tbody></table></div>"},{"id":"21.3","tytul":"Як вибрати налаштування для друкарні","html":"<p>Запитайте друкарню, чого вона вимагає:</p><ul class=\"punkty\"><li>каже «PDF/X-4» — виберіть цей стандарт і папір, на якому друкуватиме,</li><li>каже «все в CMYK» — позначте також обидва поля CMYK,</li><li>каже «без шрифтів» або «криві» — позначте <b>Перетворити текст на криві</b>,</li><li>нічого не вимагає — <b>Векторний</b>, <b>Для друкарні</b>, 300 dpi.</li></ul><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> Файл із проєкту в кольорах екрана в друці виглядає трохи інакше. Найнадійніше замовити пробний друк.</p>"},{"id":"21.4","tytul":"Що не вдається зберегти векторно","html":"<p>Елемент із тінню, елемент, обрізаний маскою, і малюнок SVG із фільтром потрапляють у файл як зображення цього одного елемента — решта сторінки залишається векторною. Текст у шрифті, який не вдається вбудувати, потрапляє у файл як криві. Після експорту застосунок повідомить, якщо таке сталося.</p>"},{"id":"21.5","tytul":"Сторінка як PNG","html":"<p><span class=\"ui\">⋯</span> → <span class=\"ui\">Завантажити поточну сторінку як PNG</span> зберігає зображення відкритої сторінки в 300 dpi, з вильотом — напр. щоб показати комусь у повідомленні.</p>"},{"id":"21.6","tytul":"Брошура й кілька сторінок на аркуші","html":"<p><b>Розташування аркушів</b> у вікні експорту кладе сторінки на аркуші — для друку на звичайному принтері або в малій друкарні:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Розташування</th><th>Що робить</th></tr></thead><tbody><tr><td><b>Брошура для складання (скріпка)</b></td><td>Сторінки парами, так щоб після двостороннього друку й складання аркушів навпіл вийшов зошит. Кількість сторінок доповнюється порожніми до кратної 4.</td></tr><tr><td><b>Брошура із зошитів</b></td><td>Те саме, але окремо для кожного зошита по <b>Зошит (сторінок)</b> — 4, 8, 16 або 32 (типово як у налаштуваннях розділу, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.7\">Зошити</a>). Зошити зшивають або склеюють разом.</td></tr><tr><td><b>2 сторінки на аркуші</b>, <b>4 сторінки на аркуші</b></td><td>Послідовні сторінки поруч — напр. листівки A6 по чотири на A4.</td></tr></tbody></table></div><p><b>Аркуш</b>: <b>За розміром сторінок</b> (дві сторінки A5 → аркуш 296 × 210 мм) або <b>A4</b> / <b>A3</b> — сторінки стоять посередині й зменшуються, якщо не вміщуються. <b>Компенсація зсуву (мм)</b>: у товщій брошурі середні аркуші після складання виступають; сторінки на них зсуваються на частину цього значення в бік корінця (напр. 0,5–1 мм при 40 сторінках).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-pdf-arkusze.png\" alt=\"Брошура: план аркушів у вікні експорту\" loading=\"lazy\"><figcaption>Брошура: план аркушів у вікні експорту</figcaption></figure><p>При <b>Для друкарні</b> аркуші мають мітки різу, а брошура — пунктирні мітки фальцювання. Сторінки на аркушах стоять точно за форматом, без вильоту.</p><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> Брошуру на домашньому принтері простіше надрукувати через <span class=\"ui\">Друкувати вдома…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21.8\">Друк удома</a>).</p>"},{"id":"21.7","tytul":"PDF для читання на екрані","html":"<p>Звичайний файл PDF одразу має навігацію для тих, хто читає на екрані:</p><ul class=\"punkty\"><li><b>закладки</b> на бічній панелі програми для читання — розділи проєкту, а під ними заголовки (стилі заголовків книги, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13\">Книжка: зміст, колонтитул, виноски, перехресні посилання, покажчик</a>),</li><li><b>клікабельний зміст</b> — рядок змісту веде на сторінку,</li><li><b>посилання</b> «с. 12» ведуть на цю сторінку,</li><li><b>посилання елемента</b> — на панелі елемента, у частині <b>Інші</b>, поле <b>Посилання в PDF (адреса сайту, e-mail)</b>: клацання елемента в PDF відкриває адресу; QR-код з адресою сайту клікабельний сам собою.</li></ul><p>Посилання є у векторному файлі; закладки — в обох типах файлу. У PDF/X-4 для друкарні навігації немає.</p>"},{"id":"21.8","tytul":"Друк удома","html":"<p>Друк на звичайному принтері: <span class=\"ui\">⋯</span> → <span class=\"ui\">Друкувати вдома…</span> або <kbd>Ctrl</kbd>+<kbd>P</kbd> у редакторі й перегляді. Вікно саме розкладає сторінки на аркуші — не друкуйте проєкт із меню браузера.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-druk.png\" alt=\"Вікно «Друкувати вдома»\" loading=\"lazy\"><figcaption>Вікно «Друкувати вдома»</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Що означає</th></tr></thead><tbody><tr><td><b>Що друкувати</b></td><td><b>Звичайний друк</b> (сторінка на аркуші), <b>Брошура для складання</b> (аркуші складаються навпіл і зшиваються посередині – порядок сторінок вибудовується сам), <b>2</b> або <b>4 сторінки на аркуші</b>.</td></tr><tr><td><b>Папір</b></td><td>A4, A3 або Letter – аркуш повертається сам.</td></tr><tr><td><b>Розмір сторінок</b></td><td><b>Фактичний</b> (сторінки зменшуються, лише коли не вміщуються) або <b>Припасувати до аркуша</b>.</td></tr><tr><td><b>Сторінки</b></td><td>Усі, <b>вибрані розділи</b> (один або кілька), <b>вибрані сторінки</b> (як у Word: <code>1-5, 8, 11-</code>) або лише поточна.</td></tr><tr><td><b>У відтінках сірого</b></td><td>Чорно-білий друк.</td></tr><tr><td><b>Мітки різу й фальцювання</b></td><td>Для брошури, яку ви обріжете після зшивання.</td></tr></tbody></table></div><p>Під налаштуваннями видно, як сторінки розкладуться на аркушах. <span class=\"ui\">Друкувати</span> відкриває вікно друку з готовим файлом (на телефоні файл відкривається в новій вкладці — виберіть там <b>Поділитися → Друкувати</b>), а <span class=\"ui\">Завантажити PDF для друку</span> зберігає той самий файл.</p><p>Вікно друку браузера може по-своєму змінити масштаб, додати поля або колонтитул із датою й адресою. Makietka друкує готовий файл PDF, а не саму сторінку, тож колонтитулів у ньому немає; масштаб 100% і двосторонній друк записані у файлі. Не кожен браузер слухається цих налаштувань, тому вікно показує, що перевірити у вікні принтера:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>У вікні принтера</th><th>Задайте</th></tr></thead><tbody><tr><td><b>Масштаб</b></td><td><b>100% / Фактичний розмір</b> — не «Припасувати» і не «Зменшити до сторінки».</td></tr><tr><td><b>Поля</b></td><td>Типові. Файл уже має поля, а сторінки розкладені на аркуші.</td></tr><tr><td><b>Колонтитули</b></td><td>Вимкнено. Якщо в попередньому перегляді видно дату й адресу, зніміть позначку з цього параметра.</td></tr></tbody></table></div><p>Принтер не друкує кілька міліметрів біля краю аркуша. Тому сторінка розміром з аркуш трохи зменшена, щоб залишилося 5 мм поля; вікно пише, на скільки.</p><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> Найнадійніший друк: <span class=\"ui\">Завантажити PDF для друку</span> і друкуйте з програми для файлів PDF. Першого разу надрукуйте <span class=\"ui\">пробну сторінку</span>: лінійка 100 мм має мати рівно 100 мм, а рамки 3, 5 і 10 мм показують, скільки біля краю залишає ваш принтер.</p><ol class=\"kroki\"><li>Спершу надрукуйте один аркуш на пробу.</li><li>Перевірте у вікні принтера масштаб <b>Фактичний розмір / 100%</b>.</li><li>Брошуру друкуйте двосторонньо, <b>перевертання по короткому краю</b>; без двостороннього друку — спершу непарні сторінки, потім вкладіть стос назад і надрукуйте парні.</li><li>Складіть аркуші навпіл (перший зверху) і зшийте в згині.</li></ol>"}]},
  {"nr":"22","tytul":"Кольори проєкту, фарби й оздоблення","czesc":"Готове видання","ikona":"pdf","sekcje":[{"id":"22.1","tytul":"Додаткові кольори","html":"<p>Друк — це не лише чотири фарби CMYK. Makietka знає додаткові кольори (напр. Pantone), оздоблення — лак, золочення, тиснення, білу фарбу — і друк лише чорною фарбою або чорною з одним кольором. Усе потрапляє у файл PDF так, як очікує друкарня: кожна фарба на окремій формі.</p><p>Додатковий колір — це окрема готова фарба — точно того відтінку, який вам потрібен (напр. колір логотипа). Найпростіше додати його біля елемента:</p><ol class=\"kroki\"><li>Виділіть елемент і відкрийте його колір (напр. <b>Колір заливки</b>).</li><li>Унизу вибору кольору: <span class=\"ui\">Зробити цей колір додатковим…</span>.</li><li>Введіть назву фарби точно як у друкарні або у віяловому каталозі, напр. «PANTONE 186 C», і <span class=\"ui\">Додати</span>.</li></ol><p>Те саме зробите у Властивостях → <b>Оздоблення друку</b> → <b>Спеціальна фарба</b> → <b>Нова з поточного кольору…</b>. Доданий колір ви потім вибираєте в будь-якому полі кольору — заливка, обведення, текст, фрагмент тексту — у частині <b>Додаткові кольори</b>, разом із <b>Відтінком</b> (напр. 40%).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kolor-dodatkowy.png\" alt=\"Додатковий колір у виборі кольору\" loading=\"lazy\"><figcaption>Додатковий колір у виборі кольору</figcaption></figure><p>Список додаткових кольорів є в <span class=\"ui\">⋯</span> → <span class=\"ui\">Кольори проєкту…</span>: там можна змінити назву, ввести <b>C</b>, <b>M</b>, <b>Y</b>, <b>K</b> (це лише перегляд на екрані — друкарня використає свою фарбу) або видалити колір. Зміна CMYK додаткового кольору змінює всі елементи цього кольору. Видалення кольору залишає елементи у звичайному кольорі CMYK.</p>"},{"id":"22.2","tytul":"Оздоблення друку: лак, золочення, тиснення, біла фарба","html":"<p>Оздоблення задаєте біля елемента — нічого не треба додавати заздалегідь. Виділіть елемент → Властивості → <b>Оздоблення друку</b> і торкніться ефекту:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ефект</th><th>Що це</th><th>Форма в PDF</th></tr></thead><tbody><tr><td><b>Лак</b></td><td>Глянцевий лак лише в цьому місці, напр. назва на матовій обкладинці.</td><td>Spot_UV</td></tr><tr><td><b>Золочення</b></td><td>Металізована фольга; <b>Колір фольги</b>: золото, срібло або мідь.</td><td>Foil_Gold, Foil_Silver, Foil_Copper</td></tr><tr><td><b>Тиснення</b></td><td>Опуклий візерунок, видавлений у папері.</td><td>Emboss</td></tr><tr><td><b>Конгрев</b></td><td>Увігнутий візерунок, втиснутий у папір.</td><td>Debossing</td></tr><tr><td><b>Білий</b></td><td>Біла фарба під низом — на кольоровому, крафтовому або прозорому матеріалі.</td><td>White</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-uszlachetnienie.png\" alt=\"Оздоблення друку на панелі елемента\" loading=\"lazy\"><figcaption>Оздоблення друку на панелі елемента</figcaption></figure><p>Над плитками ви вибираєте, <b>як</b> додати ефект:</p><ul class=\"punkty\"><li><b>Колір + ефект</b> — елемент друкується у своїх кольорах, а ефект іде на його копію точно над ним. Так зробите лак на фото або кольоровий напис із золоченням. Для фото це типове налаштування.</li><li><b>Лише ефект</b> — елемент не друкується жодною фарбою, він лише ефект, напр. напис самим золотом. Для фігур і тексту це типове налаштування.</li></ul><p>У тій самій частині є <b>Спеціальна фарба</b> — заливка елемента додатковим кольором (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.1\">Додаткові кольори</a>).</p><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> Оздоблення на дуже дрібному тексті (менше 6 pt) і тонких лініях (менше 0,3 мм) може не відтворитися. <b>Перевірити перед друком</b> про це нагадає (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>).</p><p><b>Вирізанки й складанки — лінії висічки.</b> У тих самих плитках є й технічні лінії. Елемент (фігура, лінія, замкнена фігура пером, ціла група) перестає бути малюнком і стає лінією для палітурні або плотера:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Плитка</th><th>Що це</th><th>У редакторі</th><th>Форма в PDF</th></tr></thead><tbody><tr><td><b>Різання</b></td><td>Контур для вирізання ножем або плотером. Група — кожна її фігура.</td><td>червона лінія</td><td>CutContour</td></tr><tr><td><b>Біг</b></td><td>Лінія згину — продавлюється, щоб картон зігнувся рівно.</td><td>синя штрихова</td><td>Crease</td></tr><tr><td><b>Перфорація</b></td><td>Лінія відривання (купон, квиток).</td><td>помаранчева пунктирна</td><td>Perforation</td></tr><tr><td><b>Клей</b></td><td>Ділянка, на яку йде клей (клапан коробки, конверта).</td><td>зелена ділянка</td><td>Glue</td></tr></tbody></table></div><p>Лінії завжди видно на сторінці, але вони не друкуються фарбою — у векторному PDF потрапляють на окремі форми (CutContour розпізнає більшість плотерів print & cut). Меню <b>⋯</b> → <span class=\"ui\">Файл для плотера (SVG, поточна сторінка)</span> завантажує лише лінії поточної сторінки в міліметрах — для Cricut, Silhouette або плотера в друкарні (колір лінії каже, що робити). <b>Перевірити перед друком</b> стежить, чи можна вирізати й скласти: різання з незамкненої лінії, біг або клей без лінії різання, біг або клей поза вирізаним шматком. Готові висічки конверта, папки й коробки з 3D-макетом дає розділ типу <b>Висічка</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.4\">Налаштування розділу</a>).</p>"},{"id":"22.3","tytul":"Вигляд оздоблень","html":"<p>У редакторі й перегляді оздоблення видно як ефект: полиск лаку, металізовану фольгу, тінь тиснення, білу фарбу на шаховому тлі. Меню вигляду → <b>Показувати оздоблення</b> вимикає ефект (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.6\">Правий нижній кут і меню вигляду</a>).</p>"},{"id":"22.4","tytul":"Оздоблення у файлі PDF","html":"<p>У векторному файлі кожне оздоблення — це окрема форма з <b>накладанням</b> — вона не вибиває фарбу під собою. У вікні експорту, у частині <b>Додатково</b>, виберіть <b>Оздоблення</b>:</p><ul class=\"punkty\"><li><b>Окремі форми в тому самому PDF-файлі</b> — найпоширеніше,</li><li><b>Окремий PDF-файл для кожного оздоблення</b> — основний файл без оздоблень і окремий файл кожної форми, в одному ZIP,</li><li><b>Пропустити оздоблення</b>.</li></ul><p>Файл із зображень сторінок не має окремих форм — виберіть векторний файл.</p>"},{"id":"22.5","tytul":"Кольори проєкту й друк кольорів — для всього проєкту або для розділу","html":"<p><span class=\"ui\">⋯</span> → <span class=\"ui\">Кольори проєкту…</span> збирає в одному вікні все про кольори. Угорі, у полі <b>Стосується</b>, ви вибираєте <b>Увесь проєкт</b> або один розділ — напр. обкладинка в повному кольорі, а блок чорно-білий.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kolory-druku.png\" alt=\"Вікно «Кольори проєкту» для розділу «Блок»\" loading=\"lazy\"><figcaption>Вікно «Кольори проєкту» для розділу «Блок»</figcaption></figure><p><b>Кольори в проєкті</b> (або <b>в розділі</b>) — це кольори, якими ви користуєтеся, з кількістю використань. Торкніться кольору й виберіть новий — він зміниться всюди в цьому діапазоні: для всього проєкту на сторінках, у шаблонах сторінок і в стилях, для розділу лише на його сторінках. Зміну скасуєте звичайним <span class=\"ui\">Скасувати</span>.</p><p><b>Друк кольорів</b> визначає, якими фарбами піде друк:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Режим</th><th>Коли</th></tr></thead><tbody><tr><td><b>Повноколірний</b></td><td>Звичайний друк CMYK (типово).</td></tr><tr><td><b>Відтінки сірого</b></td><td>Друк однією чорною фарбою — кольори й фото йдуть відтінками чорного.</td></tr><tr><td><b>Ч/б + 1 колір</b></td><td>Чорна й один додатковий колір, напр. календар із червоними неділями. <b>Додатковий колір режиму</b> вибираєте нижче.</td></tr><tr><td><b>Як у проєкті</b></td><td>Лише для розділу: розділ друкується так само, як увесь проєкт (типово).</td></tr></tbody></table></div><p>У PDF кожна сторінка йде в режимі свого розділу. У виборі кольору на сторінці такого розділу залишаються відтінки чорного й колір режиму, а кольори розділу видно окремо — <b>У цьому розділі</b>. Кольори поза режимом вікно покаже — <span class=\"ui\">Замінити на найближчі дозволені</span> замінить їх на чорний або колір режиму. Те саме зробить кнопка в <b>Перевірити перед друком</b>.</p><p>Унизу вікна, у частині <b>Оздоблення друку</b>, видно, які ефекти є в проєкті й на скількох елементах.</p><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> Розширений CMYK (CMYK із додатковими фарбами, напр. помаранчевою, зеленою й фіолетовою) друкарня робить сама з вашого файлу — окрема палітра не потрібна.</p>"},{"id":"22.6","tytul":"Перегляд кольороподілу","html":"<p>У перегляді проєкту <span class=\"ui\">Кольороподіл</span> показує сторінку, розкладену на форми, якими її надрукує друкарня: <b>Блакитний</b>, <b>Пурпуровий</b>, <b>Жовтий</b>, <b>Чорний</b>, додаткові кольори й оздоблення.</p><figure><img src=\"img/instrukcja/separacje.png\" alt=\"Перегляд кольороподілу: додатковий колір і УФ-лак із накладанням\" loading=\"lazy\"><figcaption>Перегляд кольороподілу: додатковий колір і УФ-лак із накладанням</figcaption></figure><ol class=\"kroki\"><li>Стрілками над зображенням переходите між сторінками.</li><li>Зніміть позначку з форми, щоб побачити сторінку без неї; залиште одну й позначте <b>Одна форма в сірому</b> — побачите саму фарбу цієї форми (чорне = 100%).</li><li><b>Показати друк оздоблень</b> — оздоблення як заштрихований шар над фарбою (друкуються з накладанням, не вибивають фарбу під собою).</li><li><b>Позначити покриття фарбою понад</b> <b>Ліміт покриття (%)</b> — місця, де сума фарб перевищує ліміт (зазвичай 300% для крейдованого паперу), стають червоними. Унизу — найбільше покриття на сторінці.</li></ol><p><b>Перетворення в CMYK</b>: <b>Просте</b> — так, як векторний файл у CMYK без профілю (чорне й сірі лише чорною фарбою; не перевищує 300%); <b>Крейдований папір (FOGRA39)</b> або <b>Некрейдований папір (FOGRA47)</b> — так, як перерахує профіль друкарні. Після перерахунку профілем <b>Перевірити перед друком</b> вкаже також кольори елементів із покриттям фарбою понад 300% (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>).</p>"}]},
  {"nr":"23","tytul":"Поширення за посиланням","czesc":"Готове видання","ikona":"pdf","wstep":"Посилання на перегляд для людей без облікового запису — клієнта, родини, друкарні.","sekcje":[{"id":"23.1","tytul":"Створення посилання","html":"<p>Людина з посиланням бачить сторінки так, як у перегляді; вона не може нічого змінити й не бачить інших ваших проєктів. Вона також може відкрити <span class=\"ui\">3D-макет</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"19.4\">3D-макет</a>): обертати його, гортати й завантажити зображення — в одному варіанті, такому як ваш (перший збережений ракурс, а без ракурсів — тип, положення й світло з вашого макета), без налаштувань і без зміни типу. Макет у посиланні оновлюється сам, також у посиланнях, створених до його появи.</p><ol class=\"kroki\"><li>У перегляді клацніть <span class=\"ui\">Поділитися</span> — або в списку проєктів <span class=\"ui\">⋯</span> на картці → <span class=\"ui\">Поділитися посиланням…</span> (проєкт не відкривається, сторінки підготуються у фоні).</li><li><span class=\"ui\">Створити посилання</span> — посилання готове одразу; зображення сторінок готуються у фоні (вікно можна закрити). Хто відкриє посилання в цей час, побачить «Перегляд готується», а сторінки з'являться в нього самі.</li><li>Скопіюйте посилання й надішліть його.</li></ol><p>Посилання коротке: <b>makietka.app/</b> і шість знаків, напр. <code>makietka.app/k7m2xq</code>. Посилання, створені раніше, отримують коротку адресу самі, під час найближчого відкриття проєкту; стара, довга адреса й далі працює.</p><div class=\"galeria\"><figure class=\"kadr\"><img src=\"img/instrukcja/k-udostepnij.png\" alt=\"Поділитися в перегляді\" loading=\"lazy\"><figcaption>Поділитися в перегляді</figcaption></figure><figure><img src=\"img/instrukcja/udostepnianie.png\" alt=\"Вікно «Поділитися переглядом»\" loading=\"lazy\"><figcaption>Вікно «Поділитися переглядом»</figcaption></figure></div><p>Проєкт із посиланням має в списку проєктів позначку <b>Спільне посилання</b> — клацання відкриває те саме вікно.</p>"},{"id":"23.2","tytul":"Оновлення","html":"<p>Посилання оновлюється само: за кілька секунд після ваших змін застосунок надсилає зображення сторінок, які змінилися. Адреса залишається та сама. <span class=\"ui\">Оновити зараз</span> робить це одразу. Людині, у якої посилання відкрите, не треба оновлювати сторінку — нові сторінки з'являться самі.</p><p>Зображення сторінок готує застосунок, тож посилання встигає за змінами, коли проєкт відкритий — у редакторі або в перегляді, на будь-якому пристрої. У цей час на екрані видно смугу <b>Оновлюю перегляд за посиланням – не закривайте Makietka</b> з лічильником сторінок. Вікно «Поділитися» можна закрити — сторінки створюються далі, а смуга залишається на екрані. Не закривайте лише вкладку з Makietka: браузер запитає, чи ви впевнені. Якщо вкладка все ж закриється, посилання доробиться саме під час наступного відкриття проєкту.</p><p>Коли треба намалювати багато сторінок одразу (від 40, напр. перше посилання на товсту книгу або зміна водяного знака), зображення малює сервер Makietka, а не ваш пристрій. Смуга тоді змінюється на <b>Перегляд за посиланням малюється на сервері – можете закрити Makietka</b>: посилання доробиться саме, також після закриття застосунку. Сервер малює ті самі зображення, що й застосунок. Дрібні зміни (кілька сторінок) і далі малює пристрій, бо це мить.</p>"},{"id":"23.3","tytul":"Захист посилання","html":"<p>Частина <b>Захист посилання</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><b>Пароль – без нього перегляд ніхто не побачить</b></td><td>Людина з посиланням спершу вводить <b>Пароль до посилання</b>. Після 10 невдалих спроб посилання на чверть години перестає приймати паролі.</td></tr><tr><td><b>Дійсне до вибраного дня</b></td><td>Після <b>Останнього дня дії</b> посилання перестає працювати.</td></tr></tbody></table></div><p>Захист можна задати під час створення посилання або будь-коли пізніше: змінити пароль, пересунути дату дії, додати захист до звичайного посилання або зняти його. Адреса посилання не змінюється. Те саме вікно відкриєте також зі списку проєктів, клацнувши позначку посилання на картці проєкту.</p><p><span class=\"ui\">Зберегти захист</span> зберігає налаштування. Порожнє поле пароля при позначеному паролі залишає попередній; зняття позначок з обох полів знімає захист. Сама зміна дати діє одразу. Новий пароль, увімкнення або зняття захисту готує сторінки посилання наново — це трохи триватиме, також зі списку проєктів (проєкт не відкривається).</p>"},{"id":"23.4","tytul":"Водяний знак","html":"<p>Частина <b>Водяний знак</b> у вікні «Поділитися»: позначте <b>Напис навскіс на кожній сторінці посилання</b>, введіть <b>Текст водяного знака</b> (порожнє поле — «ПЕРЕГЛЯД»), задайте повзунком <b>Непрозорість</b> (5–50 %, типово 12 % — блідий напис; маленький перегляд під повзунком одразу показує його на шматку сторінки) і клацніть <span class=\"ui\">Зберегти водяний знак</span>. Напис вбудовано в зображення сторінок посилання, також у 3D-макеті глядача, тож його не можна вимкнути на боці глядача. Налаштування зберігається одразу, а сторінки посилання потім готуються у фоні (смуга на екрані, див. 23.2) — вікно можна закрити; зняття позначки й збереження видаляє знак. Те саме стосується зміни захисту посилання. Водяний знак працює також зі списку проєктів і не змінює друк чи файл PDF.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-znak-wodny.png\" alt=\"Водяний знак: текст, повзунок «Непрозорість» і перегляд\" loading=\"lazy\"><figcaption>Водяний знак: текст, повзунок «Непрозорість» і перегляд</figcaption></figure>"},{"id":"23.5","tytul":"3D-макет у посиланні","html":"<p>Частина <b>3D-макет у посиланні</b> у вікні «Поділитися» визначає, що глядач побачить після дотику до <b>3D-макет</b> у перегляді за посиланням:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Налаштування</th><th>Що робить</th></tr></thead><tbody><tr><td><b>Глядач може переглянути 3D-макет</b></td><td>Без позначки — у посиланні лише сторінки, без макета.</td></tr><tr><td><b>Тип</b></td><td><b>Як у макеті проєкту</b> (тип, дібраний до проєкту) або вибраний тип, напр. блокнот замість книги. Типи, що не пасують, нижче, у групі <b>Не відповідає проєкту</b>.</td></tr><tr><td><b>Ракурс</b></td><td>Перший збережений ракурс або вибраний зі списку збережених (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"19.4\">3D-макет</a>): тип, камера, світло, тло й положення аркушів із цього ракурсу.</td></tr></tbody></table></div><p><b>Зберегти макет у посиланні</b> зберігає вибір у проєкті; наявне посилання оновлюється у фоні. Працює також зі списку проєктів.</p>"},{"id":"23.6","tytul":"Анулювання посилання","html":"<p><span class=\"ui\">Анулювати посилання</span> видаляє надані сторінки — стара адреса одразу перестає працювати. Повторне надання доступу дає нову адресу.</p><p class=\"ramka-instrukcji uwaga\"><b>Увага.</b> Посилання довге й випадкове, тож його не можна вгадати, але кожен, хто його отримає, може передати його далі. Для конфіденційних проєктів задайте пароль.</p>"}]},
  {"nr":"24","tytul":"Спільна робота","czesc":"Разом з іншими","ikona":"uzytkownik","wstep":"Спільна робота над проєктом: запрошення, ролі й коментарі.","sekcje":[{"id":"24.1","tytul":"Запрошення","html":"<p>Кожен працює у своєму обліковому записі, а зміни всі бачать наживо. Виберіть <span class=\"ui\">⋯</span> → <span class=\"ui\">Спільна робота…</span> у редакторі або на картці проєкту.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-wspolpraca.png\" alt=\"Спільна робота в меню ⋯\" loading=\"lazy\"><figcaption>Спільна робота в меню ⋯</figcaption></figure><p>У розділі <b>Запросити людину</b>:</p><ol class=\"kroki\"><li>У полі <b>Ел. пошта або ім’я користувача</b> введіть адресу або ім'я — після двох літер з'являться відповідні імена користувачів.</li><li>Виберіть <b>Роль</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24.2\">Ролі</a>).</li><li>Натисніть <span class=\"ui\">Запросити</span>.</li></ol><p>Застосунок надсилає лист із посиланням-запрошенням. Посилання можна також скопіювати й надіслати самостійно. Коли запрошуєте за іменем, ви не бачите адреси електронної пошти цієї людини. Якщо ця людина вимкнула листи про запрошення (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.6\">Сповіщення</a>), застосунок про це скаже — запрошення вона побачить у застосунку.</p><figure><img src=\"img/instrukcja/wspolpraca.png\" alt=\"Вікно «Спільна робота»\" loading=\"lazy\"><figcaption>Вікно «Спільна робота»</figcaption></figure>"},{"id":"24.2","tytul":"Ролі","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Роль</th><th>Що може</th></tr></thead><tbody><tr><td><b>може редагувати</b></td><td>Змінює сторінки, дані, шаблони й стилі; експортує PDF.</td></tr><tr><td><b>може переглядати</b></td><td>Відкриває проєкт лише в режимі перегляду.</td></tr><tr><td><b>Власник</b></td><td>Усе перелічене, а також запрошує, змінює ролі, відкликає доступ, надає посилання для перегляду й видаляє проєкт.</td></tr></tbody></table></div>"},{"id":"24.3","tytul":"Прийняття запрошення","html":"<p>Клацніть посилання в листі. Якщо у вас є обліковий запис, запрошення ви побачите й у застосунку: у списку проєктів з'явиться кнопка <span class=\"ui\">Запрошення</span> з числом. Прийнятий проєкт буде у вашому списку з позначкою власника.</p><p>Запрошення приймає людина, яка має посилання, — навіть з іншої адреси, ніж та, на яку його надіслано. У вікні «Спільна робота» завжди видно, хто насправді є в проєкті.</p><p>З увімкненими сповіщеннями (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.6\">Сповіщення</a>) ви дізнаєтеся про запрошення одразу.</p>"},{"id":"24.4","tytul":"Робота наживо","html":"<ul class=\"punkty\"><li>Зміни об'єднуються елемент за елементом: коли ви виправляєте заголовок, а хтось пересуває фото, лишаються обидві зміни. Щодо того самого елемента застосунок запитає (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.5\">Кілька пристроїв і скасування</a>).</li><li>Кружечки з ініціалами на панелі редактора й перегляду показують, хто ще має відкритий проєкт; наведіть курсор на кружечок, щоб побачити, на якій сторінці ця людина.</li><li><span class=\"ui\">Скасувати</span> скасовує лише ваші зміни.</li></ul>"},{"id":"24.5","tytul":"Керування учасниками","html":"<p>Власник у вікні «Спільна робота» біля кожної людини може:</p><ul class=\"punkty\"><li>змінити <b>роль</b> у розкривному списку,</li><li><span class=\"ui\">Відкликати</span> — відкликає доступ одразу; зміни, які ця людина вже зберегла, лишаються,</li><li>для запрошення, що очікує: <span class=\"ui\">Копіювати посилання-запрошення</span>, <span class=\"ui\">Надіслати лист із запрошенням повторно</span> і <span class=\"ui\">Скасувати запрошення</span>.</li></ul>"},{"id":"24.6","tytul":"Вихід із проєкту та копія","html":"<p>Співавтор може <span class=\"ui\">Вийти з проєкту</span> — у меню <span class=\"ui\">⋯</span> на картці або у вікні «Спільна робота». <span class=\"ui\">Зробити власну копію</span> створює ваш власний проєкт із тим самим вмістом.</p>"},{"id":"24.7","tytul":"Коментарі","html":"<p>Коментар — це примітка, прикріплена до місця на сторінці або до елемента, — як стікер на роздруківці, — видима як помаранчева шпилька з номером. Коментувати можуть усі учасники проєкту, зокрема з роллю <b>може переглядати</b> (у режимі перегляду). У PDF коментарів немає.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-komentarz-narzedzie.png\" alt=\"Інструмент «Коментар» і кнопка «Коментарі» з лічильником\" loading=\"lazy\"><figcaption>Інструмент «Коментар» і кнопка «Коментарі» з лічильником</figcaption></figure><p><b>Додавання коментаря</b></p><ol class=\"kroki\"><li>Натисніть <span class=\"ui\">Коментар</span> на панелі інструментів (у перегляді: <span class=\"ui\">Коментарі</span> → <span class=\"ui\">Новий коментар</span>).</li><li>Клацніть місце на сторінці. Якщо спершу виділите елемент, коментар одразу прикріпиться до нього.</li><li>Введіть текст і натисніть <span class=\"ui\">Додати коментар</span> (або Ctrl+Enter). Esc скасовує.</li></ol><p>Введіть <b>@</b> і початок імені, щоб згадати учасника проєкту, — застосунок підкаже імена.</p><p><b>Список коментарів</b></p><p><span class=\"ui\">Коментарі</span> на верхній панелі редактора й у перегляді показують кількість невирішених обговорень. Клацання шпильки відкриває її обговорення.</p><figure><img src=\"img/instrukcja/komentarze.png\" alt=\"Панель «Коментарі» з обговоренням і відповіддю\" loading=\"lazy\"><figcaption>Панель «Коментарі» з обговоренням і відповіддю</figcaption></figure><ul class=\"punkty\"><li>Фільтри: <b>Невирішені</b>, <b>Усі</b>, <b>Мої</b> (мої обговорення, мої відповіді й згадки про мене).</li><li>В обговоренні є відповіді, <span class=\"ui\">Відповісти</span> і <span class=\"ui\">Показати на сторінці</span>.</li><li><span class=\"ui\">Розв'язати</span> закриває вирішене обговорення й ховає шпильку; <span class=\"ui\">Відкрити знову</span> (фільтр <b>Усі</b>) повертає його.</li><li>Власний коментар можна виправити олівцем <span class=\"ui\">Редагувати</span> (з позначкою «(змінено)»); <kbd>Ctrl</kbd>+<kbd>Enter</kbd> зберігає й надсилає.</li><li>Видалити коментар може автор або власник проєкту — він одразу зникає в усіх, разом із відповідями.</li><li>Коментар до елемента рухається разом з елементом; якщо елемент видалити, шпилька лишається на цьому місці. Обговорення з видаленої сторінки лишається в списку з позначкою «сторінку видалено».</li><li>Коментарі додаються на сторінках, а не на шаблонах.</li></ul><p>Коментарі з'являються в усіх одразу; відповідь, яку ви пишете, не зникає, коли хтось щось додасть. Про нові ви дізнаєтеся й зі сповіщень (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.6\">Сповіщення</a>).</p><p>ШІ, підключений ключем, теж читає коментарі, відповідає на них і може їх розв'язати після виправлення (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.1\">Що вміє ШІ</a>).</p>"}]},
  {"nr":"25","tytul":"Робота з ШІ","czesc":"Разом з іншими","ikona":"uzytkownik","wstep":"Асистент ШІ може створювати й змінювати ваші проєкти разом із вами.","sekcje":[{"id":"25.1","tytul":"Що вміє ШІ","html":"<p>Асистент ШІ (Claude, ChatGPT та інші) підключається до Makietka через <b>конектор</b>: адресу з вашим ключем, яку ви додаєте в застосунку ШІ.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>ШІ може</th><th>ШІ не може</th></tr></thead><tbody><tr><td>створювати, копіювати й видаляти проєкти (з повним доступом)</td><td>бачити проєкти поза ключем</td></tr><tr><td>додавати, змінювати й копіювати сторінки; додавати, змінювати, вирівнювати й рівномірно розподіляти елементи; змінювати стилі й шаблони</td><td>змінити ваш обліковий запис чи пароль</td></tr><tr><td>заповнювати таблиці даних і налаштовувати серії</td><td>створити файл PDF без Makietka — його малює ваш браузер (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.5\">Файл PDF через ШІ</a>)</td></tr><tr><td>завантажувати, вставляти й замінювати фото</td><td></td></tr><tr><td>читати коментарі, відповідати на них і додавати власні (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24.7\">Коментарі</a>)</td><td></td></tr><tr><td>замовити файл PDF або PNG сторінки й дати вам посилання для завантаження (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.5\">Файл PDF через ШІ</a>)</td><td>малювати зображення – їх малює лише <span class=\"ui\">Асистент ШІ</span> у Makietka (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Асистент ШІ в Makietka (власний ключ)</a>); застосунок ШІ може завантажити зображення, намальоване в себе</td></tr><tr><td></td><td>ділитися проєктом або запрошувати людей (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24\">Спільна робота</a>)</td></tr><tr><td></td><td>завантажувати шрифти, користуватися Бібліотекою чи скасовувати зміни – скасуєте їх у редакторі (<kbd>Ctrl</kbd>+<kbd>Z</kbd>)</td></tr><tr><td></td><td>малювати кадри комікса чи розставляти бульбашки однією командою – це робить <span class=\"ui\">Асистент ШІ</span> у Makietka</td></tr></tbody></table></div><p>Пишіть ШІ звичайно, як дизайнерові: що хочете зробити, у якому форматі, скільки сторінок, який настрій. Якщо проєкт у вас відкритий, зміни з'являються в редакторі за мить. Зміни ШІ об'єднуються з вашими так само, як зміни співавтора (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24.4\">Робота наживо</a>).</p><p>Копія проєкту через з'єднувач має всі сторінки, дані й зображення. Власні копії зображень з облікового запису вона отримує під час першого відкриття в Makietka; доти користується файлами оригіналу, тож видалення оригіналу їх не стирає.</p>"},{"id":"25.2","tytul":"Ключ для ШІ","html":"<p><span class=\"ui\">Налаштування облікового запису</span> → <b>Штучний інтелект</b> починається з таблиці <b>Скільки приблизно коштує ШІ</b> (приблизні ціни з Google Gemini: покращення й переклад тексту та розмова – частка гроша, сценарій коміксу – бл. 1 гроша, зображення – бл. 0,14 зл в ескізі, 0,41 зл для друку, 0,55 зл найкраще; приклад коміксу 3 × 3 кадри – бл. 1,50 зл) і поля <b>Місячний ліміт витрат на зображення й тексти ШІ</b>. Вікна й асистент не питають згоди на кожне зображення – вартість видно біля кнопки й у розмові, а ліміт стежить, щоб ви не витратили забагато.</p><p>Нижче є перемикач чотирьох способів роботи з ШІ: <b>Чат у Makietka</b>, <b>Конектор у застосунку ШІ</b>, <b>Копіювати й вставити</b> і <b>Чат, що відкриває сторінки</b>. Кожна вкладка пояснює, як працює цей спосіб, що вам потрібно і скільки це коштує, а нижче показує ваші ключі з кнопкою <span class=\"ui\">Редагувати</span> і кнопку <span class=\"ui\">Додати ключ</span>. Новий ключ ви завжди додаєте й редагуєте в невеликому вікні.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Розділ</th><th>Для чого</th><th>Вартість</th></tr></thead><tbody><tr><td><b>Чат у Makietka</b></td><td>Ключі API постачальників (Anthropic, OpenAI, Gemini, DeepSeek, Mistral, xAI, OpenRouter, сумісні з OpenAI) для асистента ШІ в редакторі (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Асистент ШІ в Makietka (власний ключ)</a>). У вікні ви вибираєте постачальника, вставляєте ключ (<span class=\"ui\">Де взяти ключ?</span> веде на сторінку постачальника) і натискаєте <span class=\"ui\">Зберегти ключ</span>. Ключі зашифровано вашим паролем до ключів – ніхто, крім вас, їх не прочитає, навіть адміністратори Makietka. Тут також видно одноденні ключі «Чат у Makietka», якими асистент читає відкритий проєкт.</td><td>Ви платите постачальникові. Без ключа: режим «копіювати й вставити» (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Асистент ШІ в Makietka (власний ключ)</a>).</td></tr><tr><td><b>Конектор у застосунку ШІ</b></td><td>Ключ доступу й адреса конектора для Claude, ChatGPT та інших застосунків з MCP (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.3\">Підключення в застосунку ШІ</a>). Сюди ж потрапляють підключення з входом («Конектор: назва застосунку»).</td><td><b>Найімовірніше, платний план</b> застосунку ШІ (ChatGPT – платні плани; Claude – у безкоштовному один власний конектор).</td></tr><tr><td><b>Копіювати й вставити</b></td><td>Будь-який чат у браузері, зокрема безкоштовний ChatGPT, без ключа: ви вибираєте проєкт і <span class=\"ui\">Відкрити з асистентом ШІ</span> – проєкт відкривається з асистентом ШІ в режимі «копіювати й вставити» (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Асистент ШІ в Makietka (власний ключ)</a>). Чат не отримує жодного ключа чи адреси.</td><td>Нічого.</td></tr><tr><td><b>Чат, що відкриває сторінки</b></td><td>Ключ доступу й готовий запит з адресами для чату, який сам відкриває будь-які сторінки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.7\">ШІ, який уміє відкривати сторінки (без конектора)</a>). ChatGPT цього не робить – тоді «Копіювати й вставити».</td><td>Makietka нічого не бере.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-konto-ai.png\" alt=\"Штучний інтелект у налаштуваннях облікового запису\" loading=\"lazy\"><figcaption>Штучний інтелект у налаштуваннях облікового запису</figcaption></figure><p>Вікно нового ключа доступу (конектор і звичайний чат):</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Параметр</th><th>Значення</th></tr></thead><tbody><tr><td><b>Опис (для вас)</b></td><td>Наприклад, «Claude – календар».</td></tr><tr><td><b>ШІ може</b></td><td><b>читати й змінювати</b> або <b>лише читати</b>.</td></tr><tr><td><b>Дійсний</b></td><td>1 день, 7 днів, 30 днів, 90 днів, рік або безстроково.</td></tr><tr><td><b>Вибрані проєкти</b></td><td>Проєкти, до яких ключ дає доступ, — ваші й ті, якими поділилися з вами.</td></tr><tr><td><b>Повний доступ – усі проєкти, зокрема створення й видалення</b></td><td>Також проєкти, що з'являться пізніше. Видалення проєкту ШІ завжди підтверджує назвою.</td></tr><tr><td><b>Під час змін ШІ також може</b></td><td>П'ять перемикачів (типово всі ввімкнені): додавати, видаляти й переставляти сторінки; змінювати шаблони й стилі; змінювати таблиці даних і серії; завантажувати, замінювати й видаляти зображення; створювати файли PDF і PNG. Якщо вимкнено – ШІ отримує відмову з поясненням; це контролює сервер Makietka, а не застосунок ШІ. Видно лише для ключа «читати й змінювати».</td></tr></tbody></table></div><p><span class=\"ui\">Створити ключ</span> показує <b>Адресу конектора</b> (або готовий запит для звичайного чату). Якщо у вас є пароль до ключів, Makietka запам'ятовує ключ, зашифрований цим паролем; без пароля – <span class=\"ui\">Запам'ятати ключ</span> у вікні. <span class=\"ui\">Готово</span> закриває вікно.</p><p>Біля кожного ключа в списку є <span class=\"ui\">Редагувати</span> – редагування відкривається у вікні, так само як додавання:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>У вікні</th><th>Що робить</th></tr></thead><tbody><tr><td><span class=\"ui\">Показати ключ</span></td><td>Ще раз показує адресу конектора або запит для звичайного чату (і сам ключ) – щоб скопіювати. Працює для ключів, збережених у сейфі.</td></tr><tr><td><b>Діапазон</b></td><td>Вибрані проєкти або повний доступ — адреса не змінюється.</td></tr><tr><td><b>Дозволи</b></td><td>Ті самі п'ять перемикачів, що й для нового ключа. Список ключів показує, чого ключ не може (наприклад, «без: сторінок, зображень»).</td></tr><tr><td><b>Термін дії</b></td><td>Новий термін від сьогодні (1 день … рік або безстроково), зокрема для ключа, термін якого вже минув; «без змін» залишає поточний.</td></tr><tr><td><span class=\"ui\">Зберегти зміни</span></td><td>Зберігає діапазон і термін дії.</td></tr><tr><td><span class=\"ui\">Відкликати ключ</span></td><td>Одразу вимикає ключ.</td></tr></tbody></table></div><p>Ключ API постачальника у вікні редагування: <span class=\"ui\">Показати ключ</span>, <b>Замінити ключ</b> (вставляєте новий і <span class=\"ui\">Зберегти</span>) і <span class=\"ui\">Видалити ключ</span>. Розділ <b>Модель і з'єднання</b> (також під час додавання): <b>Типова модель</b> – порожнє поле означає рекомендовану модель постачальника (після <span class=\"ui\">Перевірити з'єднання</span> видно, яку; список підказує також найдешевшу й найкращу), для «Інший – сумісний з OpenAI» також <b>Адреса API</b>, і <span class=\"ui\">Перевірити з'єднання</span> – Makietka запитує в постачальника список моделей і каже, чи працює ключ, а якщо ні – чому (неправильний ключ, брак коштів, ліміт, модель недоступна, немає інтернету).</p><p>Коли ключі на цьому пристрої зашифровано, розділ «Чат у Makietka» показує <span class=\"ui\">Відкрити</span> – пароль до ключів ви вводите один раз на пристрої.</p><figure><img src=\"img/instrukcja/dostep-ai.png\" alt=\"Налаштування «Штучний інтелект»\" loading=\"lazy\"><figcaption>Налаштування «Штучний інтелект»</figcaption></figure>"},{"id":"25.3","tytul":"Підключення в застосунку ШІ","html":"<p><b>Найпростіше – із входом (без копіювання ключа).</b> У застосунку ШІ додайте власний конектор за адресою <code>https://api.makietka.app/mcp</code> (без ключа) і виберіть вхід (OAuth). Застосунок відкриє сторінку Makietka <b>Підключитися до Makietka</b>: ви входите зі своїм паролем, бачите, хто просить доступ (наприклад, «Claude»), вибираєте проєкти (або всі), лише читання чи також зміни і термін дії – <span class=\"ui\">Дозволити</span> повертає до застосунку ШІ, <span class=\"ui\">Відмовити</span> завершує підключення. Підключення — це звичайний ключ доступу «Конектор: назва застосунку» – його видно в налаштуваннях «Штучний інтелект», і його можна відкликати. Застосунок ШІ не отримує вашого пароля. Другий спосіб – адреса з ключем із вікна – працює, як і раніше:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Застосунок</th><th>Як підключити</th></tr></thead><tbody><tr><td><b>Claude</b> (claude.ai, застосунок для комп'ютера й телефона)</td><td><b>Налаштування → Конектори → Додати власний конектор</b>, назва «Makietka», вставте адресу. У розмові ввімкніть конектор у меню інструментів.</td></tr><tr><td><b>Claude Desktop</b></td><td>У вікні «Штучний інтелект»: <span class=\"ui\">Завантажити розширення для Claude Desktop</span>, двічі клацніть завантажений файл і вставте ключ. Розширення також читає файли з вашого диска.</td></tr><tr><td><b>ChatGPT</b></td><td><b>Налаштування → Застосунки → Додати власний сервер MCP</b>, вставте адресу, автентифікація: немає.</td></tr><tr><td><b>Claude Code</b> та інші програми з MCP</td><td>Команда з розділу <b>Для досвідчених</b> у налаштуваннях «Штучний інтелект».</td></tr></tbody></table></div><p>Перевірка: напишіть ШІ «Покажи мої проєкти в Makietka».</p><p>Найпростіше скопіювати запит «Підключи Makietka» і вставити його в розмову — ШІ розпізнає, у якому застосунку ви працюєте, і скаже, що натиснути:</p><div class=\"prompt-instrukcji\"><div class=\"prompt-naglowek\"><b>Запит «Підключи Makietka»</b><button type=\"button\" class=\"przycisk\" data-kopiuj-prompt data-ikona=\"kopiuj\">Копіювати</button></div><p class=\"ciche\">Вставте в розмову з ШІ – він проведе вас через підключення у вашому застосунку.</p><pre>Pomóż mi podłączyć Makietkę do Ciebie jako łącznik (serwer MCP), krok po kroku.\n\nCo to jest Makietka: aplikacja w przeglądarce (https://makietka.app) do składania publikacji do druku – kalendarzy, planerów, notesów, zeszytów, komiksów. Ma strony, wzorce, style tekstu, tabele danych, serie powielanych stron, obrazy i eksport PDF.\n\nCo wiem o łączniku Makietki:\n- To zdalny serwer MCP (transport Streamable HTTP) z logowaniem OAuth: adres https://api.makietka.app/mcp (bez klucza) – aplikacja AI otworzy stronę Makietki, gdzie się loguję i wybieram projekty. Druga droga: adres z kluczem https://api.makietka.app/mcp/&lt;klucz&gt; (łącznik „bez logowania”).\n- Klucz tworzę sam w Makietce: Ustawienia konta → Sztuczna inteligencja. Wybieram: które projekty (albo pełny dostęp – wtedy AI może też tworzyć i usuwać projekty), czy AI tylko czyta, czy też zmienia, i ważność. Adres z kluczem widać tylko raz.\n- Narzędzia łącznika: lista projektów, nowy projekt i usunięcie projektu (przy pełnym dostępie), przegląd projektu, czytanie i zmiana stron, elementów, wzorców, stylów, tabel danych i serii, wgrywanie obrazów (adres https, link z Dysku Google albo Dropboxa, kod SVG, małe pliki kawałkami), wstawianie obrazów na strony, link do wgrania zdjęć przez przeglądarkę, kontrola przed drukiem.\n- Opis dla AI: https://makietka.app/ai/api.md, model danych projektu: https://makietka.app/ai/format-makietka.md.\n- Dla Claude Desktop jest też rozszerzenie https://makietka.app/ai/mcp/makietka.mcpb – działa na komputerze i czyta pliki oraz foldery z dysku.\n- Claude Code: claude mcp add --transport http makietka https://api.makietka.app/mcp/&lt;klucz&gt;\n\nTwoje zadanie:\n1. Ustal, w jakiej aplikacji teraz rozmawiamy (claude.ai w przeglądarce, aplikacja Claude na telefonie, Claude Desktop, Claude Code, ChatGPT, Cursor albo inna) i czy na moim planie da się w niej dodać własny łącznik MCP. Jeśli nie wiesz – zapytaj mnie.\n2. Poprowadź mnie po kolei, co kliknąć, żeby dodać łącznik o nazwie „Makietka” z moim adresem. Nie proś mnie o wklejenie klucza do tej rozmowy – wkleję go sam w ustawieniach.\n3. Jeśli ta aplikacja albo mój plan nie obsługuje łączników, powiedz to wprost i zaproponuj najprostszą drogę (inna aplikacja, Claude Desktop z rozszerzeniem, Claude Code).\n4. Po podłączeniu sprawdź, czy widzisz narzędzie „projekty”, i pokaż mi listę moich projektów.\nPisz prosto, po polsku, jeden krok na raz i czekaj, aż powiem, że zrobione.</pre></div><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> Конектори зазвичай доступні в платних планах застосунків ШІ. На телефоні зазвичай можна лише користуватися конекторами, доданими раніше на комп'ютері.</p>"},{"id":"25.4","tytul":"Фото через ШІ","html":"<ul class=\"punkty\"><li><b>ChatGPT</b> бере фото, додані в розмову, напряму.</li><li><b>Claude</b> сам завантажує невеликі зображення з розмови; <b>Claude Desktop із розширенням</b> — файли й папки з диска.</li><li><b>Посилання для завантаження працює завжди:</b> попросіть у ШІ посилання — воно відкриє цей проєкт із вікном «Зображення проєкту», ви кидаєте туди фото або ZIP, а ШІ бачить їх і працює далі.</li><li>ШІ також завантажить зображення з адреси в інтернеті або з посилання на Google Диск чи Dropbox, відкритого для «усіх, хто має посилання», і намалює власну графіку SVG.</li></ul><p>Фото, яке стоїть на сторінці, ШІ не видаляє — замінює його новим файлом у тому самому місці.</p>"},{"id":"25.5","tytul":"Файл PDF через ШІ","html":"<p>Попросіть ШІ, наприклад, «Зроби PDF для друкарні» або «Покажи обкладинку як зображення». Файл малює Makietka тим самим кодом, що й <span class=\"ui\">Експортувати в PDF…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Експорт у PDF і PNG</a>):</p><ul class=\"punkty\"><li><b>Makietka відкрита</b> (будь-яка вкладка, на комп'ютері або телефоні) — сама приймає замовлення. Угорі з'являється смуга «ШІ замовив експорт PDF…», а за мить — сповіщення з кнопкою <span class=\"ui\">Завантажити</span>. ШІ отримує посилання для завантаження файлу й зауваження з перевірки перед друком.</li><li><b>Makietka закрита</b> — файл створить сервер Makietka (приблизно за хвилину), а ШІ дасть посилання для завантаження, коли ви знову запитаєте. Нічого не потрібно відкривати. Якщо сервер не впорається (наприклад, денний ліміт), ШІ дасть посилання на застосунок — після його відкриття файл створиться сам.</li></ul><p>Посилання для завантаження працює без входу 7 днів, потім файл зникає з облікового запису. ШІ може замовити весь проєкт, один розділ або вибрані сторінки, файл для друкарні (з вильотом і мітками різу, також PDF/X) або для читання на екрані, брошуру для складання чи PNG однієї сторінки.</p>"},{"id":"25.6","tytul":"Асистент ШІ в Makietka (власний ключ)","html":"<p>Без окремого застосунку ШІ: у редакторі <span class=\"ui\">Асистент ШІ</span> на верхній панелі (поруч із <span class=\"ui\">Перегляд</span>; на телефоні <span class=\"ui\">ШІ ▾</span> → <b>Асистент ШІ…</b>, а також меню <b>⋯</b> → <span class=\"ui\">ШІ-асистент (власний ключ)…</span>) відкриває чат поруч зі сторінкою (на телефоні — вікно). Напишіть, що зробити, напр. «розклади цю сторінку на дві колонки» або «додай заголовок і рамку для фото».</p><ol class=\"kroki\"><li><b>Постачальник</b> — Anthropic (Claude), OpenAI (ChatGPT), Google Gemini, DeepSeek, Mistral, xAI (Grok), OpenRouter (сотні моделей з одного облікового запису) або <b>Інший – API, сумісний з OpenAI</b> (із власною адресою). Біля назви видно, що він уміє: <b>розмова й зміни в проєкті</b> – кожен постачальник читає й змінює проєкт інструментами Makietka; <b>й зображення</b> – Google Gemini додатково малює зображення.</li><li><b>Ключ API</b> — від вибраного постачальника (<span class=\"ui\">Де взяти ключ?</span> веде на його сторінку). Для OpenRouter замість вставлення ключа досить <span class=\"ui\">Увійти через OpenRouter</span> — ви ввійдете й підтвердите доступ у них.</li><li><b>Модель</b> — залиште порожнім: Makietka сама вибере рекомендовану модель постачальника (швидку й розважливу; у полі видно, яку). Список підказує також <b>Найдешевший</b> і <b>Найкращий – дорожчий</b>, а досвідчені користувачі можуть ввести будь-яку назву.</li><li><b>ШІ може в цьому проєкті</b> — <b>читати й змінювати</b> або <b>лише читати</b>.</li></ol><p>Напишіть, що зробити (Enter надсилає, Shift+Enter — новий рядок). ШІ використовує ті самі інструменти, що й конектор (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.1\">Що вміє ШІ</a>); у чаті видно, які саме (🔧), а зміни одразу з'являються в редакторі. <span class=\"ui\">Зупинити</span> зупиняє після поточного кроку. Значок повзунків у заголовку показує й ховає налаштування.</p><ul class=\"punkty\"><li><b>Ключі зашифровані й зберігаються в обліковому записі.</b> Під час додавання першого ключа Makietka просить <b>пароль до ключів ШІ</b> (щонайменше 8 символів, бажано інший, ніж пароль облікового запису). Браузер шифрує ним ключ (AES-256) і лише тоді зберігає його в обліковому записі – на сервері лежить тільки зашифрований запис. Без вашого пароля його ніхто не прочитає, <b>навіть адміністратори Makietka</b>. На кожному новому пристрої ви вводите пароль один раз; потім пристрій його пам'ятає. Забули пароль: у вікні пароля <span class=\"ui\">Не пам'ятаю – видалити збережені ключі</span> і вставте ключі заново.</li><li>Розмова йде з браузера просто до постачальника, і за неї ви розраховуєтеся з ним.</li><li>ШІ бачить лише відкритий проєкт — через одноденний ключ доступу «Чат у Makietka», видимий у <span class=\"ui\">Налаштування облікового запису</span> → <b>Штучний інтелект</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.2\">Ключ для ШІ</a>); там його можна відкликати.</li><li>Зміна постачальника або моделі починає нову розмову.</li></ul><p><b>Без ключа й без оплати – «копіювати й вставити».</b> Постачальник <b>Будь-який чат без ключа – копіювати й вставити</b> працює з будь-яким чатом ШІ в браузері, зокрема безкоштовним (ChatGPT, Claude, Gemini, Copilot…), без ключа API:</p><ol class=\"kroki\"><li>Напишіть у чаті Makietka, що зробити. Makietka копіює в буфер обміну готовий запит: правила, список інструментів, стан проєкту й ваше завдання (його також видно в розмові з кнопкою <span class=\"ui\">Копіювати</span>).</li><li>Вставте його в чат ШІ. Він коротко відповість і додасть блок коду <code>makietka</code> з командами.</li><li>Вставте всю його відповідь у чат Makietka й надішліть – Makietka виконає команди (🔧) і скопіює результати.</li><li>Вставте результати в чат ШІ – він побачить, що вдалося, і за потреби надішле наступні команди.</li></ol><p>Дозволи такі самі, як із власним ключем (одноденний ключ «Чат у Makietka», читання або зміни).</p><p>Відповідь з'являється в розмові поступово, у міру того як ШІ її пише (Anthropic, OpenAI та сумісні, Gemini).</p><p><b>Фото в розмові.</b> Скріпка біля поля повідомлення додає фото (PNG, JPEG, WebP, GIF, до 5 МБ). ШІ їх бачить (модель має підтримувати зображення), а Makietka одразу завантажує оригінал у проєкт (вікно «Зображення проєкту»), тож ШІ може вставити його на сторінку. У режимі «копіювати й вставити» фото теж потрапляє в проєкт, але чат у браузері його не побачить.</p><p><b>Коли щось не працює,</b> асистент зрозуміло пише, що сталося: постачальник відхилив ключ, бракує коштів на рахунку постачальника, забагато запитів, модель недоступна або не підтримує інструменти, немає з'єднання. Коли постачальник перевантажений, Makietka сама повторює запит двічі, перш ніж повідомити про помилку.</p><p><b>Згода на ризиковані зміни.</b> Перш ніж асистент видалить сторінки, 3 і більше елементів одночасно, зображення або проєкт, змінить 3 і більше сторінок одним записом або повністю замінить шаблони, стилі, таблиці чи серії, у розмові з'являється запитання «ШІ хоче … Дозволити?» з кнопками <span class=\"ui\">Дозволити</span>, <span class=\"ui\">Завжди дозволяти в цій розмові</span> і <span class=\"ui\">Не дозволяти</span>. Після відмови нічого не змінюється, а ШІ отримує інформацію, що ви не дозволили, і запитує, що зробити натомість. Так само в режимі «копіювати й вставити»: запитання з'являється, коли вставлена відповідь чату містить таку зміну.</p><p><b>Зображення й комікс у чаті.</b> Асистент уміє також малювати: зображення з опису в рамку або на сторінку (як <span class=\"ui\">ШІ ▾</span> → <b>Зображення з опису…</b>, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.11\">Зображення ШІ</a>), кадри сторінки коміксу зі сценарію й карток (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.13\">Комікс</a>), бульбашки зі сценарію й оцінку вартості. Зображення малює Google Gemini ключем Gemini із сейфа, навіть коли ви розмовляєте з іншим постачальником. Асистент не питає згоди на кожне зображення – у розмові пише, що малює і скільки це приблизно коштує, напр. «🎨 Малюю зображення „Тюльпани в саду“ – бл. 0,14 зл». Запобіжником є <b>місячний ліміт витрат</b> у налаштуваннях ШІ: понад нього асистент нічого не намалює. Асистент малює в якості <b>Ескіз</b>, якщо ви не попросите кращу.</p><p>Приклади запитів:</p><ul class=\"punkty\"><li>«Додай на цій сторінці заголовок Весна в саду, під ним рамку й намалюй у ній тюльпани.»</li><li>«Намалюй кадри сторінки 2 коміксу й розстав бульбашки.»</li><li>«Скільки коштуватиме намалювати 10 зображень для друку?»</li><li>«Переклади всі тексти на цій сторінці англійською.»</li><li>«На зображенні на сторінці 2 додай дівчинці червоний капелюх.» – асистент виправляє поточне зображення, решта лишається.</li></ul><p>Зміни й зображення з’являються в редакторі під час розмови – чат не треба закривати.</p>"},{"id":"25.7","tytul":"ШІ, який уміє відкривати сторінки (без конектора)","html":"<p>Адреса конектора (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.2\">Ключ для ШІ</a>), <b>відкрита як звичайна сторінка</b>, показує опис доступу й список інструментів простим текстом. ШІ, який уміє читати сторінки з інтернету (наприклад, безкоштовний ChatGPT чи Claude з пошуком), може отже працювати без додавання конектора: у налаштуваннях <b>Штучний інтелект</b>, одразу після створення ключа, <span class=\"ui\">Копіювати для звичайного чату</span> дає готовий запит з адресою – вставте його в розмову; ШІ покаже ваші проєкти й запитає, що зробити. Інструменти він викликає, відкриваючи адреси <code>…/n/&lt;інструмент&gt;?параметр=значення</code> (складні параметри як <code>?json=…</code>); відповіддю є результат або опис помилки. Дозволи визначає ключ – ключ <b>лише читати</b> нічого не змінить.</p><p class=\"ramka-instrukcji uwaga\"><b>Увага.</b> Частина чатів відкриває лише адреси, які отримала від користувача або знайшла сама, – а не ті, які складе. Тоді працює читання (посилання з опису), а для змін скористайтеся режимом «копіювати й вставити» або конектором.</p><p class=\"ramka-instrukcji uwaga\"><b>Увага.</b> ChatGPT відкриває лише адреси, вставлені вами (не ті, які складе сам, і не посилання, знайдені на сторінці). Тому запит містить готові адреси для читання: проєкти, огляд проєкту й опис формату – читати він буде, але змін зазвичай не зробить. Для змін без платного плану скористайтеся асистентом ШІ в режимі «копіювати й вставити» (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Асистент ШІ в Makietka (власний ключ)</a>).</p>"},{"id":"25.8","tytul":"Безпека","html":"<p>ШІ отримує щонайбільше ваші дозволи: у проєкті, який ви можете лише переглядати, ключ лише читає, а коли власник відкличе ваш доступ, ключ одразу його втрачає.</p><p class=\"ramka-instrukcji uwaga\"><b>Увага.</b> Адреса конектора містить ключ — хто її має, той має доступ до вибраних проєктів. Не публікуйте її, задавайте найкоротший достатній термін дії й відкликайте ключ після завершення роботи.</p>"}]},
  {"nr":"26","tytul":"Приклад: комікс із ШІ","czesc":"Разом з іншими","ikona":"uzytkownik","sekcje":[{"id":"26.1","tytul":"Від ідеї до файлу","html":"<p>Зошит A5 з обкладинкою: ШІ розкладає кадри й виноски, ви надаєте малюнки й ухвалюєте рішення.</p><ol class=\"kroki\"><li>Створіть ключ із <b>повним доступом</b> і <b>читати й змінювати</b> — ШІ створить новий проєкт (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.2\">Ключ для ШІ</a>).</li><li>Скопіюйте запит «Комікс для друку» (нижче), допишіть свою ідею й надішліть. ШІ спершу покаже план сторінок — виправте його, перш ніж він почне.</li><li>Відкрийте новий проєкт — ви побачите, як додаються сторінки, кадри й виноски.</li><li>Попросіть у ШІ посилання для завантаження й додайте малюнки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.4\">Фото через ШІ</a>). ШІ вставить їх у кадри.</li><li>Виправте, що хочете: текст у виносках (стиль «Виноска» змінює всі одразу), кадрування, порядок сторінок.</li><li>Обкладинку зробіть окремим розділом із корінцем (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.6\">Обкладинка з корінцем</a>).</li><li><span class=\"ui\">Перевірити перед друком</span>, потім PDF <b>Для друкарні</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Перевірка перед друком</a>, <a href=\"#\" data-cel=\"21\">Експорт у PDF і PNG</a>).</li></ol><div class=\"prompt-instrukcji\"><div class=\"prompt-naglowek\"><b>Запит «Комікс для друку»</b><button type=\"button\" class=\"przycisk\" data-kopiuj-prompt data-ikona=\"kopiuj\">Копіювати</button></div><p class=\"ciche\">Скопіюйте, допишіть ідею в кінці й надішліть ШІ з підключеною Makietka.</p><pre>Korzystając z łącznika Makietka, przygotuj ze mną komiks do druku.\n\n1. Najpierw zaproponuj plan: tytuł, liczbę stron (domyślnie 8 stron środka + okładka), na każdej stronie liczbę kadrów i co się w nich dzieje. Poczekaj, aż zatwierdzę.\n2. Potem utwórz nowy projekt „Komiks – &lt;tytuł&gt;”: format A5 (148×210 mm), spad 3 mm, marginesy 8 mm. Środek w rozkładówkach, okładka jako osobna sekcja.\n3. Na stronach ułóż kadry: prostokąty z czarnym obrysem 0,6 mm i odstępem 4 mm między kadrami, w obrębie marginesów. W kadrach dymki (elipsy albo prostokąty z zaokrągleniem, białe wypełnienie, czarny obrys) z tekstem 9 pt, wyśrodkowanym. Narrację umieść w prostokątnych ramkach u góry kadru.\n4. Zrób styl tekstu „Dymek” i „Narracja”, żebym mógł je potem zmienić naraz.\n5. Rysunków nie wymyślaj na siłę: jeśli nie możesz ich narysować, w każdym kadrze zostaw szary prostokąt z krótkim opisem sceny. Ja wgram rysunki – daj mi link do wgrania obrazów, a potem wstaw je w kadry z dopasowaniem „wypełnij”.\n6. Dodaj numery stron we wzorcu (pole {nr}) na dole, po zewnętrznej stronie.\n7. Na koniec uruchom kontrolę przed drukiem i powiedz, co poprawić.\n\nMój pomysł na komiks: &lt;opisz tutaj bohaterów, historię i nastrój&gt;</pre></div><p class=\"ramka-instrukcji wskazowka\"><b>Порада.</b> Зошит на скобі має кількість сторінок, кратну 4 (8, 12, 16…). Малюнки для друку підготуйте щонайменше з роздільністю 300 dpi в розмірі кадру.</p>"}]},
  {"nr":"27","tytul":"Обліковий запис","czesc":"Обліковий запис, пристрої та довідка","ikona":"motyw","wstep":"Обліковий запис зберігає ваші проєкти, шрифти й елементи, тож вони є у вас на кожному пристрої.","sekcje":[{"id":"27.1","tytul":"Створення облікового запису","html":"<p>На екрані входу виберіть <span class=\"ui\">Новий обліковий запис</span> і введіть:</p><ul class=\"punkty\"><li><b>Ім’я користувача</b> — 3–30 символів: літери, цифри, <code>_</code>, <code>.</code> і <code>-</code>. За цим ім’ям інші запрошуватимуть вас до проєкту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24.1\">Запрошення</a>).</li><li><b>Ел. пошту</b>.</li><li><b>Пароль</b> — щонайменше 8 символів, мала й велика літера, цифра та спеціальний символ.</li></ul><p>Якщо надійде лист «Підтвердьте свій обліковий запис», натисніть у ньому кнопку — лише тоді ви зможете увійти.</p><div class=\"galeria\"><figure><img src=\"img/instrukcja/rejestracja.png\" alt=\"Новий обліковий запис\" loading=\"lazy\"><figcaption>Новий обліковий запис</figcaption></figure><figure><img src=\"img/instrukcja/rejestracja-wyslano.png\" alt=\"Перевірте пошту\" loading=\"lazy\"><figcaption>Перевірте пошту</figcaption></figure></div>"},{"id":"27.2","tytul":"Вхід і пароль","html":"<p>У полі <b>Ел. пошта або ім’я користувача</b> введіть адресу облікового запису або своє ім’я користувача (регістр літер не має значення), потім пароль. Після 10 невдалих спроб входу з тим самим ім’ям доведеться зачекати чверть години — за адресою ел. пошти ви ввійдете одразу.</p><p><span class=\"ui\">Забули пароль?</span> надсилає посилання для встановлення нового пароля. Посилання діє один раз; коли воно втратить чинність, попросіть нове.</p><figure><img src=\"img/instrukcja/logowanie.png\" alt=\"Вхід\" loading=\"lazy\"><figcaption>Вхід</figcaption></figure>"},{"id":"27.3","tytul":"Налаштування облікового запису","html":"<p>Натисніть кружечок з ініціалом у правому верхньому куті списку проєктів і виберіть <span class=\"ui\">Налаштування облікового запису</span>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-konta.png\" alt=\"Меню облікового запису\" loading=\"lazy\"><figcaption>Меню облікового запису</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Рядок</th><th>Що змінюєте</th></tr></thead><tbody><tr><td><b>Ім’я користувача</b></td><td>Ім’я, за яким інші запрошують вас до проєктів.</td></tr><tr><td><b>Ел. пошта</b></td><td>Адресу облікового запису. <span class=\"ui\">Змінити адресу</span> надсилає посилання для підтвердження на нову адресу; доки ви його не натиснете, входите за попередньою. <span class=\"ui\">Ввести іншу адресу</span> замінює адресу, що очікує підтвердження, на нову.</td></tr><tr><td><b>Пароль</b></td><td><span class=\"ui\">Змінити пароль</span>.</td></tr><tr><td><b>Тема</b></td><td>Вигляд застосунку (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.4\">Тема</a>).</td></tr><tr><td><b>Сповіщення</b></td><td>Сповіщення на цьому пристрої (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.6\">Сповіщення</a>).</td></tr><tr><td><b>Штучний інтелект</b></td><td>Ключі для AI-асистентів (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.2\">Ключ для ШІ</a>).</td></tr><tr><td><b>Бренд-кит</b></td><td>Кольори, шрифти, стилі тексту й логотип бренду — доступні в кожному проєкті (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.9\">Бренд-кит</a>).</td></tr><tr><td><b>Місце</b></td><td>Скільки місця займають ваші файли й проєкти (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.5\">Місце й ліміти</a>).</td></tr><tr><td><b>Видалити обліковий запис</b></td><td>Видалення облікового запису (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"27.7\">Видалення облікового запису</a>).</td></tr></tbody></table></div><p><span class=\"ui\">Вийти всюди</span> (у розділі <b>Вхід</b>) виходить з облікового запису на всіх пристроях одразу — наприклад, після роботи на чужому комп’ютері.</p><figure><img src=\"img/instrukcja/konto.png\" alt=\"Налаштування облікового запису\" loading=\"lazy\"><figcaption>Налаштування облікового запису</figcaption></figure>"},{"id":"27.4","tytul":"Тема","html":"<p>Кнопка теми розташована вгорі екрана (у списку проєктів, у налаштуваннях облікового запису, на екрані входу) і в меню <span class=\"ui\">⋯</span> редактора. Вона показує значок вибраного режиму й відкриває меню: <b>Як у системі</b>, <b>Світла</b> або <b>Темна</b>. Те саме можна вибрати в <span class=\"ui\">Налаштування облікового запису</span> → <b>Тема</b>. Тема змінює лише вигляд застосунку — сторінки публікації завжди на білому папері.</p><figure><img src=\"img/instrukcja/motyw.png\" alt=\"Темна тема\" loading=\"lazy\"><figcaption>Темна тема</figcaption></figure><h4>Мова</h4><p>Поруч із кнопкою теми є кнопка з прапорцем – <b>мова застосунку</b>: польська (Polski), англійська (English) або українська. У редакторі той самий вибір є в меню <span class=\"ui\">⋯</span> → <b>Język / Language / Мова</b>. Першого разу Makietka бере мову браузера, а потім пам’ятає ваш вибір на цьому пристрої. Мова змінює лише написи застосунку — вміст проєктів (тексти на сторінках, назви, дані в таблицях) лишається таким, як його ввели. Довідка (кнопка з книжкою) та її знімки екрана теж показуються вибраною мовою.</p>"},{"id":"27.5","tytul":"Місце й ліміти","html":"<p><span class=\"ui\">Налаштування облікового запису</span> → <b>Місце</b> показує смуги лімітів облікового запису:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ліміт</th><th>Скільки</th></tr></thead><tbody><tr><td>Файли облікового запису (зображення, шрифти, попередні перегляди посилань)</td><td>2 ГБ</td></tr><tr><td>Один файл</td><td>50 МБ</td></tr><tr><td>Проєкти</td><td>100</td></tr><tr><td>Зображення в одному проєкті</td><td>1000</td></tr></tbody></table></div><p>Нижче — список ваших проєктів: скільки місця займає кожен, скільки в ньому зображень і сторінок, коли його змінювали. <span class=\"ui\">Відкрити</span> відкриває проєкт, <span class=\"ui\">Показати зображення</span> — його вікно зображень (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.5\">Вікно «Зображення проєкту»</a>). Проєкти інших людей, до яких ви маєте доступ, показано окремо, і вони не враховуються у ваші ліміти.</p><p>Від 80% ліміту застосунок попереджає — тут і під час завантаження зображень. <span class=\"ui\">Очистити…</span> показує, скільки місця звільниться, і видаляє лише файли, яких уже не використовує жоден проєкт: старі версії замінених фото, файли видалених проєктів і вимкнених посилань. Файли за останні два дні лишаються.</p>"},{"id":"27.6","tytul":"Сповіщення","html":"<p>Сповіщення одразу повідомляють про запрошення й коментарі — навіть коли застосунок закрито. У <span class=\"ui\">Налаштування облікового запису</span> → <b>Сповіщення</b> увімкніть <b>На цьому пристрої</b> (браузер попросить дозволу) і виберіть, про що хочете знати: запрошення, відповіді на ваші запрошення, зміни ролі й доступу, коментарі та згадки (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24.7\">Коментарі</a>). Натискання на сповіщення відкриває потрібний проєкт або гілку.</p><p>Сповіщення вмикають окремо на кожному пристрої. На iPhone та iPad вони працюють лише в установленому застосунку (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"28.4\">Установлення застосунку</a>).</p><p><b>Ел. поштою</b> — перемикач для всього облікового запису: лист, коли хтось запрошує вас до проєкту або надає вам до нього доступ. Якщо вимкнено — листи про запрошення не надходять, а запрошення чекає в застосунку (<span class=\"ui\">Проєкти</span> → <span class=\"ui\">Запрошення</span>). Службові листи облікового запису (підтвердження адреси, новий пароль) вимкнути не можна.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-powiadomienia.png\" alt=\"Сповіщення в налаштуваннях облікового запису\" loading=\"lazy\"><figcaption>Сповіщення в налаштуваннях облікового запису</figcaption></figure>"},{"id":"27.7","tytul":"Видалення облікового запису","html":"<p><span class=\"ui\">Налаштування облікового запису</span> → <b>Видалити обліковий запис</b> видаляє обліковий запис і всі ваші проєкти. Перш ніж це зробити, експортуйте проєкти, які хочете зберегти (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.6\">Файл проєкту</a>).</p><p class=\"ramka-instrukcji uwaga\"><b>Увага.</b> Видалення облікового запису не можна скасувати.</p>"},{"id":"27.8","tytul":"Контакт","html":"<p>Маєте запитання, ідею чи знайшли помилку? <span class=\"ui\">Контакт</span> є в меню облікового запису та під формою входу. <span class=\"ui\">Прикріпити файли</span> додає знімок екрана, файл проєкту або PDF (до 5 файлів, разом 10 МБ). Можна також написати на kontakt@makietka.app.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kontakt.png\" alt=\"Форма зворотного зв’язку з вкладенням\" loading=\"lazy\"><figcaption>Форма зворотного зв’язку з вкладенням</figcaption></figure>"},{"id":"27.9","tytul":"Бренд-кит","html":"<p>Кольори, шрифти й логотип компанії (або школи, парафії, клубу) ви зберігаєте один раз — в обліковому записі — і маєте їх у кожному проєкті: <span class=\"ui\">Налаштування облікового запису</span> → <b>Бренд-кит</b> → <span class=\"ui\">Редагувати бренд-кит…</span> (або Бібліотека → <b>Бренд</b>).</p><p><b>Кілька наборів</b> — наприклад, для кожного клієнта, школи чи видавництва. Угорі вікна бренду є список <b>Набір</b>: <span class=\"ui\">Новий набір…</span> (порожній), <span class=\"ui\">Копія…</span> (з кольорами, шрифтами, стилями й логотипом поточного), <span class=\"ui\">Перейменувати…</span>, <span class=\"ui\">Видалити</span>. Зміни в наборі зберігаються, коли ви переходите на інший. Вибір у налаштуваннях облікового запису — це <b>набір у використанні</b>: бренд проєктів, які не мають власного. Вибір при відкритому проєкті (вікно бренду з Бібліотеки або з меню ⋯) запам’ятовує проєкт: його кольори, шрифти й Бібліотека показують цей набір, а інші проєкти лишаються при своїх. Те саме робить <span class=\"ui\">Застосувати бренд до проєкту…</span> — у вікні ви вибираєте, який набір застосувати.</p><ul class=\"punkty\"><li><b>Кольори бренду</b> — з назвою, наприклад «Темно-синій бренду». Перемикач <b>Pantone / CMYK</b> робить колір додатковим (плашковим), що друкується окремою фарбою (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.1\">Додаткові кольори</a>).</li><li><b>Шрифти бренду</b> — один для заголовків, один для тексту.</li><li><b>Стилі тексту</b> — <span class=\"ui\">Додати готові стилі</span> додає Заголовок, Підзаголовок, Заголовок 1–4, Абзац, Виділений абзац, Підпис, Цитату, Список, Виноску, Нижній колонтитул / колонтитул і Етикетку у шрифтах і кольорі бренду; <span class=\"ui\">Власний стиль</span> — наступні, без обмежень. Кожен стиль має шрифт, розмір, насиченість, курсив, міжрядковий інтервал, міжлітерний інтервал, колір і регістр літер.</li><li><b>Логотип</b> — PNG, JPG, WebP або SVG; вставите його з Бібліотеки.</li></ul><figure class=\"kadr\"><img src=\"img/instrukcja/k-marka-style.png\" alt=\"Стилі тексту бренду\" loading=\"lazy\"><figcaption>Стилі тексту бренду</figcaption></figure><figure class=\"kadr\"><img src=\"img/instrukcja/k-marka.png\" alt=\"Бренд-кит\" loading=\"lazy\"><figcaption>Бренд-кит</figcaption></figure><p>Бренд завжди під рукою у вікні кольору (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.7\">Вибір кольору</a>), угорі списку шрифтів (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.8\">Шрифти</a>) і в Бібліотеці (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.8\">Бібліотека</a>).</p><ul class=\"punkty\"><li><b>вибір кольору</b> — розділ <b>Бренд</b> над «Використано в проєкті» (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.7\">Вибір кольору</a>),</li><li><b>список шрифтів</b> — група <b>Бренд</b> на самому верху (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.8\">Шрифти</a>),</li><li><b>Бібліотека</b> — категорія <b>Бренд</b>: логотип, <span class=\"ui\">Застосувати бренд до проєкту…</span> і <span class=\"ui\">Редагувати бренд-кит…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.8\">Бібліотека</a>),</li><li><span class=\"ui\">⋯</span> → <span class=\"ui\">Застосувати бренд до проєкту…</span> — заміна кольорів і шрифтів усього проєкту на брендові (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.3\">Меню ⋯</a>).</li></ul><p><b>Застосувати бренд до проєкту.</b> Вікно показує кожен колір і кожен шрифт проєкту з пропозицією: колір отримує найближчий колір бренду (чорний, білий і сірі лишаються), найчастіший шрифт — шрифт тексту, решта — шрифт заголовків. У списках можна змінити пропозицію або вибрати «без змін». Розділ <b>Стилі тексту</b> переносить стилі бренду до стилів проєкту (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.4\">Стилі</a>): стиль проєкту з тією самою назвою (наприклад, «Заголовок») отримує вигляд бренду й лишається пов’язаним зі своїми текстами — вони зміняться одразу, — а відсутні стилі додаються. <span class=\"ui\">Застосувати</span> змінює сторінки, шаблони й стилі водночас; усе це скасуєте одним <span class=\"ui\">Скасувати</span> (<kbd>Ctrl</kbd>+<kbd>Z</kbd>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-marka-zastosuj.png\" alt=\"Застосувати бренд до проєкту\" loading=\"lazy\"><figcaption>Застосувати бренд до проєкту</figcaption></figure>"}]},
  {"nr":"28","tytul":"Телефон і планшет","czesc":"Обліковий запис, пристрої та довідка","ikona":"motyw","wstep":"Як працювати на сенсорному екрані та як установити застосунок.","sekcje":[{"id":"28.1","tytul":"Жести","html":"<p>На сенсорному екрані:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Жест</th><th>Що робить</th></tr></thead><tbody><tr><td><b>Один палець</b></td><td>Виділяє й переміщує елементи.</td></tr><tr><td><b>Два пальці</b></td><td>Переміщують вигляд і масштабують.</td></tr><tr><td><b>Швидкий свайп убік</b></td><td>По порожньому місцю сторінки, коли вся сторінка вміщується на екрані: ліворуч – наступна сторінка, праворуч – попередня (у розвороті — весь розворот). Повільне перетягування виділяє рамкою, як звичайно.</td></tr><tr><td><b>Подвійний дотик</b></td><td>Як подвійне клацання: введення тексту в текстовому елементі й клітинці таблиці, вхід у групу, редагування точок.</td></tr><tr><td><b>Утримання</b></td><td>Показує підказку, наприклад опис хмаринки збереження.</td></tr></tbody></table></div><p>У попередньому перегляді зведення пальців масштабує, а в презентації свайп убік гортає сторінку (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"19\">Перегляд</a>).</p>"},{"id":"28.2","tytul":"Редактор на телефоні","html":"<p>На телефоні редактор працює у вертикальній орієнтації. Панелі <b>Сторінки</b>, <b>Властивості</b>, <b>Шари</b> і <b>Попередження</b> відкриваєте кнопками внизу екрана. Панель висувається знизу, а вигляд сам зсувається так, щоб виділений елемент було видно над панеллю.</p><p><b>Ручка</b> (риска вгорі панелі): потягніть угору, щоб збільшити панель, униз — щоб її зменшити або закрити. Дотик до ручки згортає збільшену панель до звичайної висоти, а звичайну закриває. Панель також закриває повторний дотик до її кнопки.</p><p>Рідші інструменти — багатокутник, малювання, перо, коментар, копіювання вигляду — є під <span class=\"ui\">⋯</span> у кінці панелі вставлення (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.4\">Панель вставлення</a>). Лінійок і кадрування рамкою на телефоні немає: напрямні вводите числом (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.4\">Лінійки й напрямні</a>), а зображення обрізаєте числами у властивостях (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.2\">Кадрування</a>).</p><p>Якщо тримати телефон горизонтально, з’являється екран «Замало місця по висоті» — поверніть його вертикально.</p><figure class=\"telefon\"><img src=\"img/instrukcja/telefon.png\" alt=\"Редактор на телефоні\" loading=\"lazy\"><figcaption>Редактор на телефоні</figcaption></figure>"},{"id":"28.3","tytul":"Вікна знизу","html":"<p>На телефоні й планшеті вікна (Дані, Шаблони, Експорт у PDF, Зображення проєкту та інші) висуваються знизу екрана. Замість хрестика вони мають <b>ручку</b> — потягніть її вниз або торкніться, щоб закрити; закриває також дотик до затемненого тла. Головна кнопка вікна — внизу, завжди на виду. Таку саму ручку мають списки вибору, вибір кольору й дати, які на телефоні теж висуваються знизу, — дотик поза ними або до ручки їх ховає. Маленькі меню (⋯, вигляд) розгортаються під кнопкою й ховаються після дотику поруч.</p><figure class=\"telefon\"><img src=\"img/instrukcja/telefon-zaslonka.png\" alt=\"Вікно на телефоні\" loading=\"lazy\"><figcaption>Вікно на телефоні</figcaption></figure>"},{"id":"28.4","tytul":"Установлення застосунку","html":"<p>Установлена Makietka відкривається з головного екрана, як звичайний застосунок, — на весь екран, без панелі браузера.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Пристрій</th><th>Як установити</th></tr></thead><tbody><tr><td><b>Android</b> (Chrome)</td><td><span class=\"ui\">Установити застосунок</span> у меню облікового запису або в меню браузера ⋮.</td></tr><tr><td><b>iPhone та iPad</b> (Safari)</td><td><span class=\"ui\">Установити застосунок</span> покаже кроки: <b>Поділитися → На початковий екран</b>.</td></tr><tr><td><b>Комп’ютер</b> (Chrome, Edge)</td><td>Значок установлення в адресному рядку або <span class=\"ui\">Установити застосунок</span>. У Safari на Mac: <b>Файл → Додати до Dock</b>.</td></tr></tbody></table></div><p>Установлений застосунок на комп’ютері відкриває файли <code>.makietka</code> подвійним клацанням.</p>"},{"id":"28.5","tytul":"Повний екран","html":"<p><span class=\"ui\">Повний екран</span> (чотири кути) у списку проєктів, у редакторі та в попередньому перегляді ховає панелі браузера; <kbd>Esc</kbd> або та сама кнопка повертає їх. На iPhone браузер не дозволяє повноекранного режиму — там його дає встановлення застосунку (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"28.4\">Установлення застосунку</a>).</p>"},{"id":"28.6","tytul":"Тривалі дії","html":"<p>Коли щось триває довше, ніж мить, — наприклад, відкриття великого проєкту, експорт PDF, друк удома, завантаження зображень, — угорі з’являється картка зі смугою, а коли відомо, скільки лишилося, то й з лічильником, наприклад «17 з 48». Експорт PDF можна перервати кнопкою <span class=\"ui\">Скасувати</span>. Мініатюри сторінок великого проєкту малюються у фоні (тонка смуга на панелі Сторінки) — тим часом можна працювати як звичайно.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-postep.png\" alt=\"Картка поступу під час експорту PDF\" loading=\"lazy\"><figcaption>Картка поступу під час експорту PDF</figcaption></figure>"}]},
  {"nr":"29","tytul":"Клавіатурні скорочення","czesc":"Обліковий запис, пристрої та довідка","ikona":"motyw","sekcje":[{"id":"29.1","tytul":"Список скорочень","html":"<p>На Mac замість <kbd>Ctrl</kbd> натискайте <kbd>⌘</kbd>. У редакторі цей список покаже клавіша <kbd>?</kbd>. Під час введення тексту діють лише скорочення з групи «Текст».</p><p><kbd>Ctrl</kbd>+<kbd>K</kbd> відкриває палітру команд: введіть кілька літер назви команди й натисніть <kbd>Enter</kbd>.</p><div data-wstaw=\"skroty\"></div>"}]},
  {"nr":"30","tytul":"Словничок","czesc":"Обліковий запис, пристрої та довідка","ikona":"motyw","sekcje":[{"id":"30.1","tytul":"Друк і файл для друкарні","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Поняття</th><th>Значення</th></tr></thead><tbody><tr><td><b>CMYK</b></td><td>Чотири друкарські фарби: блакитна (ціан), пурпурова (маджента), жовта, чорна. Кольори на екрані (RGB) друкарня перераховує в CMYK.</td></tr><tr><td><b>Dpi</b></td><td>Кількість точок зображення на дюйм у розмірі друку. Фото для друку має мати щонайменше 300 dpi.</td></tr><tr><td><b>Спуск смуг (імпозиція)</b></td><td>Розміщення сторінок на друкованому аркуші так, щоб після фальцювання й обрізання вони йшли в правильному порядку (наприклад, брошура).</td></tr><tr><td><b>Додатковий колір (Pantone)</b></td><td>Готова змішана фарба точного відтінку, що друкується окремо поруч із CMYK.</td></tr><tr><td><b>Оверпринт (overprint)</b></td><td>Фарба, надрукована поверх фарби під нею, без її вирізання, — важливо для чорного тексту й оздоблення.</td></tr><tr><td><b>PDF/X-4</b></td><td>Різновид PDF для друкарні: вбудовані шрифти, збережений колірний профіль, прозорість без зведення.</td></tr><tr><td><b>Покриття фарбою</b></td><td>Сума фарб CMYK в одному місці (у %). Завелике покриття (зазвичай понад 300%) призводить до того, що фарба не висихає.</td></tr><tr><td><b>Колірний профіль (ICC)</b></td><td>Опис друкарської машини й паперу друкарні; під час перерахунку в CMYK дає кольори, якомога ближчі до задуманих.</td></tr><tr><td><b>Роздільність</b></td><td>Див. Dpi.</td></tr><tr><td><b>Кольороподіл (сепарації)</b></td><td>Окремі друкарські форми для кожної фарби (C, M, Y, K, додаткові кольори, оздоблення).</td></tr><tr><td><b>Виліт (bleed)</b></td><td>Кілька міліметрів за краєм сторінки; тла й фото заходять аж туди, а друкарня це обрізає.</td></tr><tr><td><b>Примірник на аркуші</b></td><td>Один примірник дрібного виробу (візитівки, наліпки) на друкованому аркуші – на одному аркуші їх уміщується багато.</td></tr><tr><td><b>Вектор</b></td><td>Малюнок, описаний формами, а не пікселями, — чіткий за будь-якого збільшення (тексти, фігури, векторний PDF).</td></tr><tr><td><b>Мітки обрізу</b></td><td>Риски у файлі PDF, які показують друкарні, де різати.</td></tr></tbody></table></div>"},{"id":"30.2","tytul":"Оздоблення друку","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Поняття</th><th>Значення</th></tr></thead><tbody><tr><td><b>Біла підкладка</b></td><td>Шар білої фарби під кольорами — потрібен під час друку на прозорому, кольоровому чи металізованому матеріалі.</td></tr><tr><td><b>Біг, бігування</b></td><td>Продавлена лінія на картоні (наприклад, обкладинки), по якій картон згинається рівно й не тріскається.</td></tr><tr><td><b>Фальц (згин)</b></td><td>Лінія, по якій складають аркуш (наприклад, листівку втричі); на картоні перед нею роблять біг.</td></tr><tr><td><b>Вибірковий лак</b></td><td>Глянцевий лак лише на вибраних місцях сторінки, наприклад на заголовку.</td></tr><tr><td><b>Перфорація</b></td><td>Лінія дрібних надрізів, по якій легко відірвати частину аркуша, наприклад аркуш календаря.</td></tr><tr><td><b>Тиснення</b></td><td>Опуклий або заглиблений візерунок, витиснений на папері.</td></tr><tr><td><b>Тип секції</b></td><td>Чим є секція в публікації (блок, обкладинка, форзац, вклейка, листівка…) – визначає її формат, нумерацію й місце в корінці.</td></tr><tr><td><b>Оздоблення</b></td><td>Додаткова обробка друку: лак, фольгування, тиснення, біла підкладка.</td></tr><tr><td><b>Висічка (штанц)</b></td><td>Контур, по якому друкарня вирізає й бігує аркуш (конверт, коробка, наліпка); у PDF — окремий колір CutContour.</td></tr><tr><td><b>Фольгування</b></td><td>Блискуча фольга (золота, срібна, кольорова), що переноситься на папір у вибраних місцях.</td></tr></tbody></table></div>"},{"id":"30.3","tytul":"Папір і палітурка","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Поняття</th><th>Значення</th></tr></thead><tbody><tr><td><b>Книжковий блок</b></td><td>Усі аркуші внутрішньої частини книжки разом, без обкладинки.</td></tr><tr><td><b>Брошура</b></td><td>Кілька аркушів, складених навпіл і скріплених у корінці; сторінки на аркушах треба відповідно розмістити (спуск смуг).</td></tr><tr><td><b>Формат</b></td><td>Розміри сторінки після обрізання, наприклад A5 = 148 × 210 мм.</td></tr><tr><td><b>Щільність паперу</b></td><td>Товщина паперу, яку подають як масу квадратного метра (г/м²), — від неї залежить, зокрема, ширина корінця.</td></tr><tr><td><b>Корінець</b></td><td>Частина обкладинки між передом і задом; його ширина залежить від кількості сторінок і паперу. У розвороті — місце скріплення.</td></tr><tr><td><b>Капталь</b></td><td>Смужка тканини вгорі й унизу корінця блоку в твердій палітурці.</td></tr><tr><td><b>Суперобкладинка</b></td><td>Паперова обкладинка, що вдягається на тверду палітурку, з двома клапанами, загорнутими всередину (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10.11\">Спеціальні розділи: суперобкладинка, листівка, календарі, висічки, вироби</a>).</td></tr><tr><td><b>Палітурка</b></td><td>Спосіб скріплення аркушів: на скобу (скоби), клейова (м’яка обкладинка), тверда, на спіралі.</td></tr><tr><td><b>Розворот</b></td><td>Ліва й права сторінки поруч, як у розгорнутій книжці.</td></tr><tr><td><b>Зошит</b></td><td>Аркуш, складений у кілька аркушів-сторінок, — книжку шиють із зошитів по 4, 8, 16 або 32 сторінки.</td></tr><tr><td><b>Клапан</b></td><td>Частина суперобкладинки або обкладинки, загорнута всередину за кришку обкладинки.</td></tr><tr><td><b>Ляссе (закладка)</b></td><td>Вузька стрічка, вклеєна в корінець твердої палітурки, щоб позначати місце в книжці.</td></tr><tr><td><b>Вклейка</b></td><td>Аркуші на іншому папері, вшиті всередину книжки, наприклад фото на крейдованому папері, – без номерів сторінок.</td></tr><tr><td><b>Форзац</b></td><td>Аркуш, що з’єднує книжковий блок із твердою обкладинкою: половина приклеєна до внутрішнього боку обкладинки, половина — це перший (або останній) вільний аркуш.</td></tr></tbody></table></div>"},{"id":"30.4","tytul":"Текст і типографіка","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Поняття</th><th>Значення</th></tr></thead><tbody><tr><td><b>Міжрядковий інтервал</b></td><td>Відстань між сусідніми рядками тексту.</td></tr><tr><td><b>Вирівнювання за шириною</b></td><td>Вирівнювання тексту по обох краях рамки — рядки мають однакову довжину.</td></tr><tr><td><b>Базова лінія</b></td><td>Невидима лінія, на якій «стоять» літери. Сітка базових ліній вирівнює рядки в сусідніх колонках і на сторінках.</td></tr><tr><td><b>Поле</b></td><td>Смуга біля краю сторінки, на якій не розміщують текст.</td></tr><tr><td><b>Стиль</b></td><td>Збережений вигляд тексту, що змінюється одразу в усіх текстах.</td></tr><tr><td><b>Висячий рядок</b></td><td>Одинокий рядок абзацу, що залишився сам у кінці або на початку колонки чи сторінки.</td></tr><tr><td><b>Колонтитул</b></td><td>Текст угорі або внизу сторінки, що повторюється на багатьох сторінках, наприклад назва розділу.</td></tr></tbody></table></div>"},{"id":"30.5","tytul":"Редагування й інструменти","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Поняття</th><th>Значення</th></tr></thead><tbody><tr><td><b>Елемент</b></td><td>Усе, що розміщено на сторінці: текст, фігура, лінія, зображення, таблиця, група.</td></tr><tr><td><b>Градієнт (перехід)</b></td><td>Плавний перехід між кольорами в заливці, зокрема до прозорості.</td></tr><tr><td><b>Кадрування</b></td><td>Вибір частини фото, яку видно в рамці.</td></tr><tr><td><b>Непрозорість</b></td><td>Прозорість елемента або кольору: 100% — повністю видимий, 0% — невидимий.</td></tr><tr><td><b>Макет</b></td><td>Проєкт публікації сторінка за сторінкою; 3D-макет — попередній перегляд надрукованого виробу (книжки, календаря).</td></tr><tr><td><b>М’які краї</b></td><td>Край фото чи фігури, що плавно переходить у прозорість.</td></tr><tr><td><b>Напрямна</b></td><td>Допоміжна лінія на сторінці для вирівнювання елементів; не друкується.</td></tr></tbody></table></div>"},{"id":"30.6","tytul":"Проєкт і дані","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Поняття</th><th>Значення</th></tr></thead><tbody><tr><td><b>Блок (серії)</b></td><td>Сторінка або кілька сусідніх сторінок серії, що повторюються разом.</td></tr><tr><td><b>Поле даних</b></td><td>Назва у фігурних дужках, наприклад <code>{dzien}</code>; на готовій сторінці вона перетворюється на значення.</td></tr><tr><td><b>Поле документа</b></td><td>Поле, що випливає з проєкту: номер сторінки, секція, дата.</td></tr><tr><td><b>Секція</b></td><td>Частина публікації з власним форматом, полями й нумерацією, наприклад обкладинка та внутрішній блок.</td></tr><tr><td><b>Серія</b></td><td>Повторення сторінки або блоку для наступних рядків таблиці.</td></tr><tr><td><b>Таблиця даних</b></td><td>Аркуш у проєкті, з якого беруться значення полів і серії, — не плутати з таблицею на сторінці.</td></tr><tr><td><b>Пропущений рядок</b></td><td>Рядок <code>[пропустити]</code>: займає місце в блоці, але його сторінка не створюється.</td></tr><tr><td><b>Шаблон сторінки</b></td><td>Спільні елементи багатьох сторінок: тло, нижній колонтитул, номер сторінки.</td></tr></tbody></table></div>"},{"id":"30.7","tytul":"AI","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Поняття</th><th>Значення</th></tr></thead><tbody><tr><td><b>AI-асистент</b></td><td>Програма для розмови (наприклад, Claude, ChatGPT), яка після підключення конектора читає й змінює ваші проєкти (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.1\">Що вміє ШІ</a>).</td></tr><tr><td><b>Ключ для AI</b></td><td>Дозвіл для асистента: до яких проєктів він має доступ, чи може лише читати і як довго ключ дійсний (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.2\">Ключ для ШІ</a>).</td></tr><tr><td><b>Конектор</b></td><td>Адреса з вашим ключем, через яку AI-асистент працює у ваших проєктах. Її видно лише раз, під час створення ключа.</td></tr><tr><td><b>Обсяг ключа</b></td><td>Вибрані проєкти або повний доступ до всіх, зокрема створення й видалення проєктів.</td></tr></tbody></table></div>"}]},
];
